#[derive(Debug, Clone, Copy)]
enum NativeTextSurface {
    FunctionName,
    ExtensionName,
}

impl NativeTextSurface {
    fn surface_tag(self) -> u8 {
        match self {
            Self::FunctionName => 4,
            Self::ExtensionName => 6,
        }
    }
}
