fn native_array_key_exists_builtin(name: &str, args: &[Expr]) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "array_key_exists" | "key_exists"
    ) && args.len() == 2
}

fn native_value_comparison_op_tag(op: BinaryOp) -> Option<&'static str> {
    match op {
        BinaryOp::Eq => Some("PHPC_NATIVE_VALUE_COMPARISON_EQ"),
        BinaryOp::Ne => Some("PHPC_NATIVE_VALUE_COMPARISON_NE"),
        BinaryOp::Lt => Some("PHPC_NATIVE_VALUE_COMPARISON_LT"),
        BinaryOp::Le => Some("PHPC_NATIVE_VALUE_COMPARISON_LE"),
        BinaryOp::Gt => Some("PHPC_NATIVE_VALUE_COMPARISON_GT"),
        BinaryOp::Ge => Some("PHPC_NATIVE_VALUE_COMPARISON_GE"),
        BinaryOp::StrictEq => Some("PHPC_NATIVE_VALUE_COMPARISON_STRICT_EQ"),
        BinaryOp::StrictNe => Some("PHPC_NATIVE_VALUE_COMPARISON_STRICT_NE"),
        BinaryOp::Spaceship => None,
        BinaryOp::Add
        | BinaryOp::Sub
        | BinaryOp::Mul
        | BinaryOp::Div
        | BinaryOp::Mod
        | BinaryOp::Concat
        | BinaryOp::NullCoalesce
        | BinaryOp::LogicalAnd
        | BinaryOp::LogicalOr
        | BinaryOp::LogicalXor
        | BinaryOp::BitwiseAnd
        | BinaryOp::BitwiseOr
        | BinaryOp::BitwiseXor
        | BinaryOp::ShiftLeft
        | BinaryOp::ShiftRight => None,
    }
}

fn native_value_comparison_op_tag_value(op: BinaryOp) -> Option<u8> {
    match op {
        BinaryOp::Eq => Some(0),
        BinaryOp::Ne => Some(1),
        BinaryOp::Lt => Some(2),
        BinaryOp::Le => Some(3),
        BinaryOp::Gt => Some(4),
        BinaryOp::Ge => Some(5),
        BinaryOp::StrictEq => Some(6),
        BinaryOp::StrictNe => Some(7),
        BinaryOp::Spaceship => None,
        BinaryOp::Add
        | BinaryOp::Sub
        | BinaryOp::Mul
        | BinaryOp::Div
        | BinaryOp::Mod
        | BinaryOp::Concat
        | BinaryOp::NullCoalesce
        | BinaryOp::LogicalAnd
        | BinaryOp::LogicalOr
        | BinaryOp::LogicalXor
        | BinaryOp::BitwiseAnd
        | BinaryOp::BitwiseOr
        | BinaryOp::BitwiseXor
        | BinaryOp::ShiftLeft
        | BinaryOp::ShiftRight => None,
    }
}

fn native_value_non_strict_comparison_op_tag(op: BinaryOp) -> Option<&'static str> {
    match op {
        BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
            native_value_comparison_op_tag(op)
        }
        BinaryOp::StrictEq
        | BinaryOp::StrictNe
        | BinaryOp::Spaceship
        | BinaryOp::Add
        | BinaryOp::Sub
        | BinaryOp::Mul
        | BinaryOp::Div
        | BinaryOp::Mod
        | BinaryOp::Concat
        | BinaryOp::NullCoalesce
        | BinaryOp::LogicalAnd
        | BinaryOp::LogicalOr
        | BinaryOp::LogicalXor
        | BinaryOp::BitwiseAnd
        | BinaryOp::BitwiseOr
        | BinaryOp::BitwiseXor
        | BinaryOp::ShiftLeft
        | BinaryOp::ShiftRight => None,
    }
}

fn native_value_non_strict_comparison_expr(expr: &Expr) -> bool {
    matches!(
        expr,
        Expr::Binary { op, .. } if native_value_non_strict_comparison_op_tag(*op).is_some()
    )
}

fn native_string_search_result_expr(expr: &Expr) -> bool {
    matches!(
        expr,
        Expr::Call { name, .. } if native_string_search_operation_for_name(name).is_some()
    )
}

fn native_value_result_output_expr(expr: &Expr) -> bool {
    match expr {
        Expr::Index { .. } => true,
        Expr::Property { .. } => true,
        Expr::CompoundAssign { .. } => true,
        Expr::NullCoalesceAssign { .. } => true,
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => native_value_ternary_needs_lazy_materialization(condition, if_true, if_false),
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => native_value_short_ternary_needs_lazy_materialization(condition, if_false),
        Expr::Unary { op, .. } => native_value_unary_op_tag(*op).is_some(),
        Expr::Binary { op, .. } => {
            native_value_binary_op_tag(*op).is_some() || matches!(op, BinaryOp::NullCoalesce)
        }
        Expr::Cast { .. } => true,
        Expr::Call { name, args, .. } => {
            native_value_cast_builtin_op_tag(name).is_some()
                || native_value_type_name_tag(name).is_some()
                || native_string_result_operation_for_name(name).is_some()
                || native_string_search_operation_for_name(name).is_some()
                || native_array_pointer_builtin(name, args).is_some()
                || native_array_mutation_builtin(name, args).is_some()
                || native_value_array_callback_builtin(name, args).is_some()
                || native_value_array_query_builtin(name, args).is_some()
                || native_output_buffer_operation_for_call(name).is_some()
        }
        _ => false,
    }
}

fn native_value_strict_identity_operand_needs_materialization(expr: &Expr) -> bool {
    match expr {
        Expr::CompoundAssign { .. }
        | Expr::NullCoalesceAssign { .. }
        | Expr::IncrementDecrement { .. }
        | Expr::Cast { .. } => true,
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => native_value_ternary_needs_lazy_materialization(condition, if_true, if_false),
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => native_value_short_ternary_needs_lazy_materialization(condition, if_false),
        Expr::Unary { op, .. } => native_value_unary_op_tag(*op).is_some(),
        Expr::Binary { op, .. } => {
            native_value_binary_op_tag(*op).is_some()
                || native_value_bitwise_binary_op_tag(*op).is_some()
                || native_value_comparison_op_tag(*op).is_some()
        }
        Expr::Call { name, args, .. } => {
            native_value_cast_builtin_op_tag(name).is_some()
                || native_value_type_name_tag(name).is_some()
                || native_string_result_operation_for_name(name).is_some()
                || native_string_search_operation_for_name(name).is_some()
                || native_array_pointer_builtin(name, args).is_some()
                || native_array_mutation_builtin(name, args).is_some()
                || native_value_array_callback_builtin(name, args).is_some()
                || native_value_array_query_builtin(name, args).is_some()
        }
        _ => false,
    }
}

fn native_value_strict_identity_needs_materialization(left: &Expr, right: &Expr) -> bool {
    native_value_strict_identity_operand_needs_materialization(left)
        || native_value_strict_identity_operand_needs_materialization(right)
}

fn native_conditional_rhs_needs_cleanup_boundary(expr: &Expr) -> bool {
    match expr {
        Expr::Array { .. }
        | Expr::Assign { .. }
        | Expr::CompoundAssign { .. }
        | Expr::NullCoalesceAssign { .. }
        | Expr::IncrementDecrement { .. }
        | Expr::Ternary { .. }
        | Expr::ShortTernary { .. }
        | Expr::Match { .. } => true,
        Expr::Index { target, index, .. } => {
            native_conditional_rhs_needs_cleanup_boundary(target)
                || native_conditional_rhs_needs_cleanup_boundary(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => native_conditional_rhs_needs_cleanup_boundary(target),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            native_conditional_rhs_needs_cleanup_boundary(target)
                || new_class_name_conditional_rhs_needs_cleanup_boundary(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => {
            native_conditional_rhs_needs_cleanup_boundary(target)
                || native_conditional_rhs_needs_cleanup_boundary(property)
        }
        Expr::Binary { left, right, .. } => {
            native_conditional_rhs_needs_cleanup_boundary(left)
                || native_conditional_rhs_needs_cleanup_boundary(right)
        }
        Expr::Call { args, .. } => args
            .iter()
            .any(native_conditional_rhs_needs_cleanup_boundary),
        Expr::DynamicCall { callee, args, .. } => {
            native_conditional_rhs_needs_cleanup_boundary(callee)
                || args
                    .iter()
                    .any(native_conditional_rhs_needs_cleanup_boundary)
        }
        Expr::New { args, .. } => args
            .iter()
            .any(native_conditional_rhs_needs_cleanup_boundary),
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            native_conditional_rhs_needs_cleanup_boundary(expr)
        }
        Expr::Closure { .. } => true,
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::InterpolatedString { .. }
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. }
        | Expr::MethodCall { .. }
        | Expr::DynamicMethodCall { .. }
        | Expr::ParentMethodCall { .. }
        | Expr::StaticMethodCall { .. }
        | Expr::ObjectStaticMethodCall { .. }
        | Expr::SelfMethodCall { .. }
        | Expr::LateStaticMethodCall { .. } => false,
    }
}

fn new_class_name_conditional_rhs_needs_cleanup_boundary(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicExpression(expr) => {
            native_conditional_rhs_needs_cleanup_boundary(expr)
        }
        NewClassName::Named(_)
        | NewClassName::DynamicVariable(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn native_value_ternary_needs_lazy_materialization(
    condition: &Expr,
    if_true: &Expr,
    if_false: &Expr,
) -> bool {
    native_value_result_output_expr(condition)
        || native_value_result_output_expr(if_true)
        || native_value_result_output_expr(if_false)
        || native_conditional_rhs_needs_cleanup_boundary(if_true)
        || native_conditional_rhs_needs_cleanup_boundary(if_false)
}

fn native_value_short_ternary_needs_lazy_materialization(
    condition: &Expr,
    if_false: &Expr,
) -> bool {
    native_value_result_output_expr(condition)
        || native_value_result_output_expr(if_false)
        || native_conditional_rhs_needs_cleanup_boundary(condition)
        || native_conditional_rhs_needs_cleanup_boundary(if_false)
}

fn native_value_cast_op_tag(kind: CastKind) -> &'static str {
    match kind {
        CastKind::String => "PHPC_NATIVE_VALUE_CAST_STRING",
        CastKind::Int => "PHPC_NATIVE_VALUE_CAST_INT",
        CastKind::Bool => "PHPC_NATIVE_VALUE_CAST_BOOL",
        CastKind::Float => "PHPC_NATIVE_VALUE_CAST_FLOAT",
        CastKind::Array => "PHPC_NATIVE_VALUE_CAST_ARRAY",
        CastKind::Object => "PHPC_NATIVE_VALUE_CAST_OBJECT",
    }
}

fn native_value_cast_builtin_op_tag(name: &str) -> Option<&'static str> {
    match name.to_ascii_lowercase().as_str() {
        "strval" => Some("PHPC_NATIVE_VALUE_CAST_STRING"),
        "boolval" => Some("PHPC_NATIVE_VALUE_CAST_BOOL"),
        "floatval" | "doubleval" => Some("PHPC_NATIVE_VALUE_CAST_FLOAT"),
        _ => None,
    }
}

fn native_value_type_name_tag(name: &str) -> Option<&'static str> {
    match name.to_ascii_lowercase().as_str() {
        "gettype" => Some("PHPC_NATIVE_VALUE_TYPE_NAME_GETTYPE"),
        "get_debug_type" => Some("PHPC_NATIVE_VALUE_TYPE_NAME_DEBUG"),
        _ => None,
    }
}

fn native_value_type_predicate_tag(name: &str) -> Option<&'static str> {
    match name.to_ascii_lowercase().as_str() {
        "is_null" => Some("PHPC_NATIVE_VALUE_TYPE_IS_NULL"),
        "is_bool" => Some("PHPC_NATIVE_VALUE_TYPE_IS_BOOL"),
        "is_int" | "is_integer" | "is_long" => Some("PHPC_NATIVE_VALUE_TYPE_IS_INT"),
        "is_float" | "is_double" => Some("PHPC_NATIVE_VALUE_TYPE_IS_FLOAT"),
        "is_string" => Some("PHPC_NATIVE_VALUE_TYPE_IS_STRING"),
        "is_array" => Some("PHPC_NATIVE_VALUE_TYPE_IS_ARRAY"),
        "is_scalar" => Some("PHPC_NATIVE_VALUE_TYPE_IS_SCALAR"),
        "is_numeric" => Some("PHPC_NATIVE_VALUE_TYPE_IS_NUMERIC"),
        "is_countable" => Some("PHPC_NATIVE_VALUE_TYPE_IS_COUNTABLE"),
        "is_iterable" => Some("PHPC_NATIVE_VALUE_TYPE_IS_ITERABLE"),
        "is_object" => Some("PHPC_NATIVE_VALUE_TYPE_IS_OBJECT"),
        "is_resource" => Some("PHPC_NATIVE_VALUE_TYPE_IS_RESOURCE"),
        _ => None,
    }
}

fn native_value_type_predicate_abi_value(predicate_tag: &str) -> &'static str {
    match predicate_tag {
        "PHPC_NATIVE_VALUE_TYPE_IS_NULL" => "0",
        "PHPC_NATIVE_VALUE_TYPE_IS_BOOL" => "1",
        "PHPC_NATIVE_VALUE_TYPE_IS_INT" => "2",
        "PHPC_NATIVE_VALUE_TYPE_IS_FLOAT" => "3",
        "PHPC_NATIVE_VALUE_TYPE_IS_STRING" => "4",
        "PHPC_NATIVE_VALUE_TYPE_IS_ARRAY" => "5",
        "PHPC_NATIVE_VALUE_TYPE_IS_SCALAR" => "6",
        "PHPC_NATIVE_VALUE_TYPE_IS_NUMERIC" => "7",
        "PHPC_NATIVE_VALUE_TYPE_IS_COUNTABLE" => "8",
        "PHPC_NATIVE_VALUE_TYPE_IS_ITERABLE" => "9",
        "PHPC_NATIVE_VALUE_TYPE_IS_OBJECT" => "10",
        "PHPC_NATIVE_VALUE_TYPE_IS_RESOURCE" => "11",
        _ => "255",
    }
}

fn native_value_result_expr_call_operation(
    expr: &Expr,
    blocker: NativeCallBlocker,
) -> Option<NativeCallOperation> {
    match expr {
        Expr::Unary { op, expr, .. } if native_value_unary_op_tag(*op).is_some() => {
            native_value_result_expr_call_operation(expr, blocker)
        }
        Expr::Binary {
            left, op, right, ..
        } if native_value_binary_op_tag(*op).is_some()
            || native_value_comparison_op_tag(*op).is_some() =>
        {
            native_value_result_expr_call_operation(left, blocker)
                .or_else(|| native_value_result_expr_call_operation(right, blocker))
        }
        Expr::Cast { expr, .. } => native_value_result_expr_call_operation(expr, blocker),
        Expr::Call { name, args, span } if native_value_cast_builtin_op_tag(name).is_some() => {
            let [arg] = args.as_slice() else {
                return Some(NativeCallOperation::direct_named_value(*span, blocker));
            };
            native_value_result_expr_call_operation(arg, blocker)
        }
        Expr::Call { name, args, span } if native_value_type_name_tag(name).is_some() => {
            let [arg] = args.as_slice() else {
                return Some(NativeCallOperation::direct_named_value(*span, blocker));
            };
            native_value_result_expr_call_operation(arg, blocker)
        }
        Expr::Call { name, args, span }
            if native_string_result_operation_for_name(name).is_some() =>
        {
            let [arg] = args.as_slice() else {
                return Some(NativeCallOperation::direct_named_value(*span, blocker));
            };
            native_value_result_expr_call_operation(arg, blocker)
        }
        Expr::Call { name, args, span } if native_array_pointer_builtin(name, args).is_some() => {
            let [arg] = args.as_slice() else {
                return Some(NativeCallOperation::direct_named_value(*span, blocker));
            };
            native_value_result_expr_call_operation(arg, blocker)
        }
        Expr::Call { name, args, .. } if native_array_sort_builtin(name, args).is_some() => args
            .iter()
            .find_map(|arg| native_value_result_expr_call_operation(arg, blocker)),
        Expr::Call { name, args, .. } if native_array_mutation_builtin(name, args).is_some() => {
            args.iter()
                .find_map(|arg| native_value_result_expr_call_operation(arg, blocker))
        }
        Expr::Call { name, args, .. }
            if native_value_array_callback_builtin(name, args).is_some() =>
        {
            args.iter()
                .find_map(|arg| native_value_result_expr_call_operation(arg, blocker))
        }
        Expr::Call { name, args, .. } if native_value_array_query_builtin(name, args).is_some() => {
            args.iter()
                .find_map(|arg| native_value_result_expr_call_operation(arg, blocker))
        }
        _ => native_expr_call_result_operation(expr, blocker),
    }
}

fn native_statement_assignment_rhs_call_operation(
    target: &AssignTarget,
    expr: &Expr,
) -> Option<NativeCallOperation> {
    match target {
        AssignTarget::Variable { .. } => None,
        target if native_array_append_assignment_target_materializes_rhs_value(target) => None,
        target if is_object_public_property_assign_target(target) => None,
        target if direct_property_held_arrayaccess_assignment_target_is_lowerable(target) => None,
        _ => native_value_result_expr_call_operation(
            expr,
            NativeCallBlocker::StatementOperandEvaluationCleanup,
        ),
    }
}

fn native_array_append_assignment_target_materializes_rhs_value(target: &AssignTarget) -> bool {
    matches!(
        target,
        AssignTarget::ArrayIndex { index: None, .. } | AssignTarget::NestedArrayAppend { .. }
    )
}

fn direct_property_held_arrayaccess_assignment_target_is_lowerable(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::DynamicObjectPropertyArrayIndex { indices, .. } => indices.len() == 1,
        AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::DynamicObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => indices.is_empty() && suffix_indices.is_empty(),
        _ => false,
    }
}

fn native_statement_operand_call_operation(stmt: &Stmt) -> Option<NativeCallOperation> {
    match stmt {
        Stmt::If { condition, .. }
        | Stmt::While { condition, .. }
        | Stmt::DoWhile { condition, .. } => {
            native_statement_operand_call_result_operation(condition)
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            ..
        } => native_for_action_list_call_operation(initializers)
            .or_else(|| {
                conditions
                    .iter()
                    .find_map(native_statement_operand_call_result_operation)
            })
            .or_else(|| native_for_action_list_call_operation(increments)),
        Stmt::Switch { value, cases, .. } => native_statement_operand_call_result_operation(value)
            .or_else(|| {
                cases
                    .iter()
                    .filter_map(|case| case.condition.as_ref())
                    .find_map(native_statement_operand_call_result_operation)
            }),
        Stmt::Foreach { iterable, .. } => native_statement_operand_call_result_operation(iterable),
        Stmt::Assign { target, expr, .. } if is_object_public_property_assign_target(target) => {
            native_statement_assignment_rhs_call_operation(target, expr)
        }
        Stmt::Assign { target, expr, .. } => native_assignment_target_call_operation(target)
            .or_else(|| native_statement_assignment_rhs_call_operation(target, expr)),
        Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            native_rmw_assignment_target_call_operation(target)
                .or_else(|| native_statement_operand_call_result_operation(expr))
        }
        Stmt::IncrementDecrement { target, .. } => {
            native_rmw_assignment_target_call_operation(target)
        }
        Stmt::ConstDeclaration { declarations, .. } => {
            declarations.iter().find_map(|declaration| {
                native_statement_operand_call_result_operation(&declaration.value)
            })
        }
        Stmt::Require { path, .. } | Stmt::Include { path, .. } => {
            native_statement_operand_call_result_operation(path)
        }
        Stmt::Return {
            value: Some(value), ..
        } => native_statement_operand_call_result_operation(value),
        Stmt::Throw { expr, .. } => native_statement_operand_call_result_operation(expr),
        Stmt::StaticLocal { declarations, .. } => declarations
            .iter()
            .filter_map(|declaration| declaration.default.as_ref())
            .find_map(native_statement_operand_call_result_operation),
        Stmt::ReferenceAssign { target, source, .. } => {
            native_reference_assignment_call_operation(target, source)
        }
        Stmt::UnsetArrayIndex { index, .. } => native_lvalue_operand_call_result_operation(index),
        Stmt::UnsetNestedArrayIndex { indices, .. } => {
            native_expr_list_call_result_operation(indices)
        }
        Stmt::UnsetDynamicObjectProperty { property, .. } => {
            native_lvalue_operand_call_result_operation(property)
        }
        Stmt::UnsetMany { targets, .. } => {
            targets.iter().find_map(native_unset_target_call_operation)
        }
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => native_try_body_call_operation(body, catches, finally_body.as_deref()),
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Echo { .. }
        | Stmt::Print { .. }
        | Stmt::Expr { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::UnsetVariable { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Return { value: None, .. }
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::Global { .. } => None,
    }
}

fn native_try_body_call_operation(
    body: &[Stmt],
    catches: &[CatchClause],
    finally_body: Option<&[Stmt]>,
) -> Option<NativeCallOperation> {
    native_try_stmt_list_call_operation(body)
        .or_else(|| {
            catches
                .iter()
                .find_map(|catch| native_try_stmt_list_call_operation(&catch.body))
        })
        .or_else(|| finally_body.and_then(native_try_stmt_list_call_operation))
}

fn native_try_stmt_list_call_operation(statements: &[Stmt]) -> Option<NativeCallOperation> {
    statements.iter().find_map(native_try_stmt_call_operation)
}

fn native_try_stmt_call_operation(stmt: &Stmt) -> Option<NativeCallOperation> {
    match stmt {
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => native_try_body_call_operation(body, catches, finally_body.as_deref()),
        _ => native_statement_operand_call_operation(stmt).or_else(|| match stmt {
            Stmt::Echo { exprs, .. } => {
                native_unemitted_statement_operand_list_call_operation(exprs)
            }
            Stmt::Print { expr, .. } | Stmt::Expr { expr, .. } => {
                native_unemitted_statement_operand_call_operation(expr)
            }
            Stmt::Assign { expr, .. } => native_unemitted_statement_operand_call_operation(expr),
            Stmt::If {
                then_branch,
                else_branch,
                ..
            } => native_try_stmt_list_call_operation(then_branch)
                .or_else(|| native_try_stmt_list_call_operation(else_branch)),
            Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::Foreach { body, .. } => {
                native_try_stmt_list_call_operation(body)
            }
            Stmt::For { body, .. } => native_try_stmt_list_call_operation(body),
            Stmt::Switch { cases, .. } => cases
                .iter()
                .find_map(|case| native_try_stmt_list_call_operation(&case.body)),
            Stmt::Namespace { .. }
            | Stmt::Use { .. }
            | Stmt::ReferenceAssign { .. }
            | Stmt::CompoundAssign { .. }
            | Stmt::IncrementDecrement { .. }
            | Stmt::NullCoalesceAssign { .. }
            | Stmt::Goto { .. }
            | Stmt::Label { .. }
            | Stmt::UnsetVariable { .. }
            | Stmt::UnsetArrayIndex { .. }
            | Stmt::UnsetNestedArrayIndex { .. }
            | Stmt::UnsetObjectProperty { .. }
            | Stmt::UnsetDynamicObjectProperty { .. }
            | Stmt::UnsetStaticProperty { .. }
            | Stmt::UnsetSelfStaticProperty { .. }
            | Stmt::UnsetParentStaticProperty { .. }
            | Stmt::UnsetLateStaticProperty { .. }
            | Stmt::UnsetMany { .. }
            | Stmt::ConstDeclaration { .. }
            | Stmt::Require { .. }
            | Stmt::Include { .. }
            | Stmt::Function(_)
            | Stmt::Interface(_)
            | Stmt::Trait(_)
            | Stmt::Enum(_)
            | Stmt::Class(_)
            | Stmt::Return { .. }
            | Stmt::Throw { .. }
            | Stmt::Try { .. }
            | Stmt::Break { .. }
            | Stmt::Continue { .. }
            | Stmt::Global { .. }
            | Stmt::StaticLocal { .. } => None,
        }),
    }
}

#[derive(Clone, Copy)]
struct NativeControlFlowCleanupRequirementOptions {
    allow_return: bool,
    allow_loop_transfer: bool,
    allow_request_scope_throw_transfer: bool,
    include_call_operations: bool,
}

impl NativeControlFlowCleanupRequirementOptions {
    fn blocked_transfers() -> Self {
        Self {
            allow_return: false,
            allow_loop_transfer: false,
            allow_request_scope_throw_transfer: false,
            include_call_operations: true,
        }
    }

    fn allow_return_and_loop_transfer() -> Self {
        Self {
            allow_return: true,
            allow_loop_transfer: true,
            allow_request_scope_throw_transfer: false,
            include_call_operations: true,
        }
    }

    fn allow_return_loop_and_request_scope_throw_transfer() -> Self {
        Self {
            allow_return: true,
            allow_loop_transfer: true,
            allow_request_scope_throw_transfer: true,
            include_call_operations: true,
        }
    }

    fn frame_body_cleanup_only() -> Self {
        Self {
            allow_return: true,
            allow_loop_transfer: true,
            allow_request_scope_throw_transfer: false,
            include_call_operations: false,
        }
    }
}

fn native_control_flow_operand_list_is_blocked(
    requirements: &[NativeDiagnosticOperandRequirement],
) -> bool {
    native_diagnostic_operation_list_is_blocked(
        PHPC_NATIVE_DIAGNOSTIC_OPERATION_CONTROL_FLOW_OPERAND_LIST,
        requirements,
    )
}

fn native_control_flow_cleanup_requirements<F>(
    statements: &[Stmt],
    options: NativeControlFlowCleanupRequirementOptions,
    expr_requires_destructor_cleanup: &F,
) -> Vec<NativeDiagnosticOperandRequirement>
where
    F: Fn(&Expr) -> bool,
{
    let mut requirements = Vec::new();
    for (operand_index, stmt) in statements.iter().enumerate() {
        native_stmt_control_flow_cleanup_requirements(
            stmt,
            options,
            operand_index,
            expr_requires_destructor_cleanup,
            &mut requirements,
        );
    }
    requirements
}

fn push_native_control_flow_requirement(
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
    tag: u8,
    operand_index: usize,
) {
    if !requirements
        .iter()
        .any(|requirement| requirement.tag == tag && requirement.operand_index == operand_index)
    {
        requirements.push(NativeDiagnosticOperandRequirement { tag, operand_index });
    }
}

fn native_call_blocker_operand_requirement_tag(blocker: NativeCallBlocker) -> u8 {
    match blocker {
        NativeCallBlocker::DynamicCallableEvaluation => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_DYNAMIC_CALLABLE_EVALUATION
        }
        NativeCallBlocker::ArgumentEvaluationCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_ARGUMENT_EVALUATION_CLEANUP
        }
        NativeCallBlocker::StatementOperandEvaluationCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP
        }
        NativeCallBlocker::ValueOperandEvaluationCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_VALUE_EVALUATION_CLEANUP
        }
        NativeCallBlocker::LvalueOperandEvaluationCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_LVALUE_EVALUATION_CLEANUP
        }
        NativeCallBlocker::RmwLvalueOperandEvaluationCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_RMW_LVALUE_EVALUATION_CLEANUP
        }
        NativeCallBlocker::ReturnValueOwnership => PHPC_NATIVE_DIAGNOSTIC_OPERAND_RESULT_OWNERSHIP,
        NativeCallBlocker::ByReferenceArgumentBinding => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_BY_REFERENCE_ARGUMENT_BINDING
        }
        NativeCallBlocker::FunctionFrameHandoff | NativeCallBlocker::ClosureFrameHandoff => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_FRAME_HANDOFF
        }
        NativeCallBlocker::GlobalFrameSeparation => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_GLOBAL_FRAME_SEPARATION
        }
        NativeCallBlocker::UnknownCalleeDiagnostics => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_UNKNOWN_CALLEE_DIAGNOSTICS
        }
        NativeCallBlocker::MethodDispatch => PHPC_NATIVE_DIAGNOSTIC_OPERAND_METHOD_DISPATCH,
        NativeCallBlocker::ConstructorDispatch => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_CONSTRUCTOR_DISPATCH
        }
        NativeCallBlocker::DestructorObservableCleanup => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_DESTRUCTOR_OBSERVABLE_CLEANUP
        }
        NativeCallBlocker::ReferenceBinding => {
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_REFERENCE_TARGET_BINDING
        }
    }
}

fn push_native_control_flow_call_operation_requirement(
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
    operation: NativeCallOperation,
    operand_index: usize,
) {
    push_native_control_flow_requirement(
        requirements,
        native_call_blocker_operand_requirement_tag(operation.blocker),
        operand_index,
    );
}

fn native_control_flow_requirements_include_call_operation(
    requirements: &[NativeDiagnosticOperandRequirement],
    operation: NativeCallOperation,
) -> bool {
    let tag = native_call_blocker_operand_requirement_tag(operation.blocker);
    requirements
        .iter()
        .any(|requirement| requirement.tag == tag)
}

fn push_native_control_flow_expr_requirements<F>(
    expr: &Expr,
    operand_index: usize,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    if expr_contains_exit_construct(expr) {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
            operand_index,
        );
    }
    if expr_requires_destructor_cleanup(expr) {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_DESTRUCTOR_OBSERVABLE_CLEANUP,
            operand_index,
        );
    }
}

fn push_native_control_flow_assign_target_requirements<F>(
    target: &AssignTarget,
    operand_index: usize,
    include_call_operations: bool,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    if assign_target_contains_exit_construct(target) {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
            operand_index,
        );
    }
    if include_call_operations {
        if let Some(operation) = native_assignment_target_call_operation(target) {
            push_native_control_flow_call_operation_requirement(
                requirements,
                operation,
                operand_index,
            );
        }
    }
    if assign_target_contains_destructor_observable_cleanup(
        target,
        expr_requires_destructor_cleanup,
    ) {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_DESTRUCTOR_OBSERVABLE_CLEANUP,
            operand_index,
        );
    }
}

fn push_native_control_flow_unset_target_requirements<F>(
    target: &UnsetTarget,
    operand_index: usize,
    include_call_operations: bool,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    if unset_target_contains_exit_construct(target) {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
            operand_index,
        );
    }
    if include_call_operations {
        if let Some(operation) = native_unset_target_call_operation(target) {
            push_native_control_flow_call_operation_requirement(
                requirements,
                operation,
                operand_index,
            );
        }
    }
    if unset_target_contains_destructor_observable_cleanup(target, expr_requires_destructor_cleanup)
    {
        push_native_control_flow_requirement(
            requirements,
            PHPC_NATIVE_DIAGNOSTIC_OPERAND_DESTRUCTOR_OBSERVABLE_CLEANUP,
            operand_index,
        );
    }
}

fn native_stmt_control_flow_cleanup_requirements<F>(
    stmt: &Stmt,
    options: NativeControlFlowCleanupRequirementOptions,
    operand_index: usize,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    match stmt {
        Stmt::Return { value, .. } => {
            if !options.allow_return {
                push_native_control_flow_requirement(
                    requirements,
                    PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
                    operand_index,
                );
            }
            if let Some(value) = value {
                push_native_control_flow_expr_requirements(
                    value,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
                if options.include_call_operations {
                    if let Some(operation) = native_statement_operand_call_result_operation(value) {
                        push_native_control_flow_call_operation_requirement(
                            requirements,
                            operation,
                            operand_index,
                        );
                    }
                }
            }
        }
        Stmt::Throw { expr, .. } => {
            if !options.allow_request_scope_throw_transfer {
                push_native_control_flow_requirement(
                    requirements,
                    PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
                    operand_index,
                );
                push_native_control_flow_expr_requirements(
                    expr,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
                if options.include_call_operations {
                    if let Some(operation) = native_statement_operand_call_result_operation(expr) {
                        push_native_control_flow_call_operation_requirement(
                            requirements,
                            operation,
                            operand_index,
                        );
                    }
                }
            }
        }
        Stmt::Goto { .. } => {
            push_native_control_flow_requirement(
                requirements,
                PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
                operand_index,
            );
        }
        Stmt::Break { .. } | Stmt::Continue { .. } => {
            if !options.allow_loop_transfer {
                push_native_control_flow_requirement(
                    requirements,
                    PHPC_NATIVE_DIAGNOSTIC_OPERAND_STATEMENT_EVALUATION_CLEANUP,
                    operand_index,
                );
            }
        }
        Stmt::Echo { exprs, .. } => {
            for expr in exprs {
                push_native_control_flow_expr_requirements(
                    expr,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
        }
        Stmt::Print { expr, .. } | Stmt::Expr { expr, .. } => {
            push_native_control_flow_expr_requirements(
                expr,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            push_native_control_flow_assign_target_requirements(
                target,
                operand_index,
                options.include_call_operations,
                expr_requires_destructor_cleanup,
                requirements,
            );
            push_native_control_flow_expr_requirements(
                expr,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if options.include_call_operations {
                if let Some(operation) =
                    native_statement_assignment_rhs_call_operation(target, expr)
                {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            push_native_control_flow_assign_target_requirements(
                target,
                operand_index,
                options.include_call_operations,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if reference_source_contains_destructor_observable_cleanup(
                source,
                expr_requires_destructor_cleanup,
            ) {
                push_native_control_flow_requirement(
                    requirements,
                    PHPC_NATIVE_DIAGNOSTIC_OPERAND_DESTRUCTOR_OBSERVABLE_CLEANUP,
                    operand_index,
                );
            }
            if options.include_call_operations {
                if let Some(operation) = native_reference_assignment_call_operation(target, source)
                {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::IncrementDecrement { target, .. } => {
            push_native_control_flow_assign_target_requirements(
                target,
                operand_index,
                options.include_call_operations,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            push_native_control_flow_expr_requirements(
                condition,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                then_branch,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                else_branch,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => {
            push_native_control_flow_expr_requirements(
                condition,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                body,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            for action in initializers.iter().chain(increments.iter()) {
                push_native_control_flow_for_action_requirements(
                    action,
                    operand_index,
                    options.include_call_operations,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
            for condition in conditions {
                push_native_control_flow_expr_requirements(
                    condition,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                body,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::Switch { value, cases, .. } => {
            push_native_control_flow_expr_requirements(
                value,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            for case in cases {
                if let Some(condition) = &case.condition {
                    push_native_control_flow_expr_requirements(
                        condition,
                        operand_index,
                        expr_requires_destructor_cleanup,
                        requirements,
                    );
                }
                native_stmt_list_control_flow_cleanup_requirements_at_operand(
                    &case.body,
                    options,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
        }
        Stmt::Foreach { iterable, body, .. } => {
            push_native_control_flow_expr_requirements(
                iterable,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                body,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        Stmt::UnsetArrayIndex { index, .. } => {
            push_native_control_flow_expr_requirements(
                index,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if options.include_call_operations {
                if let Some(operation) = native_lvalue_operand_call_result_operation(index) {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::UnsetNestedArrayIndex { indices, .. } => {
            for index in indices {
                push_native_control_flow_expr_requirements(
                    index,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
            if options.include_call_operations {
                if let Some(operation) = native_expr_list_call_result_operation(indices) {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::UnsetDynamicObjectProperty { property, .. } => {
            push_native_control_flow_expr_requirements(
                property,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if options.include_call_operations {
                if let Some(operation) = native_lvalue_operand_call_result_operation(property) {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::UnsetMany { targets, .. } => {
            for target in targets {
                push_native_control_flow_unset_target_requirements(
                    target,
                    operand_index,
                    options.include_call_operations,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
        }
        Stmt::ConstDeclaration { declarations, .. } => {
            declarations.iter().for_each(|declaration| {
                push_native_control_flow_expr_requirements(
                    &declaration.value,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
                if options.include_call_operations {
                    if let Some(operation) =
                        native_statement_operand_call_result_operation(&declaration.value)
                    {
                        push_native_control_flow_call_operation_requirement(
                            requirements,
                            operation,
                            operand_index,
                        );
                    }
                }
            })
        }
        Stmt::Require { path, .. } | Stmt::Include { path, .. } => {
            push_native_control_flow_expr_requirements(
                path,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if options.include_call_operations {
                if let Some(operation) = native_statement_operand_call_result_operation(path) {
                    push_native_control_flow_call_operation_requirement(
                        requirements,
                        operation,
                        operand_index,
                    );
                }
            }
        }
        Stmt::Try {
            body, finally_body, ..
        } => {
            native_stmt_list_control_flow_cleanup_requirements_at_operand(
                body,
                options,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
            if let Some(body) = finally_body {
                native_stmt_list_control_flow_cleanup_requirements_at_operand(
                    body,
                    NativeControlFlowCleanupRequirementOptions::blocked_transfers(),
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
            }
        }
        Stmt::StaticLocal { declarations, .. } => declarations
            .iter()
            .filter_map(|declaration| declaration.default.as_ref())
            .for_each(|default| {
                push_native_control_flow_expr_requirements(
                    default,
                    operand_index,
                    expr_requires_destructor_cleanup,
                    requirements,
                );
                if options.include_call_operations {
                    if let Some(operation) = native_statement_operand_call_result_operation(default)
                    {
                        push_native_control_flow_call_operation_requirement(
                            requirements,
                            operation,
                            operand_index,
                        );
                    }
                }
            }),
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Label { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::UnsetVariable { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Global { .. } => {}
    }
}

fn native_stmt_list_control_flow_cleanup_requirements_at_operand<F>(
    statements: &[Stmt],
    options: NativeControlFlowCleanupRequirementOptions,
    operand_index: usize,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    for stmt in statements {
        native_stmt_control_flow_cleanup_requirements(
            stmt,
            options,
            operand_index,
            expr_requires_destructor_cleanup,
            requirements,
        );
    }
}

fn push_native_control_flow_for_action_requirements<F>(
    action: &ForAction,
    operand_index: usize,
    include_call_operations: bool,
    expr_requires_destructor_cleanup: &F,
    requirements: &mut Vec<NativeDiagnosticOperandRequirement>,
) where
    F: Fn(&Expr) -> bool,
{
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            push_native_control_flow_assign_target_requirements(
                target,
                operand_index,
                include_call_operations,
                expr_requires_destructor_cleanup,
                requirements,
            );
            push_native_control_flow_expr_requirements(
                expr,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        ForAction::IncrementDecrement { target, .. } => {
            push_native_control_flow_assign_target_requirements(
                target,
                operand_index,
                include_call_operations,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
        ForAction::Expr { expr } => {
            push_native_control_flow_expr_requirements(
                expr,
                operand_index,
                expr_requires_destructor_cleanup,
                requirements,
            );
        }
    }
    if include_call_operations {
        if let Some(operation) = native_for_action_call_operation(action) {
            push_native_control_flow_call_operation_requirement(
                requirements,
                operation,
                operand_index,
            );
        }
    }
}

fn array_item_contains_exit_construct(item: &ArrayItem) -> bool {
    item.key.as_ref().is_some_and(expr_contains_exit_construct)
        || expr_contains_exit_construct(&item.value)
}

fn match_arm_exprs_contain<F>(arms: &[MatchArm], contains: &F) -> bool
where
    F: Fn(&Expr) -> bool,
{
    arms.iter()
        .any(|arm| arm.conditions.iter().any(contains) || contains(&arm.result))
}

fn match_expr_contains<F>(subject: &Expr, arms: &[MatchArm], contains: &F) -> bool
where
    F: Fn(&Expr) -> bool,
{
    contains(subject) || match_arm_exprs_contain(arms, contains)
}

fn assign_target_contains_exit_construct(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            index.as_ref().is_some_and(expr_contains_exit_construct)
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => {
            indices.iter().any(expr_contains_exit_construct)
                || suffix_indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_exit_construct(property)
                || indices.iter().any(expr_contains_exit_construct)
                || suffix_indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::DynamicProperty { property, .. }
        | AssignTarget::ObjectStaticProperty {
            target: property, ..
        } => expr_contains_exit_construct(property),
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_exit_construct(holder)
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_exit_construct(holder)
                || indices.iter().any(expr_contains_exit_construct)
                || suffix_indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => expr_contains_exit_construct(holder) || expr_contains_exit_construct(property),
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_exit_construct(holder)
                || expr_contains_exit_construct(property)
                || indices.iter().any(expr_contains_exit_construct)
                || suffix_indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_exit_construct(property)
                || indices.iter().any(expr_contains_exit_construct)
        }
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => false,
    }
}

fn unset_target_contains_exit_construct(target: &UnsetTarget) -> bool {
    match target {
        UnsetTarget::ArrayIndex { index, .. }
        | UnsetTarget::DynamicObjectProperty {
            property: index, ..
        } => expr_contains_exit_construct(index),
        UnsetTarget::NestedArrayIndex { indices, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_exit_construct)
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_exit_construct(property)
                || indices.iter().any(expr_contains_exit_construct)
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_exit_construct(holder)
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => expr_contains_exit_construct(holder) || expr_contains_exit_construct(property),
        UnsetTarget::ObjectStaticProperty { target, .. } => expr_contains_exit_construct(target),
        UnsetTarget::Variable { .. }
        | UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => false,
    }
}

fn exprs_contain_destructor_observable_cleanup<F>(exprs: &[Expr], contains: &F) -> bool
where
    F: Fn(&Expr) -> bool,
{
    exprs.iter().any(contains)
}

fn optional_expr_contains_destructor_observable_cleanup<F>(
    expr: Option<&Expr>,
    contains: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    expr.is_some_and(contains)
}

fn array_item_contains_destructor_observable_cleanup<F>(item: &ArrayItem, contains: &F) -> bool
where
    F: Fn(&Expr) -> bool,
{
    optional_expr_contains_destructor_observable_cleanup(item.key.as_ref(), contains)
        || contains(&item.value)
}

fn assign_target_contains_destructor_observable_cleanup<F>(
    target: &AssignTarget,
    contains: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            optional_expr_contains_destructor_observable_cleanup(index.as_ref(), contains)
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            exprs_contain_destructor_observable_cleanup(indices, contains)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => {
            exprs_contain_destructor_observable_cleanup(indices, contains)
                || exprs_contain_destructor_observable_cleanup(suffix_indices, contains)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            contains(property)
                || exprs_contain_destructor_observable_cleanup(indices, contains)
                || exprs_contain_destructor_observable_cleanup(suffix_indices, contains)
        }
        AssignTarget::DynamicProperty { property, .. }
        | AssignTarget::ObjectStaticProperty {
            target: property, ..
        } => contains(property),
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => contains(holder),
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            contains(holder)
                || exprs_contain_destructor_observable_cleanup(indices, contains)
                || exprs_contain_destructor_observable_cleanup(suffix_indices, contains)
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => contains(holder) || contains(property),
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            contains(holder)
                || contains(property)
                || exprs_contain_destructor_observable_cleanup(indices, contains)
                || exprs_contain_destructor_observable_cleanup(suffix_indices, contains)
        }
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => contains(property) || exprs_contain_destructor_observable_cleanup(indices, contains),
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => false,
    }
}

fn unset_target_contains_destructor_observable_cleanup<F>(
    target: &UnsetTarget,
    contains: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    match target {
        UnsetTarget::ArrayIndex { index, .. }
        | UnsetTarget::DynamicObjectProperty {
            property: index, ..
        } => contains(index),
        UnsetTarget::NestedArrayIndex { indices, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            exprs_contain_destructor_observable_cleanup(indices, contains)
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => contains(property) || exprs_contain_destructor_observable_cleanup(indices, contains),
        UnsetTarget::NonDirectObjectProperty { holder, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => contains(holder),
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => contains(holder) || contains(property),
        UnsetTarget::ObjectStaticProperty { target, .. } => contains(target),
        UnsetTarget::Variable { .. }
        | UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => false,
    }
}

fn reference_source_contains_destructor_observable_cleanup<F>(
    source: &ReferenceSource,
    contains: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    match source {
        ReferenceSource::ArrayIndex { index, .. } => contains(index),
        ReferenceSource::ArrayAppend { indices, .. }
        | ReferenceSource::NestedArrayIndex { indices, .. }
        | ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. } => {
            exprs_contain_destructor_observable_cleanup(indices, contains)
        }
        ReferenceSource::ObjectPropertyArrayIndex { index, .. } => contains(index),
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            property, index, ..
        } => contains(property) || contains(index),
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            property, indices, ..
        } => contains(property) || exprs_contain_destructor_observable_cleanup(indices, contains),
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        } => contains(holder) || exprs_contain_destructor_observable_cleanup(indices, contains),
        ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            contains(holder)
                || contains(property)
                || exprs_contain_destructor_observable_cleanup(indices, contains)
        }
        ReferenceSource::Property { expr, .. }
        | ReferenceSource::StaticProperty { expr, .. }
        | ReferenceSource::MethodCall { expr, .. } => contains(expr),
        ReferenceSource::StaticPropertyArrayIndex { expr, indices, .. }
        | ReferenceSource::ExpressionArrayIndex {
            target: expr,
            indices,
            ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target: expr,
            indices,
            ..
        } => contains(expr) || exprs_contain_destructor_observable_cleanup(indices, contains),
        ReferenceSource::Variable { .. } => false,
    }
}

fn expr_contains_exit_construct(expr: &Expr) -> bool {
    match expr {
        Expr::Call { name, args, .. } => {
            is_exit_construct_name(name) || args.iter().any(expr_contains_exit_construct)
        }
        Expr::DynamicCall { callee, args, .. } => {
            expr_contains_exit_construct(callee) || args.iter().any(expr_contains_exit_construct)
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            expr_contains_exit_construct(target) || args.iter().any(expr_contains_exit_construct)
        }
        Expr::StaticMethodCall { args, .. } => args.iter().any(expr_contains_exit_construct),
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            expr_contains_exit_construct(target)
                || expr_contains_exit_construct(method)
                || args.iter().any(expr_contains_exit_construct)
        }
        Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. } => args.iter().any(expr_contains_exit_construct),
        Expr::Array { items, .. } => items.iter().any(array_item_contains_exit_construct),
        Expr::Index { target, index, .. } => {
            expr_contains_exit_construct(target) || expr_contains_exit_construct(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => expr_contains_exit_construct(target),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            expr_contains_exit_construct(target)
                || new_class_name_contains_exit_construct(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => expr_contains_exit_construct(target) || expr_contains_exit_construct(property),
        Expr::New { args, .. } => args.iter().any(expr_contains_exit_construct),
        Expr::Binary { left, right, .. } => {
            expr_contains_exit_construct(left) || expr_contains_exit_construct(right)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            expr_contains_exit_construct(condition)
                || expr_contains_exit_construct(if_true)
                || expr_contains_exit_construct(if_false)
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => expr_contains_exit_construct(condition) || expr_contains_exit_construct(if_false),
        Expr::Match { subject, arms, .. } => {
            match_expr_contains(subject, arms, &expr_contains_exit_construct)
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_exit_construct(target) || expr_contains_exit_construct(expr)
        }
        Expr::IncrementDecrement { target, .. } => assign_target_contains_exit_construct(target),
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            expr_contains_exit_construct(expr)
        }
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::InterpolatedString { .. }
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. }
        | Expr::Closure { .. } => false,
    }
}

fn new_class_name_contains_exit_construct(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicExpression(expr) => expr_contains_exit_construct(expr),
        NewClassName::Named(_)
        | NewClassName::DynamicVariable(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn function_body_contains_native_frame_blocker(statements: &[Stmt]) -> bool {
    !native_control_flow_cleanup_requirements(
        statements,
        NativeControlFlowCleanupRequirementOptions::frame_body_cleanup_only(),
        &|_| false,
    )
    .is_empty()
        || statements.iter().any(stmt_contains_function_frame_blocker)
}

fn function_reference_return_sources_are_supported<F>(
    function: &FunctionDecl,
    reference_source_supported: F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    if !function.returns_by_reference {
        return true;
    }

    stmt_list_reference_return_sources_are_supported(&function.body, &reference_source_supported)
}

fn closure_reference_return_sources_are_supported<F>(
    params: &[FunctionParam],
    captures: &[ClosureCapture],
    body: &[Stmt],
    returns_by_reference: bool,
    reference_source_supported: F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    if !returns_by_reference {
        return true;
    }

    let mut by_reference_symbols = params
        .iter()
        .filter(|param| param.by_reference)
        .map(|param| param.name.as_str())
        .collect::<HashSet<_>>();
    by_reference_symbols.extend(
        captures
            .iter()
            .filter(|capture| capture.by_reference)
            .map(|capture| capture.name.as_str()),
    );

    stmt_list_reference_return_sources_are_supported(body, &|expr| {
        closure_reference_return_source_is_supported(
            expr,
            &by_reference_symbols,
            &reference_source_supported,
        )
    })
}

fn closure_reference_return_source_is_supported<F>(
    expr: &Expr,
    by_reference_symbols: &HashSet<&str>,
    reference_source_supported: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    if matches!(expr, Expr::Variable(name, _) if !by_reference_symbols.contains(name.as_str())) {
        return false;
    }

    reference_source_supported(expr)
}

fn stmt_list_reference_return_sources_are_supported<F>(
    statements: &[Stmt],
    reference_source_supported: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    statements
        .iter()
        .all(|stmt| stmt_reference_return_sources_are_supported(stmt, reference_source_supported))
}

fn stmt_reference_return_sources_are_supported<F>(
    stmt: &Stmt,
    reference_source_supported: &F,
) -> bool
where
    F: Fn(&Expr) -> bool,
{
    match stmt {
        Stmt::Return { value, .. } => value.as_ref().map_or(true, reference_source_supported),
        Stmt::If {
            then_branch,
            else_branch,
            ..
        } => {
            stmt_list_reference_return_sources_are_supported(
                then_branch,
                reference_source_supported,
            ) && stmt_list_reference_return_sources_are_supported(
                else_branch,
                reference_source_supported,
            )
        }
        Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::Foreach { body, .. } => {
            stmt_list_reference_return_sources_are_supported(body, reference_source_supported)
        }
        Stmt::For { body, .. } => {
            stmt_list_reference_return_sources_are_supported(body, reference_source_supported)
        }
        Stmt::Switch { cases, .. } => cases.iter().all(|case| {
            stmt_list_reference_return_sources_are_supported(&case.body, reference_source_supported)
        }),
        Stmt::Try {
            body, finally_body, ..
        } => {
            stmt_list_reference_return_sources_are_supported(body, reference_source_supported)
                && finally_body.as_ref().map_or(true, |body| {
                    stmt_list_reference_return_sources_are_supported(
                        body,
                        reference_source_supported,
                    )
                })
        }
        _ => true,
    }
}

fn stmt_list_always_returns(statements: &[Stmt]) -> bool {
    statements.iter().any(stmt_always_returns)
}

fn stmt_always_returns(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Return { .. } => true,
        Stmt::If {
            then_branch,
            else_branch,
            ..
        } => stmt_list_always_returns(then_branch) && stmt_list_always_returns(else_branch),
        Stmt::Try {
            body, finally_body, ..
        } => {
            finally_body
                .as_ref()
                .is_some_and(|body| stmt_list_always_returns(body))
                || stmt_list_always_returns(body)
        }
        _ => false,
    }
}

fn stmt_list_contains_global_import(statements: &[Stmt]) -> bool {
    statements.iter().any(stmt_contains_global_import)
}

fn stmt_list_frame_environment_requirement(statements: &[Stmt]) -> CFrameEnvironmentRequirement {
    CFrameEnvironmentRequirement {
        root_symbols: stmt_list_contains_global_import(statements)
            || stmt_list_contains_globals_access(statements),
        request_state: stmt_list_contains_request_state_access(statements),
        include_scope_symbols: stmt_list_contains_include_or_require(statements),
    }
}

fn stmt_list_contains_include_or_require(statements: &[Stmt]) -> bool {
    statements.iter().any(stmt_contains_include_or_require)
}

fn stmt_contains_include_or_require(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Include { .. } | Stmt::Require { .. } => true,
        Stmt::Echo { exprs, .. } => exprs.iter().any(expr_contains_include_or_require),
        Stmt::Print { expr, .. } | Stmt::Expr { expr, .. } | Stmt::Throw { expr, .. } => {
            expr_contains_include_or_require(expr)
        }
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_include_or_require(target)
                || expr_contains_include_or_require(expr)
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            assign_target_contains_include_or_require(target)
                || reference_source_contains_include_or_require(source)
        }
        Stmt::IncrementDecrement { target, .. } => {
            assign_target_contains_include_or_require(target)
        }
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            expr_contains_include_or_require(condition)
                || stmt_list_contains_include_or_require(then_branch)
                || stmt_list_contains_include_or_require(else_branch)
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => {
            expr_contains_include_or_require(condition)
                || stmt_list_contains_include_or_require(body)
        }
        Stmt::Foreach { iterable, body, .. } => {
            expr_contains_include_or_require(iterable)
                || stmt_list_contains_include_or_require(body)
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            initializers
                .iter()
                .chain(increments.iter())
                .any(for_action_contains_include_or_require)
                || conditions.iter().any(expr_contains_include_or_require)
                || stmt_list_contains_include_or_require(body)
        }
        Stmt::Switch { value, cases, .. } => {
            expr_contains_include_or_require(value)
                || cases.iter().any(|case| {
                    case.condition
                        .as_ref()
                        .is_some_and(expr_contains_include_or_require)
                        || stmt_list_contains_include_or_require(&case.body)
                })
        }
        Stmt::UnsetArrayIndex { index, .. } => expr_contains_include_or_require(index),
        Stmt::UnsetNestedArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_include_or_require)
        }
        Stmt::UnsetDynamicObjectProperty { property, .. } => {
            expr_contains_include_or_require(property)
        }
        Stmt::UnsetMany { targets, .. } => {
            targets.iter().any(unset_target_contains_include_or_require)
        }
        Stmt::ConstDeclaration { declarations, .. } => declarations
            .iter()
            .any(|declaration| expr_contains_include_or_require(&declaration.value)),
        Stmt::Return { value, .. } => value.as_ref().is_some_and(expr_contains_include_or_require),
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            stmt_list_contains_include_or_require(body)
                || catches
                    .iter()
                    .any(|catch| stmt_list_contains_include_or_require(&catch.body))
                || finally_body
                    .as_ref()
                    .is_some_and(|body| stmt_list_contains_include_or_require(body))
        }
        Stmt::StaticLocal { declarations, .. } => declarations.iter().any(|declaration| {
            declaration
                .default
                .as_ref()
                .is_some_and(expr_contains_include_or_require)
        }),
        _ => false,
    }
}

fn expr_contains_include_or_require(expr: &Expr) -> bool {
    match expr {
        Expr::Include { .. } | Expr::Require { .. } => true,
        Expr::InterpolatedString { parts, .. } => parts
            .iter()
            .any(interpolated_string_part_contains_include_or_require),
        Expr::Call { args, .. }
        | Expr::StaticMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. }
        | Expr::New { args, .. } => args.iter().any(expr_contains_include_or_require),
        Expr::DynamicCall { callee, args, .. } => {
            expr_contains_include_or_require(callee)
                || args.iter().any(expr_contains_include_or_require)
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            expr_contains_include_or_require(target)
                || args.iter().any(expr_contains_include_or_require)
        }
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            expr_contains_include_or_require(target)
                || expr_contains_include_or_require(method)
                || args.iter().any(expr_contains_include_or_require)
        }
        Expr::Array { items, .. } => items.iter().any(|item| {
            item.key
                .as_ref()
                .is_some_and(expr_contains_include_or_require)
                || expr_contains_include_or_require(&item.value)
        }),
        Expr::Index { target, index, .. } => {
            expr_contains_include_or_require(target) || expr_contains_include_or_require(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Cast { expr: target, .. } => expr_contains_include_or_require(target),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            expr_contains_include_or_require(target)
                || new_class_name_contains_include_or_require(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => expr_contains_include_or_require(target) || expr_contains_include_or_require(property),
        Expr::Binary { left, right, .. } => {
            expr_contains_include_or_require(left) || expr_contains_include_or_require(right)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            expr_contains_include_or_require(condition)
                || expr_contains_include_or_require(if_true)
                || expr_contains_include_or_require(if_false)
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => {
            expr_contains_include_or_require(condition)
                || expr_contains_include_or_require(if_false)
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_include_or_require(target)
                || expr_contains_include_or_require(expr)
        }
        Expr::IncrementDecrement { target, .. } => {
            assign_target_contains_include_or_require(target)
        }
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            expr_contains_include_or_require(expr)
        }
        _ => false,
    }
}

fn new_class_name_contains_include_or_require(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicExpression(expr) => expr_contains_include_or_require(expr),
        NewClassName::DynamicVariable(_)
        | NewClassName::Named(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn interpolated_string_part_contains_include_or_require(_part: &InterpolatedStringPart) -> bool {
    false
}

fn assign_target_contains_include_or_require(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            index.as_ref().is_some_and(expr_contains_include_or_require)
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_include_or_require)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => indices
            .iter()
            .chain(suffix_indices.iter())
            .any(expr_contains_include_or_require),
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayAppend { holder, .. } => {
            expr_contains_include_or_require(holder)
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => expr_contains_include_or_require(holder) || expr_contains_include_or_require(property),
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_include_or_require(property)
                || indices.iter().any(expr_contains_include_or_require)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_include_or_require(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_include_or_require)
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_include_or_require(holder)
                || expr_contains_include_or_require(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_include_or_require)
        }
        AssignTarget::DynamicProperty { property, .. }
        | AssignTarget::DynamicStaticProperty { property, .. }
        | AssignTarget::DynamicSelfStaticProperty { property, .. }
        | AssignTarget::DynamicParentStaticProperty { property, .. }
        | AssignTarget::DynamicLateStaticProperty { property, .. } => {
            expr_contains_include_or_require(property)
        }
        AssignTarget::ObjectStaticProperty { target, .. } => {
            expr_contains_include_or_require(target)
        }
        AssignTarget::DynamicObjectStaticProperty {
            target, property, ..
        } => expr_contains_include_or_require(target) || expr_contains_include_or_require(property),
        _ => false,
    }
}

fn reference_source_contains_include_or_require(source: &ReferenceSource) -> bool {
    match source {
        ReferenceSource::ArrayIndex { index, .. } => expr_contains_include_or_require(index),
        ReferenceSource::ObjectPropertyArrayIndex { index, .. } => {
            expr_contains_include_or_require(index)
        }
        ReferenceSource::ArrayAppend { indices, .. }
        | ReferenceSource::NestedArrayIndex { indices, .. }
        | ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. }
        | ReferenceSource::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_include_or_require)
        }
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            property, index, ..
        } => expr_contains_include_or_require(property) || expr_contains_include_or_require(index),
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            property, indices, ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            property,
            indices,
            ..
        } => {
            expr_contains_include_or_require(property)
                || indices.iter().any(expr_contains_include_or_require)
        }
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        }
        | ReferenceSource::ExpressionArrayIndex {
            target: holder,
            indices,
            ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target: holder,
            indices,
            ..
        } => {
            expr_contains_include_or_require(holder)
                || indices.iter().any(expr_contains_include_or_require)
        }
        ReferenceSource::Property { expr, .. }
        | ReferenceSource::StaticProperty { expr, .. }
        | ReferenceSource::MethodCall { expr, .. } => expr_contains_include_or_require(expr),
        ReferenceSource::Variable { .. } => false,
    }
}

fn unset_target_contains_include_or_require(target: &UnsetTarget) -> bool {
    match target {
        UnsetTarget::ArrayIndex { index, .. } => expr_contains_include_or_require(index),
        UnsetTarget::NestedArrayIndex { indices, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_include_or_require)
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_include_or_require(property)
                || indices.iter().any(expr_contains_include_or_require)
        }
        UnsetTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => {
            expr_contains_include_or_require(holder)
                || indices.iter().any(expr_contains_include_or_require)
        }
        UnsetTarget::DynamicObjectProperty { property, .. } => {
            expr_contains_include_or_require(property)
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. } => {
            expr_contains_include_or_require(holder)
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        } => expr_contains_include_or_require(holder) || expr_contains_include_or_require(property),
        UnsetTarget::ObjectStaticProperty { target, .. } => {
            expr_contains_include_or_require(target)
        }
        _ => false,
    }
}

fn for_action_contains_include_or_require(action: &ForAction) -> bool {
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            assign_target_contains_include_or_require(target)
                || expr_contains_include_or_require(expr)
        }
        ForAction::IncrementDecrement { target, .. } => {
            assign_target_contains_include_or_require(target)
        }
        ForAction::Expr { expr } => expr_contains_include_or_require(expr),
    }
}

fn stmt_contains_global_import(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Global { .. } => true,
        Stmt::If {
            then_branch,
            else_branch,
            ..
        } => {
            stmt_list_contains_global_import(then_branch)
                || stmt_list_contains_global_import(else_branch)
        }
        Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::Foreach { body, .. } => {
            stmt_list_contains_global_import(body)
        }
        Stmt::For { body, .. } => stmt_list_contains_global_import(body),
        Stmt::Switch { cases, .. } => cases
            .iter()
            .any(|case| stmt_list_contains_global_import(&case.body)),
        Stmt::Try {
            body, finally_body, ..
        } => {
            stmt_list_contains_global_import(body)
                || finally_body
                    .as_ref()
                    .is_some_and(|body| stmt_list_contains_global_import(body))
        }
        _ => false,
    }
}

fn stmt_list_contains_globals_access(statements: &[Stmt]) -> bool {
    statements.iter().any(stmt_contains_globals_access)
}

fn stmt_contains_globals_access(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Echo { exprs, .. } => exprs.iter().any(expr_contains_globals_access),
        Stmt::Print { expr, .. }
        | Stmt::Expr { expr, .. }
        | Stmt::Require { path: expr, .. }
        | Stmt::Include { path: expr, .. }
        | Stmt::Throw { expr, .. } => expr_contains_globals_access(expr),
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_globals_access(target) || expr_contains_globals_access(expr)
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            assign_target_contains_globals_access(target)
                || reference_source_contains_globals_access(source)
        }
        Stmt::IncrementDecrement { target, .. } => assign_target_contains_globals_access(target),
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            expr_contains_globals_access(condition)
                || stmt_list_contains_globals_access(then_branch)
                || stmt_list_contains_globals_access(else_branch)
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => expr_contains_globals_access(condition) || stmt_list_contains_globals_access(body),
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            initializers
                .iter()
                .chain(increments.iter())
                .any(for_action_contains_globals_access)
                || conditions.iter().any(expr_contains_globals_access)
                || stmt_list_contains_globals_access(body)
        }
        Stmt::Switch { value, cases, .. } => {
            expr_contains_globals_access(value)
                || cases.iter().any(|case| {
                    case.condition
                        .as_ref()
                        .is_some_and(expr_contains_globals_access)
                        || stmt_list_contains_globals_access(&case.body)
                })
        }
        Stmt::Foreach { iterable, body, .. } => {
            expr_contains_globals_access(iterable) || stmt_list_contains_globals_access(body)
        }
        Stmt::UnsetVariable { name, .. } => is_globals_superglobal_name(name),
        Stmt::UnsetArrayIndex { name, index, .. } => {
            is_globals_superglobal_name(name) || expr_contains_globals_access(index)
        }
        Stmt::UnsetNestedArrayIndex { name, indices, .. } => {
            is_globals_superglobal_name(name) || indices.iter().any(expr_contains_globals_access)
        }
        Stmt::UnsetDynamicObjectProperty { property, .. } => expr_contains_globals_access(property),
        Stmt::UnsetMany { targets, .. } => targets.iter().any(unset_target_contains_globals_access),
        Stmt::ConstDeclaration { declarations, .. } => declarations
            .iter()
            .any(|declaration| expr_contains_globals_access(&declaration.value)),
        Stmt::Return { value, .. } => value.as_ref().is_some_and(expr_contains_globals_access),
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            stmt_list_contains_globals_access(body)
                || catches
                    .iter()
                    .any(|catch| stmt_list_contains_globals_access(&catch.body))
                || finally_body
                    .as_ref()
                    .is_some_and(|body| stmt_list_contains_globals_access(body))
        }
        Stmt::StaticLocal { declarations, .. } => declarations.iter().any(|declaration| {
            declaration
                .default
                .as_ref()
                .is_some_and(expr_contains_globals_access)
        }),
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::Global { .. } => false,
    }
}

fn stmt_list_unsupported_global_import_span(statements: &[Stmt]) -> Option<Span> {
    statements
        .iter()
        .find_map(stmt_unsupported_global_import_span)
}

fn stmt_unsupported_global_import_span(stmt: &Stmt) -> Option<Span> {
    match stmt {
        Stmt::Global { names, span } => names
            .iter()
            .any(|name| is_request_superglobal_name(name))
            .then_some(*span),
        Stmt::If {
            then_branch,
            else_branch,
            ..
        } => stmt_list_unsupported_global_import_span(then_branch)
            .or_else(|| stmt_list_unsupported_global_import_span(else_branch)),
        Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::Foreach { body, .. } => {
            stmt_list_unsupported_global_import_span(body)
        }
        Stmt::For { body, .. } => stmt_list_unsupported_global_import_span(body),
        Stmt::Switch { cases, .. } => cases
            .iter()
            .find_map(|case| stmt_list_unsupported_global_import_span(&case.body)),
        Stmt::Try {
            body, finally_body, ..
        } => stmt_list_unsupported_global_import_span(body).or_else(|| {
            finally_body
                .as_ref()
                .and_then(|body| stmt_list_unsupported_global_import_span(body))
        }),
        _ => None,
    }
}

fn stmt_contains_function_frame_blocker(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::StaticLocal { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_) => true,
        Stmt::If {
            then_branch,
            else_branch,
            ..
        } => {
            then_branch.iter().any(stmt_contains_function_frame_blocker)
                || else_branch.iter().any(stmt_contains_function_frame_blocker)
        }
        Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::Foreach { body, .. } => {
            body.iter().any(stmt_contains_function_frame_blocker)
        }
        Stmt::For { body, .. } => body.iter().any(stmt_contains_function_frame_blocker),
        Stmt::Switch { cases, .. } => cases
            .iter()
            .any(|case| case.body.iter().any(stmt_contains_function_frame_blocker)),
        Stmt::Try {
            body, finally_body, ..
        } => {
            body.iter().any(stmt_contains_function_frame_blocker)
                || finally_body
                    .as_ref()
                    .is_some_and(|body| body.iter().any(stmt_contains_function_frame_blocker))
        }
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Echo { .. }
        | Stmt::Print { .. }
        | Stmt::Assign { .. }
        | Stmt::ReferenceAssign { .. }
        | Stmt::CompoundAssign { .. }
        | Stmt::IncrementDecrement { .. }
        | Stmt::NullCoalesceAssign { .. }
        | Stmt::Expr { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::UnsetVariable { .. }
        | Stmt::UnsetArrayIndex { .. }
        | Stmt::UnsetNestedArrayIndex { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetDynamicObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::UnsetMany { .. }
        | Stmt::ConstDeclaration { .. }
        | Stmt::Require { .. }
        | Stmt::Include { .. }
        | Stmt::Return { .. }
        | Stmt::Throw { .. }
        | Stmt::Global { .. }
        | Stmt::Break { .. }
        | Stmt::Continue { .. } => false,
    }
}

fn collect_direct_call_names_from_stmts(statements: &[Stmt], names: &mut Vec<String>) {
    for statement in statements {
        collect_direct_call_names_from_stmt(statement, names);
    }
}

fn collect_direct_call_names_from_stmt(stmt: &Stmt, names: &mut Vec<String>) {
    match stmt {
        Stmt::Echo { exprs, .. } => {
            for expr in exprs {
                collect_direct_call_names_from_expr(expr, names);
            }
        }
        Stmt::Print { expr, .. }
        | Stmt::Expr { expr, .. }
        | Stmt::Require { path: expr, .. }
        | Stmt::Include { path: expr, .. }
        | Stmt::Throw { expr, .. } => collect_direct_call_names_from_expr(expr, names),
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
            collect_direct_call_names_from_expr(expr, names);
        }
        Stmt::IncrementDecrement { target, .. } | Stmt::ReferenceAssign { target, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
        }
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            collect_direct_call_names_from_expr(condition, names);
            collect_direct_call_names_from_stmts(then_branch, names);
            collect_direct_call_names_from_stmts(else_branch, names);
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => {
            collect_direct_call_names_from_expr(condition, names);
            collect_direct_call_names_from_stmts(body, names);
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            for action in initializers.iter().chain(increments.iter()) {
                collect_direct_call_names_from_for_action(action, names);
            }
            for condition in conditions {
                collect_direct_call_names_from_expr(condition, names);
            }
            collect_direct_call_names_from_stmts(body, names);
        }
        Stmt::Switch { value, cases, .. } => {
            collect_direct_call_names_from_expr(value, names);
            for case in cases {
                if let Some(condition) = &case.condition {
                    collect_direct_call_names_from_expr(condition, names);
                }
                collect_direct_call_names_from_stmts(&case.body, names);
            }
        }
        Stmt::Foreach { iterable, body, .. } => {
            collect_direct_call_names_from_expr(iterable, names);
            collect_direct_call_names_from_stmts(body, names);
        }
        Stmt::UnsetArrayIndex { index, .. }
        | Stmt::UnsetDynamicObjectProperty {
            property: index, ..
        } => collect_direct_call_names_from_expr(index, names),
        Stmt::UnsetNestedArrayIndex { indices, .. } => {
            for index in indices {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        Stmt::UnsetMany { targets, .. } => {
            for target in targets {
                collect_direct_call_names_from_unset_target(target, names);
            }
        }
        Stmt::ConstDeclaration { declarations, .. } => {
            for declaration in declarations {
                collect_direct_call_names_from_expr(&declaration.value, names);
            }
        }
        Stmt::Return { value, .. } => {
            if let Some(value) = value {
                collect_direct_call_names_from_expr(value, names);
            }
        }
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            collect_direct_call_names_from_stmts(body, names);
            for catch in catches {
                collect_direct_call_names_from_stmts(&catch.body, names);
            }
            if let Some(finally_body) = finally_body {
                collect_direct_call_names_from_stmts(finally_body, names);
            }
        }
        Stmt::StaticLocal { declarations, .. } => {
            for declaration in declarations {
                if let Some(default) = &declaration.default {
                    collect_direct_call_names_from_expr(default, names);
                }
            }
        }
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::UnsetVariable { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::Global { .. } => {}
    }
}

fn collect_direct_call_names_from_for_action(action: &ForAction, names: &mut Vec<String>) {
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
            collect_direct_call_names_from_expr(expr, names);
        }
        ForAction::IncrementDecrement { target, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
        }
        ForAction::Expr { expr } => collect_direct_call_names_from_expr(expr, names),
    }
}

fn collect_direct_call_names_from_assign_target(target: &AssignTarget, names: &mut Vec<String>) {
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            if let Some(index) = index {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            for index in indices {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => {
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::DynamicProperty { property, .. } => {
            collect_direct_call_names_from_expr(property, names);
        }
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            collect_direct_call_names_from_expr(property, names);
            for index in indices {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            collect_direct_call_names_from_expr(property, names);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::ObjectStaticProperty { target: holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            collect_direct_call_names_from_expr(holder, names);
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            collect_direct_call_names_from_expr(holder, names);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => {
            collect_direct_call_names_from_expr(holder, names);
            collect_direct_call_names_from_expr(property, names);
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            collect_direct_call_names_from_expr(holder, names);
            collect_direct_call_names_from_expr(property, names);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => {}
    }
}

fn collect_direct_call_names_from_unset_target(target: &UnsetTarget, names: &mut Vec<String>) {
    match target {
        UnsetTarget::ArrayIndex { index, .. }
        | UnsetTarget::DynamicObjectProperty {
            property: index, ..
        } => collect_direct_call_names_from_expr(index, names),
        UnsetTarget::NestedArrayIndex { indices, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            for index in indices {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            collect_direct_call_names_from_expr(property, names);
            for index in indices {
                collect_direct_call_names_from_expr(index, names);
            }
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            collect_direct_call_names_from_expr(holder, names);
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => {
            collect_direct_call_names_from_expr(holder, names);
            collect_direct_call_names_from_expr(property, names);
        }
        UnsetTarget::ObjectStaticProperty { target, .. } => {
            collect_direct_call_names_from_expr(target, names);
        }
        UnsetTarget::Variable { .. }
        | UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => {}
    }
}

fn collect_direct_call_names_from_expr(expr: &Expr, names: &mut Vec<String>) {
    match expr {
        Expr::Call { name, args, .. } => {
            names.push(name.clone());
            for arg in args {
                collect_direct_call_names_from_expr(arg, names);
            }
        }
        Expr::DynamicCall { callee, args, .. } => {
            collect_direct_call_names_from_expr(callee, names);
            for arg in args {
                collect_direct_call_names_from_expr(arg, names);
            }
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            collect_direct_call_names_from_expr(target, names);
            for arg in args {
                collect_direct_call_names_from_expr(arg, names);
            }
        }
        Expr::StaticMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. }
        | Expr::New { args, .. } => {
            for arg in args {
                collect_direct_call_names_from_expr(arg, names);
            }
        }
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            collect_direct_call_names_from_expr(target, names);
            collect_direct_call_names_from_expr(method, names);
            for arg in args {
                collect_direct_call_names_from_expr(arg, names);
            }
        }
        Expr::Array { items, .. } => {
            for item in items {
                if let Some(key) = &item.key {
                    collect_direct_call_names_from_expr(key, names);
                }
                collect_direct_call_names_from_expr(&item.value, names);
            }
        }
        Expr::Index { target, index, .. } => {
            collect_direct_call_names_from_expr(target, names);
            collect_direct_call_names_from_expr(index, names);
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => collect_direct_call_names_from_expr(target, names),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            collect_direct_call_names_from_expr(target, names);
            collect_direct_call_names_from_new_class_name(class_name, names);
        }
        Expr::DynamicProperty {
            target, property, ..
        } => {
            collect_direct_call_names_from_expr(target, names);
            collect_direct_call_names_from_expr(property, names);
        }
        Expr::Binary { left, right, .. } => {
            collect_direct_call_names_from_expr(left, names);
            collect_direct_call_names_from_expr(right, names);
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            collect_direct_call_names_from_expr(condition, names);
            collect_direct_call_names_from_expr(if_true, names);
            collect_direct_call_names_from_expr(if_false, names);
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => {
            collect_direct_call_names_from_expr(condition, names);
            collect_direct_call_names_from_expr(if_false, names);
        }
        Expr::Match { subject, arms, .. } => {
            collect_direct_call_names_from_expr(subject, names);
            for arm in arms {
                for condition in &arm.conditions {
                    collect_direct_call_names_from_expr(condition, names);
                }
                collect_direct_call_names_from_expr(&arm.result, names);
            }
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
            collect_direct_call_names_from_expr(expr, names);
        }
        Expr::IncrementDecrement { target, .. } => {
            collect_direct_call_names_from_assign_target(target, names);
        }
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            collect_direct_call_names_from_expr(expr, names)
        }
        Expr::Closure { .. }
        | Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::InterpolatedString { .. }
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. } => {}
    }
}

fn collect_direct_call_names_from_new_class_name(
    class_name: &NewClassName,
    names: &mut Vec<String>,
) {
    if let NewClassName::DynamicExpression(expr) = class_name {
        collect_direct_call_names_from_expr(expr, names);
    }
}

fn collect_native_arrow_capture_candidates_from_stmts(
    statements: &[Stmt],
    captures: &mut Vec<(String, Span)>,
) {
    for statement in statements {
        collect_native_arrow_capture_candidates_from_stmt(statement, captures);
    }
}

fn collect_native_arrow_capture_candidates_from_stmt(
    stmt: &Stmt,
    captures: &mut Vec<(String, Span)>,
) {
    match stmt {
        Stmt::Echo { exprs, .. } => {
            for expr in exprs {
                collect_native_arrow_capture_candidates_from_expr(expr, captures);
            }
        }
        Stmt::Print { expr, .. }
        | Stmt::Expr { expr, .. }
        | Stmt::Require { path: expr, .. }
        | Stmt::Include { path: expr, .. }
        | Stmt::Throw { expr, .. } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
            collect_native_arrow_capture_candidates_from_reference_source(source, captures);
        }
        Stmt::IncrementDecrement { target, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
        }
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(condition, captures);
            collect_native_arrow_capture_candidates_from_stmts(then_branch, captures);
            collect_native_arrow_capture_candidates_from_stmts(else_branch, captures);
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(condition, captures);
            collect_native_arrow_capture_candidates_from_stmts(body, captures);
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            for action in initializers.iter().chain(increments.iter()) {
                collect_native_arrow_capture_candidates_from_for_action(action, captures);
            }
            for condition in conditions {
                collect_native_arrow_capture_candidates_from_expr(condition, captures);
            }
            collect_native_arrow_capture_candidates_from_stmts(body, captures);
        }
        Stmt::Switch { value, cases, .. } => {
            collect_native_arrow_capture_candidates_from_expr(value, captures);
            for case in cases {
                if let Some(condition) = &case.condition {
                    collect_native_arrow_capture_candidates_from_expr(condition, captures);
                }
                collect_native_arrow_capture_candidates_from_stmts(&case.body, captures);
            }
        }
        Stmt::Foreach { iterable, body, .. } => {
            collect_native_arrow_capture_candidates_from_expr(iterable, captures);
            collect_native_arrow_capture_candidates_from_stmts(body, captures);
        }
        Stmt::UnsetArrayIndex { name, index, span } => {
            captures.push((name.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(index, captures);
        }
        Stmt::UnsetNestedArrayIndex {
            name,
            indices,
            span,
        } => {
            captures.push((name.clone(), *span));
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        Stmt::UnsetObjectProperty { object, span, .. } => {
            captures.push((object.clone(), *span));
        }
        Stmt::UnsetDynamicObjectProperty {
            object,
            property,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        Stmt::UnsetMany { targets, .. } => {
            for target in targets {
                collect_native_arrow_capture_candidates_from_unset_target(target, captures);
            }
        }
        Stmt::ConstDeclaration { declarations, .. } => {
            for declaration in declarations {
                collect_native_arrow_capture_candidates_from_expr(&declaration.value, captures);
            }
        }
        Stmt::Return { value, .. } => {
            if let Some(value) = value {
                collect_native_arrow_capture_candidates_from_expr(value, captures);
            }
        }
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_stmts(body, captures);
            for catch in catches {
                collect_native_arrow_capture_candidates_from_stmts(&catch.body, captures);
            }
            if let Some(finally_body) = finally_body {
                collect_native_arrow_capture_candidates_from_stmts(finally_body, captures);
            }
        }
        Stmt::StaticLocal { declarations, .. } => {
            for declaration in declarations {
                if let Some(default) = &declaration.default {
                    collect_native_arrow_capture_candidates_from_expr(default, captures);
                }
            }
        }
        Stmt::UnsetVariable { name, span } => {
            captures.push((name.clone(), *span));
        }
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::Global { .. } => {}
    }
}

fn collect_native_arrow_capture_candidates_from_for_action(
    action: &ForAction,
    captures: &mut Vec<(String, Span)>,
) {
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        ForAction::IncrementDecrement { target, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
        }
        ForAction::Expr { expr } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures)
        }
    }
}

fn collect_native_arrow_capture_candidates_from_assign_target(
    target: &AssignTarget,
    captures: &mut Vec<(String, Span)>,
) {
    match target {
        AssignTarget::Variable { name, span } => captures.push((name.clone(), *span)),
        AssignTarget::List { names, span } => {
            for name in names.iter().flatten() {
                captures.push((name.clone(), *span));
            }
        }
        AssignTarget::ArrayIndex { name, index, span } => {
            captures.push((name.clone(), *span));
            if let Some(index) = index {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NestedArrayIndex {
            name,
            indices,
            span,
        }
        | AssignTarget::ObjectPropertyArrayIndex {
            object: name,
            indices,
            span,
            ..
        } => {
            captures.push((name.clone(), *span));
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::StaticPropertyArrayIndex { expr, indices, .. } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NestedArrayAppend {
            name,
            indices,
            suffix_indices,
            span,
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            object: name,
            indices,
            suffix_indices,
            span,
            ..
        } => {
            captures.push((name.clone(), *span));
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::StaticPropertyArrayAppend {
            expr,
            indices,
            suffix_indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::Property { object, span, .. } => {
            captures.push((object.clone(), *span));
        }
        AssignTarget::DynamicProperty {
            object,
            property,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        AssignTarget::DynamicObjectPropertyArrayIndex {
            object,
            property,
            indices,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            object,
            property,
            indices,
            suffix_indices,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::ObjectStaticProperty { target: holder, .. } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
        }
        AssignTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices.iter().chain(suffix_indices.iter()) {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => {}
    }
}

fn collect_native_arrow_capture_candidates_from_unset_target(
    target: &UnsetTarget,
    captures: &mut Vec<(String, Span)>,
) {
    match target {
        UnsetTarget::Variable { name, span } => captures.push((name.clone(), *span)),
        UnsetTarget::ArrayIndex { name, index, span } => {
            captures.push((name.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(index, captures);
        }
        UnsetTarget::NestedArrayIndex {
            name,
            indices,
            span,
        }
        | UnsetTarget::ObjectPropertyArrayIndex {
            object: name,
            indices,
            span,
            ..
        } => {
            captures.push((name.clone(), *span));
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        UnsetTarget::StaticPropertyArrayIndex { expr, indices, .. } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        UnsetTarget::ObjectProperty { object, span, .. } => {
            captures.push((object.clone(), *span));
        }
        UnsetTarget::DynamicObjectProperty {
            object,
            property,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            object,
            property,
            indices,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
        }
        UnsetTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        UnsetTarget::ObjectStaticProperty { target, .. } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
        }
        UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => {}
    }
}

fn collect_native_arrow_capture_candidates_from_reference_source(
    source: &ReferenceSource,
    captures: &mut Vec<(String, Span)>,
) {
    match source {
        ReferenceSource::Variable { name, span }
        | ReferenceSource::ArrayIndex { name, span, .. }
        | ReferenceSource::ArrayAppend { name, span, .. }
        | ReferenceSource::NestedArrayIndex { name, span, .. } => {
            captures.push((name.clone(), *span));
        }
        ReferenceSource::ObjectPropertyArrayIndex {
            object,
            index,
            span,
            ..
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(index, captures);
        }
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            object,
            property,
            index,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            collect_native_arrow_capture_candidates_from_expr(index, captures);
        }
        ReferenceSource::ObjectPropertyArrayAppend {
            object,
            indices,
            span,
            ..
        }
        | ReferenceSource::ObjectPropertyNestedArrayIndex {
            object,
            indices,
            span,
            ..
        } => {
            captures.push((object.clone(), *span));
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            object,
            property,
            indices,
            span,
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            object,
            property,
            indices,
            span,
        } => {
            captures.push((object.clone(), *span));
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(holder, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
        ReferenceSource::Property { expr, .. }
        | ReferenceSource::StaticProperty { expr, .. }
        | ReferenceSource::MethodCall { expr, .. } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        ReferenceSource::StaticPropertyArrayIndex { expr, indices, .. }
        | ReferenceSource::ExpressionArrayIndex {
            target: expr,
            indices,
            ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target: expr,
            indices,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
            for index in indices {
                collect_native_arrow_capture_candidates_from_expr(index, captures);
            }
        }
    }
}

fn collect_native_arrow_capture_candidates_from_expr(
    expr: &Expr,
    captures: &mut Vec<(String, Span)>,
) {
    match expr {
        Expr::Variable(name, span) => captures.push((name.clone(), *span)),
        Expr::InterpolatedString { parts, span } => {
            for part in parts {
                match part {
                    InterpolatedStringPart::Literal(_) => {}
                    InterpolatedStringPart::Variable(name)
                    | InterpolatedStringPart::DeprecatedDollarBraceVariable(name)
                    | InterpolatedStringPart::ArrayOffset { variable: name, .. }
                    | InterpolatedStringPart::ObjectProperty { variable: name, .. } => {
                        captures.push((name.clone(), *span));
                    }
                    InterpolatedStringPart::AccessChain { variable, segments } => {
                        captures.push((variable.clone(), *span));
                        for segment in segments {
                            if let InterpolatedAccessSegment::ArrayOffset(
                                InterpolatedArrayKey::Variable(name),
                            ) = segment
                            {
                                captures.push((name.clone(), *span));
                            }
                        }
                    }
                }
                if let InterpolatedStringPart::ArrayOffset {
                    key: InterpolatedArrayKey::Variable(name),
                    ..
                } = part
                {
                    captures.push((name.clone(), *span));
                }
            }
        }
        Expr::Call { args, .. }
        | Expr::StaticMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. } => {
            for arg in args {
                collect_native_arrow_capture_candidates_from_expr(arg, captures);
            }
        }
        Expr::New {
            class_name,
            args,
            span,
        } => {
            match class_name {
                NewClassName::DynamicVariable(name) => captures.push((name.clone(), *span)),
                NewClassName::DynamicExpression(expr) => {
                    collect_native_arrow_capture_candidates_from_expr(expr, captures);
                }
                NewClassName::Named(_)
                | NewClassName::SelfClass
                | NewClassName::ParentClass
                | NewClassName::StaticClass => {}
            }
            for arg in args {
                collect_native_arrow_capture_candidates_from_expr(arg, captures);
            }
        }
        Expr::DynamicCall { callee, args, .. } => {
            collect_native_arrow_capture_candidates_from_expr(callee, captures);
            for arg in args {
                collect_native_arrow_capture_candidates_from_expr(arg, captures);
            }
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
            for arg in args {
                collect_native_arrow_capture_candidates_from_expr(arg, captures);
            }
        }
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
            collect_native_arrow_capture_candidates_from_expr(method, captures);
            for arg in args {
                collect_native_arrow_capture_candidates_from_expr(arg, captures);
            }
        }
        Expr::Array { items, .. } => {
            for item in items {
                if let Some(key) = &item.key {
                    collect_native_arrow_capture_candidates_from_expr(key, captures);
                }
                collect_native_arrow_capture_candidates_from_expr(&item.value, captures);
            }
        }
        Expr::Index { target, index, .. } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
            collect_native_arrow_capture_candidates_from_expr(index, captures);
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
        }
        Expr::InstanceOf {
            expr: target,
            class_name,
            span,
        } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
            collect_native_arrow_capture_candidates_from_new_class_name(
                class_name, *span, captures,
            );
        }
        Expr::DynamicProperty {
            target, property, ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(target, captures);
            collect_native_arrow_capture_candidates_from_expr(property, captures);
        }
        Expr::Binary { left, right, .. } => {
            collect_native_arrow_capture_candidates_from_expr(left, captures);
            collect_native_arrow_capture_candidates_from_expr(right, captures);
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(condition, captures);
            collect_native_arrow_capture_candidates_from_expr(if_true, captures);
            collect_native_arrow_capture_candidates_from_expr(if_false, captures);
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => {
            collect_native_arrow_capture_candidates_from_expr(condition, captures);
            collect_native_arrow_capture_candidates_from_expr(if_false, captures);
        }
        Expr::Match { subject, arms, .. } => {
            collect_native_arrow_capture_candidates_from_expr(subject, captures);
            for arm in arms {
                for condition in &arm.conditions {
                    collect_native_arrow_capture_candidates_from_expr(condition, captures);
                }
                collect_native_arrow_capture_candidates_from_expr(&arm.result, captures);
            }
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        Expr::IncrementDecrement { target, .. } => {
            collect_native_arrow_capture_candidates_from_assign_target(target, captures);
        }
        Expr::Closure {
            params,
            captures: lexical_captures,
            body,
            is_arrow,
            ..
        } => {
            for capture in lexical_captures {
                captures.push((capture.name.clone(), capture.span));
            }
            if *is_arrow {
                let parameter_names = params
                    .iter()
                    .map(|param| param.name.as_str())
                    .collect::<HashSet<_>>();
                let mut nested = Vec::new();
                collect_native_arrow_capture_candidates_from_stmts(body, &mut nested);
                for (name, span) in nested {
                    if !parameter_names.contains(name.as_str()) {
                        captures.push((name, span));
                    }
                }
            }
        }
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. } => {}
    }
}

fn collect_native_arrow_capture_candidates_from_new_class_name(
    class_name: &NewClassName,
    span: Span,
    captures: &mut Vec<(String, Span)>,
) {
    match class_name {
        NewClassName::DynamicVariable(name) => captures.push((name.clone(), span)),
        NewClassName::DynamicExpression(expr) => {
            collect_native_arrow_capture_candidates_from_expr(expr, captures);
        }
        NewClassName::Named(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => {}
    }
}

fn native_for_action_list_call_operation(actions: &[ForAction]) -> Option<NativeCallOperation> {
    actions.iter().find_map(native_for_action_call_operation)
}

fn native_for_action_call_operation(action: &ForAction) -> Option<NativeCallOperation> {
    match action {
        ForAction::Assign { target, expr } => native_assignment_target_call_operation(target)
            .or_else(|| native_statement_operand_call_result_operation(expr)),
        ForAction::CompoundAssign { target, expr, .. } => {
            native_rmw_assignment_target_call_operation(target)
                .or_else(|| native_statement_operand_call_result_operation(expr))
        }
        ForAction::IncrementDecrement { target, .. } => {
            native_rmw_assignment_target_call_operation(target)
        }
        ForAction::Expr { expr } => native_statement_operand_call_result_operation(expr),
    }
}

fn native_comparison_op_for_binary_op(op: BinaryOp) -> Option<NativeComparisonOp> {
    Some(match op {
        BinaryOp::Eq => NativeComparisonOp::LooseEq,
        BinaryOp::Ne => NativeComparisonOp::LooseNe,
        BinaryOp::Lt => NativeComparisonOp::LooseLt,
        BinaryOp::Le => NativeComparisonOp::LooseLe,
        BinaryOp::Gt => NativeComparisonOp::LooseGt,
        BinaryOp::Ge => NativeComparisonOp::LooseGe,
        BinaryOp::StrictEq => NativeComparisonOp::StrictEq,
        BinaryOp::StrictNe => NativeComparisonOp::StrictNe,
        _ => return None,
    })
}

fn native_comparison_c_uint8_argument(op: NativeComparisonOp) -> String {
    (op as u8).to_string()
}

fn native_expr_contains_call_result(expr: &Expr) -> bool {
    match expr {
        Expr::Call { .. }
        | Expr::DynamicCall { .. }
        | Expr::MethodCall { .. }
        | Expr::DynamicMethodCall { .. }
        | Expr::ParentMethodCall { .. }
        | Expr::StaticMethodCall { .. }
        | Expr::ObjectStaticMethodCall { .. }
        | Expr::SelfMethodCall { .. }
        | Expr::LateStaticMethodCall { .. }
        | Expr::New { .. }
        | Expr::Closure { .. } => true,
        Expr::Array { items, .. } => items.iter().any(|item| {
            item.key
                .as_ref()
                .is_some_and(native_expr_contains_call_result)
                || native_expr_contains_call_result(&item.value)
        }),
        Expr::Index { target, index, .. } => {
            native_expr_contains_call_result(target) || native_expr_contains_call_result(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. } => {
            native_expr_contains_call_result(target)
        }
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            native_expr_contains_call_result(target)
                || new_class_name_contains_call_result(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => native_expr_contains_call_result(target) || native_expr_contains_call_result(property),
        Expr::Clone { expr, .. }
        | Expr::Unary { expr, .. }
        | Expr::ErrorControl { expr, .. }
        | Expr::Include { path: expr, .. }
        | Expr::Require { path: expr, .. }
        | Expr::Cast { expr, .. } => native_expr_contains_call_result(expr),
        Expr::Binary { left, right, .. } => {
            native_expr_contains_call_result(left) || native_expr_contains_call_result(right)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            native_expr_contains_call_result(condition)
                || native_expr_contains_call_result(if_true)
                || native_expr_contains_call_result(if_false)
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => {
            native_expr_contains_call_result(condition)
                || native_expr_contains_call_result(if_false)
        }
        Expr::Match { subject, arms, .. } => {
            match_expr_contains(subject, arms, &native_expr_contains_call_result)
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            native_assign_target_contains_call_result(target)
                || native_expr_contains_call_result(expr)
        }
        Expr::IncrementDecrement { target, .. } => {
            native_assign_target_contains_call_result(target)
        }
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            native_expr_contains_call_result(expr)
        }
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::InterpolatedString { .. }
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. } => false,
    }
}

fn new_class_name_contains_call_result(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicExpression(expr) => native_expr_contains_call_result(expr),
        NewClassName::Named(_)
        | NewClassName::DynamicVariable(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn native_assign_target_contains_call_result(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            index.as_ref().is_some_and(native_expr_contains_call_result)
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(native_expr_contains_call_result)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => indices
            .iter()
            .chain(suffix_indices.iter())
            .any(native_expr_contains_call_result),
        AssignTarget::NonDirectProperty { holder, .. } => native_expr_contains_call_result(holder),
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        } => native_expr_contains_call_result(holder) || native_expr_contains_call_result(property),
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            native_expr_contains_call_result(property)
                || indices.iter().any(native_expr_contains_call_result)
        }
        AssignTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => {
            native_expr_contains_call_result(holder)
                || indices.iter().any(native_expr_contains_call_result)
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            native_expr_contains_call_result(holder)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(native_expr_contains_call_result)
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            native_expr_contains_call_result(holder)
                || native_expr_contains_call_result(property)
                || indices.iter().any(native_expr_contains_call_result)
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            native_expr_contains_call_result(holder)
                || native_expr_contains_call_result(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(native_expr_contains_call_result)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            native_expr_contains_call_result(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(native_expr_contains_call_result)
        }
        AssignTarget::DynamicProperty { property, .. }
        | AssignTarget::ObjectStaticProperty {
            target: property, ..
        } => native_expr_contains_call_result(property),
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => false,
    }
}

fn native_reference_source_call_operation(source: &ReferenceSource) -> Option<NativeCallOperation> {
    native_reference_source_call_result_operation(source)
        .or_else(|| native_reference_source_lvalue_operand_call_operation(source))
}

fn native_reference_assignment_call_operation(
    target: &AssignTarget,
    source: &ReferenceSource,
) -> Option<NativeCallOperation> {
    let requirements = native_reference_assignment_operand_list_requirements(target, source);
    if !native_reference_binding_operand_list_is_blocked(&requirements) {
        return None;
    }

    native_assignment_target_call_operation(target)
        .or_else(|| native_reference_source_call_operation(source))
}

fn native_reference_source_call_result_operation(
    source: &ReferenceSource,
) -> Option<NativeCallOperation> {
    let (expr, span) = match source {
        ReferenceSource::MethodCall { expr, span }
        | ReferenceSource::Property { expr, span }
        | ReferenceSource::StaticProperty { expr, span }
        | ReferenceSource::StaticPropertyArrayIndex { expr, span, .. } => (expr, *span),
        ReferenceSource::ExpressionArrayIndex { target, span, .. }
        | ReferenceSource::ExpressionArrayAppend { target, span, .. } => (target, *span),
        ReferenceSource::NonDirectObjectPropertyArrayAppend { holder, span, .. }
        | ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend { holder, span, .. }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex { holder, span, .. }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder, span, ..
        } => (holder, *span),
        _ => return None,
    };

    native_reference_expr_call_callee(expr)
        .map(|callee| NativeCallOperation::reference_result(span, callee))
}

fn native_reference_source_lvalue_operand_call_operation(
    source: &ReferenceSource,
) -> Option<NativeCallOperation> {
    match source {
        ReferenceSource::ArrayIndex { index, .. }
        | ReferenceSource::ObjectPropertyArrayIndex { index, .. } => {
            native_lvalue_operand_call_result_operation(index)
        }
        ReferenceSource::ArrayAppend { indices, .. }
        | ReferenceSource::NestedArrayIndex { indices, .. }
        | ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. } => {
            native_expr_list_call_result_operation(indices)
        }
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            property, index, ..
        } => native_lvalue_operand_call_result_operation(property)
            .or_else(|| native_lvalue_operand_call_result_operation(index)),
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            property, indices, ..
        } => native_lvalue_operand_call_result_operation(property)
            .or_else(|| native_expr_list_call_result_operation(indices)),
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        } => native_lvalue_operand_call_result_operation(holder)
            .or_else(|| native_expr_list_call_result_operation(indices)),
        ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder,
            property,
            indices,
            ..
        } => native_lvalue_operand_call_result_operation(holder)
            .or_else(|| native_lvalue_operand_call_result_operation(property))
            .or_else(|| native_expr_list_call_result_operation(indices)),
        ReferenceSource::Property { expr, .. } | ReferenceSource::StaticProperty { expr, .. } => {
            native_lvalue_operand_call_result_operation(expr)
        }
        ReferenceSource::StaticPropertyArrayIndex { expr, indices, .. } => {
            native_lvalue_operand_call_result_operation(expr)
                .or_else(|| native_expr_list_call_result_operation(indices))
        }
        ReferenceSource::ExpressionArrayIndex {
            target, indices, ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target, indices, ..
        } => native_lvalue_operand_call_result_operation(target)
            .or_else(|| native_expr_list_call_result_operation(indices)),
        ReferenceSource::Variable { .. } | ReferenceSource::MethodCall { .. } => None,
    }
}

fn native_reference_array_item_list_call_operation(
    items: &[ArrayItem],
) -> Option<NativeCallOperation> {
    let requirements = native_reference_array_item_operand_list_requirements(items);
    if !native_reference_binding_operand_list_is_blocked(&requirements) {
        return None;
    }

    items
        .iter()
        .find_map(native_reference_array_item_call_operation)
}

fn native_reference_array_item_call_operation(item: &ArrayItem) -> Option<NativeCallOperation> {
    if !item.by_reference {
        return None;
    }

    native_reference_array_item_value_call_operation(&item.value)
}

fn native_reference_array_item_value_call_operation(expr: &Expr) -> Option<NativeCallOperation> {
    NativeCallResultConsumer::ReferenceResult
        .operation(expr)
        .or_else(|| native_lvalue_operand_call_result_operation(expr))
}

fn native_reference_expr_call_callee(expr: &Expr) -> Option<NativeCallCallee> {
    if let Some(callee) = native_call_callee_for_expr(expr) {
        return Some(callee);
    }

    match expr {
        Expr::Index { target, .. }
        | Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::DynamicProperty { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. } => {
            native_reference_expr_call_callee(target)
        }
        _ => None,
    }
}

fn native_dereferenced_call_result_operation(expr: &Expr) -> Option<NativeCallOperation> {
    NativeCallResultConsumer::DereferencedValue.operation(expr)
}

fn native_assignment_target_call_result_operation(
    target: &AssignTarget,
) -> Option<NativeCallOperation> {
    native_assignment_target_call_result_callee(target)
        .map(|callee| callee.dereferenced_value_result_operation(target.span()))
}

fn native_assignment_target_call_result_callee(target: &AssignTarget) -> Option<NativeCallCallee> {
    match target {
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayAppend { holder, .. }
        | AssignTarget::NonDirectDynamicProperty { holder, .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex { holder, .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { holder, .. } => {
            native_reference_expr_call_callee(holder)
        }
        AssignTarget::ObjectStaticProperty { target, .. }
        | AssignTarget::DynamicObjectStaticProperty { target, .. } => {
            native_reference_expr_call_callee(target)
        }
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::ArrayIndex { .. }
        | AssignTarget::NestedArrayIndex { .. }
        | AssignTarget::NestedArrayAppend { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::ObjectPropertyArrayIndex { .. }
        | AssignTarget::DynamicObjectPropertyArrayIndex { .. }
        | AssignTarget::ObjectPropertyArrayAppend { .. }
        | AssignTarget::DynamicObjectPropertyArrayAppend { .. }
        | AssignTarget::DynamicProperty { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::StaticPropertyArrayIndex { .. }
        | AssignTarget::StaticPropertyArrayAppend { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => None,
    }
}

fn native_assignment_target_call_operation(target: &AssignTarget) -> Option<NativeCallOperation> {
    native_assignment_target_call_result_operation(target)
        .or_else(|| native_assignment_target_lvalue_operand_call_operation(target))
}

fn native_rmw_assignment_target_call_operation(
    target: &AssignTarget,
) -> Option<NativeCallOperation> {
    native_assignment_target_call_result_operation(target)
        .or_else(|| native_rmw_assignment_target_lvalue_operand_call_operation(target))
}

fn native_assignment_target_lvalue_operand_call_operation(
    target: &AssignTarget,
) -> Option<NativeCallOperation> {
    let requirements = native_assignment_target_lvalue_operand_requirements(target);
    if !native_assignment_lvalue_operand_list_is_blocked(&requirements) {
        return None;
    }

    native_assignment_target_lvalue_operands(target)
        .into_iter()
        .find_map(|(expr, _)| native_lvalue_operand_call_result_operation(expr))
}

fn native_rmw_assignment_target_lvalue_operand_call_operation(
    target: &AssignTarget,
) -> Option<NativeCallOperation> {
    let requirements = native_rmw_assignment_target_lvalue_operand_requirements(target);
    if !native_rmw_lvalue_operand_list_is_blocked(&requirements) {
        return None;
    }

    native_assignment_target_lvalue_operands(target)
        .into_iter()
        .find_map(|(expr, _)| native_rmw_lvalue_operand_call_result_operation(expr))
}

fn native_rmw_lvalue_operand_call_result_operation(expr: &Expr) -> Option<NativeCallOperation> {
    NativeCallResultConsumer::RmwLvalueOperand.operation(expr)
}

fn native_assignment_target_lvalue_operands(target: &AssignTarget) -> Vec<(&Expr, u8)> {
    let receiver_tag = PHPC_NATIVE_DIAGNOSTIC_OPERAND_ASSIGNMENT_TARGET_RECEIVER_EVALUATION;
    let property_tag = PHPC_NATIVE_DIAGNOSTIC_OPERAND_ASSIGNMENT_TARGET_PROPERTY_EVALUATION;
    let key_tag = PHPC_NATIVE_DIAGNOSTIC_OPERAND_ASSIGNMENT_TARGET_KEY_EVALUATION;

    let mut operands = Vec::new();
    match target {
        AssignTarget::ArrayIndex { index, .. } => {
            operands.extend(index.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            operands.extend(indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => {
            operands.extend(indices.iter().map(|index| (index, key_tag)));
            operands.extend(suffix_indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NonDirectProperty { holder, .. } => {
            operands.push((holder, receiver_tag));
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        } => {
            operands.push((holder, receiver_tag));
            operands.push((property, property_tag));
        }
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            operands.push((property, property_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => {
            operands.push((holder, receiver_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            operands.push((holder, receiver_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
            operands.extend(suffix_indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            operands.push((holder, receiver_tag));
            operands.push((property, property_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            operands.push((holder, receiver_tag));
            operands.push((property, property_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
            operands.extend(suffix_indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            operands.push((property, property_tag));
            operands.extend(indices.iter().map(|index| (index, key_tag)));
            operands.extend(suffix_indices.iter().map(|index| (index, key_tag)));
        }
        AssignTarget::DynamicProperty { property, .. } => {
            operands.push((property, property_tag));
        }
        AssignTarget::ObjectStaticProperty { target, .. }
        | AssignTarget::DynamicObjectStaticProperty { target, .. } => {
            operands.push((target, receiver_tag));
        }
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => {}
    }
    operands
}

fn native_unset_target_call_operation(target: &UnsetTarget) -> Option<NativeCallOperation> {
    match target {
        UnsetTarget::ArrayIndex { index, .. } => native_lvalue_operand_call_result_operation(index),
        UnsetTarget::NestedArrayIndex { indices, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            native_expr_list_call_result_operation(indices)
        }
        UnsetTarget::NonDirectObjectPropertyArrayIndex {
            holder, indices, ..
        } => native_lvalue_operand_call_result_operation(holder)
            .or_else(|| native_expr_list_call_result_operation(indices)),
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => native_lvalue_operand_call_result_operation(property)
            .or_else(|| native_expr_list_call_result_operation(indices)),
        UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder,
            property,
            indices,
            ..
        } => native_lvalue_operand_call_result_operation(holder)
            .or_else(|| native_lvalue_operand_call_result_operation(property))
            .or_else(|| native_expr_list_call_result_operation(indices)),
        UnsetTarget::DynamicObjectProperty { property, .. } => {
            native_lvalue_operand_call_result_operation(property)
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. } => {
            native_lvalue_operand_call_result_operation(holder)
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        } => native_lvalue_operand_call_result_operation(holder)
            .or_else(|| native_lvalue_operand_call_result_operation(property)),
        UnsetTarget::ObjectStaticProperty { target, .. } => {
            native_lvalue_operand_call_result_operation(target)
        }
        UnsetTarget::Variable { .. }
        | UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => None,
    }
}

fn native_expr_list_call_result_operation(exprs: &[Expr]) -> Option<NativeCallOperation> {
    let requirements = native_lvalue_operand_list_requirements(exprs);
    if !native_diagnostic_operation_list_is_blocked(
        PHPC_NATIVE_DIAGNOSTIC_OPERATION_LVALUE_OPERAND_LIST,
        &requirements,
    ) {
        return None;
    }

    exprs
        .iter()
        .find_map(native_lvalue_operand_call_result_operation)
}

fn native_value_call_operation_for_expr(expr: &Expr) -> Option<NativeCallOperation> {
    let (span, callee, default_blocker, args) = match expr {
        Expr::Call { args, span, .. } => (
            *span,
            NativeCallCallee::DirectNamed,
            NativeCallBlocker::UnknownCalleeDiagnostics,
            args.as_slice(),
        ),
        Expr::DynamicCall { args, span, .. } => (
            *span,
            NativeCallCallee::DynamicExpression,
            NativeCallBlocker::DynamicCallableEvaluation,
            args.as_slice(),
        ),
        Expr::MethodCall { span, .. }
        | Expr::DynamicMethodCall { span, .. }
        | Expr::ParentMethodCall { span, .. }
        | Expr::StaticMethodCall { span, .. }
        | Expr::ObjectStaticMethodCall { span, .. }
        | Expr::SelfMethodCall { span, .. }
        | Expr::LateStaticMethodCall { span, .. } => (
            *span,
            NativeCallCallee::MethodDispatch,
            NativeCallBlocker::MethodDispatch,
            native_call_args_for_expr(expr),
        ),
        Expr::New {
            class_name,
            args,
            span,
        } => {
            if let Some(operation) =
                native_constructor_symbol_environment_operation_for_class_name(class_name, *span)
            {
                return Some(operation);
            }
            (
                *span,
                NativeCallCallee::ConstructorDispatch,
                NativeCallBlocker::ConstructorDispatch,
                args.as_slice(),
            )
        }
        _ => return None,
    };
    let blocker = native_call_argument_list_blocker(args).unwrap_or(default_blocker);

    Some(match callee {
        NativeCallCallee::DirectNamed => NativeCallOperation::direct_named_value(span, blocker),
        NativeCallCallee::DynamicExpression
            if blocker == NativeCallBlocker::DynamicCallableEvaluation =>
        {
            NativeCallOperation::dynamic_value(span)
        }
        NativeCallCallee::DynamicExpression => {
            NativeCallOperation::dynamic_value_with_blocker(span, blocker)
        }
        NativeCallCallee::MethodDispatch if blocker == NativeCallBlocker::MethodDispatch => {
            NativeCallOperation::method_value(span)
        }
        NativeCallCallee::MethodDispatch => {
            NativeCallOperation::method_value_with_blocker(span, blocker)
        }
        NativeCallCallee::ConstructorDispatch => {
            NativeCallOperation::constructor_value(span, blocker)
        }
        NativeCallCallee::FunctionFrame => {
            unreachable!("value-call classifier cannot produce a function-frame callee")
        }
        NativeCallCallee::ClosureFrame => {
            unreachable!("value-call classifier cannot produce a closure-frame callee")
        }
    })
}

fn native_call_root_operation(expr: &Expr) -> Option<NativeCallOperation> {
    match expr {
        Expr::Closure {
            params,
            returns_by_reference,
            span,
            ..
        } => Some(NativeCallOperation::closure_frame(
            *span,
            native_closure_frame_blocker(params, *returns_by_reference),
        )),
        _ => native_value_call_operation_for_expr(expr),
    }
}

fn native_call_args_for_expr(expr: &Expr) -> &[Expr] {
    match expr {
        Expr::MethodCall { args, .. }
        | Expr::DynamicMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::StaticMethodCall { args, .. }
        | Expr::ObjectStaticMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. } => args.as_slice(),
        _ => unreachable!("native call args requested for a non-method call expression"),
    }
}

fn native_constructor_symbol_environment_operation_for_class_name(
    class_name: &NewClassName,
    span: Span,
) -> Option<NativeCallOperation> {
    new_class_name_symbol_environment_span(class_name, span).map(|span| {
        NativeCallOperation::constructor_value(span, NativeCallBlocker::GlobalFrameSeparation)
    })
}

fn new_class_name_symbol_environment_span(class_name: &NewClassName, span: Span) -> Option<Span> {
    match class_name {
        NewClassName::DynamicVariable(name) if is_frame_separated_symbol_environment_name(name) => {
            Some(span)
        }
        _ => None,
    }
}

fn native_call_callee_for_expr(expr: &Expr) -> Option<NativeCallCallee> {
    native_value_call_operation_for_expr(expr).map(|operation| operation.callee)
}

fn native_call_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match operation.callee {
        NativeCallCallee::DirectNamed => native_direct_call_blocker_message(backend, operation),
        NativeCallCallee::DynamicExpression => {
            native_dynamic_call_blocker_message(backend, operation)
        }
        NativeCallCallee::MethodDispatch => native_method_call_blocker_message(backend, operation),
        NativeCallCallee::ConstructorDispatch => {
            native_constructor_call_blocker_message(backend, operation)
        }
        NativeCallCallee::FunctionFrame => {
            native_function_frame_blocker_message(backend, operation)
        }
        NativeCallCallee::ClosureFrame => native_closure_frame_blocker_message(backend, operation),
    }
}

fn native_call_operation_diagnostic(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> Diagnostic {
    Diagnostic::new(
        Phase::Codegen,
        operation.span.line,
        operation.span.column,
        native_call_blocker_message(backend, operation),
    )
}

fn native_function_declaration_fallback_diagnostic(
    backend: NativeCallBackend,
    function: &FunctionDecl,
    static_local_rejection: &'static str,
) -> Diagnostic {
    if let Some(span) = find_static_local_span(&function.body) {
        return Diagnostic::new(
            Phase::Codegen,
            span.line,
            span.column,
            static_local_rejection,
        );
    }

    native_call_operation_diagnostic(backend, native_function_frame_call_operation(function))
}

fn native_direct_call_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::Value,
            NativeCallBlocker::ArgumentEvaluationCleanup
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::StatementOperandEvaluationCleanup
            | NativeCallBlocker::ValueOperandEvaluationCleanup
            | NativeCallBlocker::LvalueOperandEvaluationCleanup
            | NativeCallBlocker::RmwLvalueOperandEvaluationCleanup
            | NativeCallBlocker::ReturnValueOwnership
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::UnknownCalleeDiagnostics,
        ) => backend.function_call_rejection(),
        (
            NativeCallResult::Reference,
            NativeCallBlocker::ReferenceBinding
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.reference_assignment_rejection(),
        _ => unreachable!("invalid native direct-call blocker contract"),
    }
}

fn native_dynamic_call_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::Value,
            NativeCallBlocker::DynamicCallableEvaluation
            | NativeCallBlocker::ArgumentEvaluationCleanup
            | NativeCallBlocker::StatementOperandEvaluationCleanup
            | NativeCallBlocker::ValueOperandEvaluationCleanup
            | NativeCallBlocker::LvalueOperandEvaluationCleanup
            | NativeCallBlocker::RmwLvalueOperandEvaluationCleanup
            | NativeCallBlocker::ReturnValueOwnership
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::UnknownCalleeDiagnostics,
        ) => backend.dynamic_function_call_rejection(),
        (
            NativeCallResult::Reference,
            NativeCallBlocker::ReferenceBinding
            | NativeCallBlocker::DynamicCallableEvaluation
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.reference_assignment_rejection(),
        _ => unreachable!("invalid native dynamic-call blocker contract"),
    }
}

fn native_method_call_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::Value,
            NativeCallBlocker::MethodDispatch
            | NativeCallBlocker::ArgumentEvaluationCleanup
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::StatementOperandEvaluationCleanup
            | NativeCallBlocker::ValueOperandEvaluationCleanup
            | NativeCallBlocker::LvalueOperandEvaluationCleanup
            | NativeCallBlocker::RmwLvalueOperandEvaluationCleanup
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.method_call_rejection(),
        (
            NativeCallResult::Reference,
            NativeCallBlocker::ReferenceBinding
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.reference_assignment_rejection(),
        _ => unreachable!("invalid native method-call blocker contract"),
    }
}

fn native_constructor_call_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::Value,
            NativeCallBlocker::ConstructorDispatch
            | NativeCallBlocker::DestructorObservableCleanup
            | NativeCallBlocker::ArgumentEvaluationCleanup
            | NativeCallBlocker::StatementOperandEvaluationCleanup
            | NativeCallBlocker::ValueOperandEvaluationCleanup
            | NativeCallBlocker::LvalueOperandEvaluationCleanup
            | NativeCallBlocker::RmwLvalueOperandEvaluationCleanup
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.object_instantiation_rejection(),
        (
            NativeCallResult::Reference,
            NativeCallBlocker::ReferenceBinding | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.reference_assignment_rejection(),
        _ => unreachable!("invalid native constructor-call blocker contract"),
    }
}

fn native_function_frame_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::FrameHandoff,
            NativeCallBlocker::FunctionFrameHandoff
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::ReturnValueOwnership,
        )
        | (NativeCallResult::Value, NativeCallBlocker::ReturnValueOwnership) => {
            backend.function_declaration_rejection()
        }
        _ => unreachable!("invalid native function-frame blocker contract"),
    }
}

fn native_closure_frame_blocker_message(
    backend: NativeCallBackend,
    operation: NativeCallOperation,
) -> &'static str {
    match (operation.result, operation.blocker) {
        (
            NativeCallResult::FrameHandoff,
            NativeCallBlocker::ClosureFrameHandoff
            | NativeCallBlocker::ByReferenceArgumentBinding
            | NativeCallBlocker::GlobalFrameSeparation
            | NativeCallBlocker::ReturnValueOwnership,
        ) => backend.closure_rejection(),
        _ => unreachable!("invalid native closure-frame blocker contract"),
    }
}

pub fn emit_llvm_ir(program: &Program) -> CompileResult<String> {
    let mut generator = LlvmGenerator::default();
    generator.emit_program(program)
}

pub fn emit_assembly(program: &Program) -> CompileResult<String> {
    let ir = emit_llvm_ir(program)?;
    if command_available("clang") {
        return clang_assembly_from_ir(&ir);
    }
    if command_available("llc") {
        return llc_assembly_from_ir(&ir);
    }
    if command_available("cc") {
        let c_source = emit_c_source_for_assembly(program)?;
        return cc_assembly_from_c(&c_source);
    }

    Err(Diagnostic::new(
        Phase::Codegen,
        0,
        0,
        "no assembly backend found; install clang, llc, or cc",
    ))
}

fn is_request_superglobal_name(name: &str) -> bool {
    matches!(
        name,
        "_SERVER" | "_COOKIE" | "_GET" | "_POST" | "_REQUEST" | "_FILES" | "_SESSION"
    )
}

const REQUEST_SUPERGLOBAL_NAMES: [&str; 7] = [
    "_SERVER", "_COOKIE", "_GET", "_POST", "_REQUEST", "_FILES", "_SESSION",
];

fn is_globals_superglobal_name(name: &str) -> bool {
    name == "GLOBALS"
}

fn is_frame_separated_symbol_environment_name(name: &str) -> bool {
    is_globals_superglobal_name(name) || is_request_superglobal_name(name)
}

fn static_string_key_expr_value(expr: &Expr) -> Option<String> {
    match expr {
        Expr::String(value, _) => Some(value.clone()),
        Expr::Binary {
            left,
            op: BinaryOp::Concat,
            right,
            ..
        } => {
            let mut value = static_string_key_expr_value(left)?;
            value.push_str(&static_string_key_expr_value(right)?);
            Some(value)
        }
        _ => None,
    }
}

fn globals_request_superglobal_alias_path<'a>(
    indices: &'a [&'a Expr],
) -> Option<(String, &'a [&'a Expr])> {
    let mut remaining = indices;
    while let Some((first, rest)) = remaining.split_first() {
        let Some(name) = static_string_key_expr_value(first) else {
            return None;
        };
        if is_globals_superglobal_name(&name) {
            remaining = rest;
            continue;
        }
        if is_request_superglobal_name(&name) {
            return Some((name, rest));
        }
        return None;
    }
    None
}

fn globals_indices_may_reference_request_superglobal(indices: &[&Expr]) -> bool {
    let mut remaining = indices;
    while let Some((first, rest)) = remaining.split_first() {
        let Some(name) = static_string_key_expr_value(first) else {
            return true;
        };
        if is_globals_superglobal_name(&name) {
            remaining = rest;
            continue;
        }
        return is_request_superglobal_name(&name);
    }
    false
}

fn globals_alias_expr_may_reference_request_superglobal(expr: &Expr) -> bool {
    let mut indices = Vec::new();
    let mut target = expr;
    loop {
        match target {
            Expr::Index {
                target: nested,
                index,
                ..
            } => {
                indices.push(index.as_ref());
                target = nested;
            }
            Expr::AppendIndex { target: nested, .. } => {
                target = nested;
            }
            Expr::Variable(name, _) if is_globals_superglobal_name(name) => {
                indices.reverse();
                return globals_indices_may_reference_request_superglobal(&indices);
            }
            _ => return false,
        }
    }
}

fn expr_contains_globals_access(expr: &Expr) -> bool {
    match expr {
        Expr::Variable(name, _) if is_globals_superglobal_name(name) => true,
        Expr::InterpolatedString { parts, .. } => parts
            .iter()
            .any(interpolated_string_part_contains_globals_access),
        Expr::Call { args, .. }
        | Expr::StaticMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. }
        | Expr::New { args, .. } => args.iter().any(expr_contains_globals_access),
        Expr::DynamicCall { callee, args, .. } => {
            expr_contains_globals_access(callee) || args.iter().any(expr_contains_globals_access)
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            expr_contains_globals_access(target) || args.iter().any(expr_contains_globals_access)
        }
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            expr_contains_globals_access(target)
                || expr_contains_globals_access(method)
                || args.iter().any(expr_contains_globals_access)
        }
        Expr::Array { items, .. } => items.iter().any(|item| {
            item.key.as_ref().is_some_and(expr_contains_globals_access)
                || expr_contains_globals_access(&item.value)
        }),
        Expr::Index { target, index, .. } => {
            expr_contains_globals_access(target) || expr_contains_globals_access(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => expr_contains_globals_access(target),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            expr_contains_globals_access(target)
                || new_class_name_contains_globals_access(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => expr_contains_globals_access(target) || expr_contains_globals_access(property),
        Expr::Binary { left, right, .. } => {
            expr_contains_globals_access(left) || expr_contains_globals_access(right)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            expr_contains_globals_access(condition)
                || expr_contains_globals_access(if_true)
                || expr_contains_globals_access(if_false)
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => expr_contains_globals_access(condition) || expr_contains_globals_access(if_false),
        Expr::Match { subject, arms, .. } => {
            match_expr_contains(subject, arms, &expr_contains_globals_access)
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_globals_access(target) || expr_contains_globals_access(expr)
        }
        Expr::IncrementDecrement { target, .. } => assign_target_contains_globals_access(target),
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            expr_contains_globals_access(expr)
        }
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. }
        | Expr::Closure { .. } => false,
    }
}

fn new_class_name_contains_globals_access(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicVariable(name) => is_globals_superglobal_name(name),
        NewClassName::DynamicExpression(expr) => expr_contains_globals_access(expr),
        NewClassName::Named(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn interpolated_string_part_contains_globals_access(part: &InterpolatedStringPart) -> bool {
    match part {
        InterpolatedStringPart::Variable(name)
        | InterpolatedStringPart::DeprecatedDollarBraceVariable(name)
        | InterpolatedStringPart::ArrayOffset { variable: name, .. }
        | InterpolatedStringPart::ObjectProperty { variable: name, .. }
        | InterpolatedStringPart::AccessChain { variable: name, .. } => {
            is_globals_superglobal_name(name)
        }
        InterpolatedStringPart::Literal(_) => false,
    }
}

fn target_name_is_globals(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::Variable { name, .. }
        | AssignTarget::ArrayIndex { name, .. }
        | AssignTarget::NestedArrayIndex { name, .. }
        | AssignTarget::NestedArrayAppend { name, .. } => is_globals_superglobal_name(name),
        _ => false,
    }
}

fn assign_target_contains_globals_access(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::Variable { name, .. } => is_globals_superglobal_name(name),
        AssignTarget::ArrayIndex { index, .. } => {
            target_name_is_globals(target)
                || index.as_ref().is_some_and(expr_contains_globals_access)
        }
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            target_name_is_globals(target) || indices.iter().any(expr_contains_globals_access)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => {
            target_name_is_globals(target)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_globals_access)
        }
        AssignTarget::DynamicProperty { property, .. } => expr_contains_globals_access(property),
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_globals_access(property)
                || indices.iter().any(expr_contains_globals_access)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_globals_access(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_globals_access)
        }
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::ObjectStaticProperty { target: holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_globals_access(holder)
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_globals_access(holder)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_globals_access)
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => expr_contains_globals_access(holder) || expr_contains_globals_access(property),
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_globals_access(holder)
                || expr_contains_globals_access(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_globals_access)
        }
        AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => false,
    }
}

fn reference_source_contains_globals_access(source: &ReferenceSource) -> bool {
    match source {
        ReferenceSource::Variable { name, .. } => is_globals_superglobal_name(name),
        ReferenceSource::ArrayIndex { name, index, .. } => {
            is_globals_superglobal_name(name) || expr_contains_globals_access(index)
        }
        ReferenceSource::ArrayAppend { name, indices, .. }
        | ReferenceSource::NestedArrayIndex { name, indices, .. } => {
            is_globals_superglobal_name(name) || indices.iter().any(expr_contains_globals_access)
        }
        ReferenceSource::ObjectPropertyArrayIndex { index, .. } => {
            expr_contains_globals_access(index)
        }
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            property, index, ..
        } => expr_contains_globals_access(property) || expr_contains_globals_access(index),
        ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_globals_access)
        }
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            property, indices, ..
        } => {
            expr_contains_globals_access(property)
                || indices.iter().any(expr_contains_globals_access)
        }
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        } => {
            expr_contains_globals_access(holder) || indices.iter().any(expr_contains_globals_access)
        }
        ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            expr_contains_globals_access(holder)
                || expr_contains_globals_access(property)
                || indices.iter().any(expr_contains_globals_access)
        }
        ReferenceSource::StaticPropertyArrayIndex { expr, indices, .. }
        | ReferenceSource::ExpressionArrayIndex {
            target: expr,
            indices,
            ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target: expr,
            indices,
            ..
        } => expr_contains_globals_access(expr) || indices.iter().any(expr_contains_globals_access),
        ReferenceSource::Property { expr, .. }
        | ReferenceSource::StaticProperty { expr, .. }
        | ReferenceSource::MethodCall { expr, .. } => expr_contains_globals_access(expr),
    }
}

fn for_action_contains_globals_access(action: &ForAction) -> bool {
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            assign_target_contains_globals_access(target) || expr_contains_globals_access(expr)
        }
        ForAction::IncrementDecrement { target, .. } => {
            assign_target_contains_globals_access(target)
        }
        ForAction::Expr { expr } => expr_contains_globals_access(expr),
    }
}

fn unset_target_contains_globals_access(target: &UnsetTarget) -> bool {
    match target {
        UnsetTarget::Variable { name, .. } => is_globals_superglobal_name(name),
        UnsetTarget::ArrayIndex { name, index, .. } => {
            is_globals_superglobal_name(name) || expr_contains_globals_access(index)
        }
        UnsetTarget::NestedArrayIndex { name, indices, .. } => {
            is_globals_superglobal_name(name) || indices.iter().any(expr_contains_globals_access)
        }
        UnsetTarget::DynamicObjectProperty {
            property: index, ..
        } => expr_contains_globals_access(index),
        UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_globals_access)
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_globals_access(property)
                || indices.iter().any(expr_contains_globals_access)
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_globals_access(holder)
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => expr_contains_globals_access(holder) || expr_contains_globals_access(property),
        UnsetTarget::ObjectStaticProperty { target, .. } => expr_contains_globals_access(target),
        UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => false,
    }
}

fn stmt_list_contains_request_state_access(statements: &[Stmt]) -> bool {
    statements.iter().any(stmt_contains_request_state_access)
}

fn stmt_contains_request_state_access(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Echo { exprs, .. } => exprs.iter().any(expr_contains_request_state_access),
        Stmt::Print { expr, .. }
        | Stmt::Expr { expr, .. }
        | Stmt::Require { path: expr, .. }
        | Stmt::Include { path: expr, .. }
        | Stmt::Throw { expr, .. } => expr_contains_request_state_access(expr),
        Stmt::Assign { target, expr, .. }
        | Stmt::CompoundAssign { target, expr, .. }
        | Stmt::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_request_state_access(target)
                || expr_contains_request_state_access(expr)
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            assign_target_contains_request_state_access(target)
                || reference_source_contains_request_state_access(source)
        }
        Stmt::IncrementDecrement { target, .. } => {
            assign_target_contains_request_state_access(target)
        }
        Stmt::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => {
            expr_contains_request_state_access(condition)
                || stmt_list_contains_request_state_access(then_branch)
                || stmt_list_contains_request_state_access(else_branch)
        }
        Stmt::While {
            condition, body, ..
        }
        | Stmt::DoWhile {
            condition, body, ..
        } => {
            expr_contains_request_state_access(condition)
                || stmt_list_contains_request_state_access(body)
        }
        Stmt::For {
            initializers,
            conditions,
            increments,
            body,
            ..
        } => {
            initializers
                .iter()
                .chain(increments.iter())
                .any(for_action_contains_request_state_access)
                || conditions.iter().any(expr_contains_request_state_access)
                || stmt_list_contains_request_state_access(body)
        }
        Stmt::Switch { value, cases, .. } => {
            expr_contains_request_state_access(value)
                || cases.iter().any(|case| {
                    case.condition
                        .as_ref()
                        .is_some_and(expr_contains_request_state_access)
                        || stmt_list_contains_request_state_access(&case.body)
                })
        }
        Stmt::Foreach { iterable, body, .. } => {
            expr_contains_request_state_access(iterable)
                || stmt_list_contains_request_state_access(body)
        }
        Stmt::UnsetVariable { name, .. } => is_request_superglobal_name(name),
        Stmt::UnsetArrayIndex { name, index, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(&[index]))
                || expr_contains_request_state_access(index)
        }
        Stmt::UnsetNestedArrayIndex { name, indices, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(
                        &indices.iter().collect::<Vec<_>>(),
                    ))
                || indices.iter().any(expr_contains_request_state_access)
        }
        Stmt::UnsetDynamicObjectProperty { property, .. } => {
            expr_contains_request_state_access(property)
        }
        Stmt::UnsetMany { targets, .. } => targets
            .iter()
            .any(unset_target_contains_request_state_access),
        Stmt::ConstDeclaration { declarations, .. } => declarations
            .iter()
            .any(|declaration| expr_contains_request_state_access(&declaration.value)),
        Stmt::Return { value, .. } => value
            .as_ref()
            .is_some_and(expr_contains_request_state_access),
        Stmt::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            stmt_list_contains_request_state_access(body)
                || catches
                    .iter()
                    .any(|catch| stmt_list_contains_request_state_access(&catch.body))
                || finally_body
                    .as_ref()
                    .is_some_and(|body| stmt_list_contains_request_state_access(body))
        }
        Stmt::StaticLocal { declarations, .. } => declarations.iter().any(|declaration| {
            declaration
                .default
                .as_ref()
                .is_some_and(expr_contains_request_state_access)
        }),
        Stmt::Namespace { .. }
        | Stmt::Use { .. }
        | Stmt::Goto { .. }
        | Stmt::Label { .. }
        | Stmt::UnsetObjectProperty { .. }
        | Stmt::UnsetStaticProperty { .. }
        | Stmt::UnsetSelfStaticProperty { .. }
        | Stmt::UnsetParentStaticProperty { .. }
        | Stmt::UnsetLateStaticProperty { .. }
        | Stmt::Function(_)
        | Stmt::Interface(_)
        | Stmt::Trait(_)
        | Stmt::Enum(_)
        | Stmt::Class(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::Global { .. } => false,
    }
}

fn expr_contains_request_state_access(expr: &Expr) -> bool {
    if globals_alias_expr_may_reference_request_superglobal(expr) {
        return true;
    }
    match expr {
        Expr::Variable(name, _) if is_request_superglobal_name(name) => true,
        Expr::InterpolatedString { parts, .. } => parts
            .iter()
            .any(interpolated_string_part_contains_request_state_access),
        Expr::Call { args, .. }
        | Expr::StaticMethodCall { args, .. }
        | Expr::ParentMethodCall { args, .. }
        | Expr::SelfMethodCall { args, .. }
        | Expr::LateStaticMethodCall { args, .. }
        | Expr::New { args, .. } => args.iter().any(expr_contains_request_state_access),
        Expr::DynamicCall { callee, args, .. } => {
            expr_contains_request_state_access(callee)
                || args.iter().any(expr_contains_request_state_access)
        }
        Expr::MethodCall { target, args, .. }
        | Expr::ObjectStaticMethodCall { target, args, .. } => {
            expr_contains_request_state_access(target)
                || args.iter().any(expr_contains_request_state_access)
        }
        Expr::DynamicMethodCall {
            target,
            method,
            args,
            ..
        } => {
            expr_contains_request_state_access(target)
                || expr_contains_request_state_access(method)
                || args.iter().any(expr_contains_request_state_access)
        }
        Expr::Array { items, .. } => items.iter().any(|item| {
            item.key
                .as_ref()
                .is_some_and(expr_contains_request_state_access)
                || expr_contains_request_state_access(&item.value)
        }),
        Expr::Index { target, index, .. } => {
            expr_contains_request_state_access(target) || expr_contains_request_state_access(index)
        }
        Expr::AppendIndex { target, .. }
        | Expr::Property { target, .. }
        | Expr::ObjectStaticClassConstant { target, .. }
        | Expr::ObjectStaticProperty { target, .. }
        | Expr::ObjectClassNameConstant { target, .. }
        | Expr::DynamicObjectStaticProperty { target, .. }
        | Expr::Clone { expr: target, .. }
        | Expr::Unary { expr: target, .. }
        | Expr::ErrorControl { expr: target, .. }
        | Expr::Include { path: target, .. }
        | Expr::Require { path: target, .. }
        | Expr::Cast { expr: target, .. } => expr_contains_request_state_access(target),
        Expr::InstanceOf {
            expr: target,
            class_name,
            ..
        } => {
            expr_contains_request_state_access(target)
                || new_class_name_contains_request_state_access(class_name)
        }
        Expr::DynamicProperty {
            target, property, ..
        } => {
            expr_contains_request_state_access(target)
                || expr_contains_request_state_access(property)
        }
        Expr::Binary { left, right, .. } => {
            expr_contains_request_state_access(left) || expr_contains_request_state_access(right)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            expr_contains_request_state_access(condition)
                || expr_contains_request_state_access(if_true)
                || expr_contains_request_state_access(if_false)
        }
        Expr::ShortTernary {
            condition,
            if_false,
            ..
        } => {
            expr_contains_request_state_access(condition)
                || expr_contains_request_state_access(if_false)
        }
        Expr::Match { subject, arms, .. } => {
            match_expr_contains(subject, arms, &expr_contains_request_state_access)
        }
        Expr::Assign { target, expr, .. }
        | Expr::CompoundAssign { target, expr, .. }
        | Expr::NullCoalesceAssign { target, expr, .. } => {
            assign_target_contains_request_state_access(target)
                || expr_contains_request_state_access(expr)
        }
        Expr::IncrementDecrement { target, .. } => {
            assign_target_contains_request_state_access(target)
        }
        Expr::NamedArgument { expr, .. } | Expr::SpreadArgument { expr, .. } => {
            expr_contains_request_state_access(expr)
        }
        Expr::Null(_)
        | Expr::Bool(_, _)
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::Variable(_, _)
        | Expr::MagicLine { .. }
        | Expr::MagicFile { .. }
        | Expr::MagicDir { .. }
        | Expr::MagicFunction { .. }
        | Expr::MagicClass { .. }
        | Expr::MagicMethod { .. }
        | Expr::GlobalConstant { .. }
        | Expr::ClassNameConstant { .. }
        | Expr::SelfClassNameConstant { .. }
        | Expr::ParentClassNameConstant { .. }
        | Expr::StaticClassNameConstant { .. }
        | Expr::ClassConstant { .. }
        | Expr::SelfClassConstant { .. }
        | Expr::ParentClassConstant { .. }
        | Expr::LateStaticClassConstant { .. }
        | Expr::StaticProperty { .. }
        | Expr::DynamicStaticProperty { .. }
        | Expr::SelfStaticProperty { .. }
        | Expr::DynamicSelfStaticProperty { .. }
        | Expr::ParentStaticProperty { .. }
        | Expr::DynamicParentStaticProperty { .. }
        | Expr::LateStaticProperty { .. }
        | Expr::DynamicLateStaticProperty { .. }
        | Expr::Closure { .. } => false,
    }
}

fn new_class_name_contains_request_state_access(class_name: &NewClassName) -> bool {
    match class_name {
        NewClassName::DynamicVariable(name) => is_request_superglobal_name(name),
        NewClassName::DynamicExpression(expr) => expr_contains_request_state_access(expr),
        NewClassName::Named(_)
        | NewClassName::SelfClass
        | NewClassName::ParentClass
        | NewClassName::StaticClass => false,
    }
}

fn interpolated_string_part_contains_request_state_access(part: &InterpolatedStringPart) -> bool {
    match part {
        InterpolatedStringPart::Variable(name)
        | InterpolatedStringPart::DeprecatedDollarBraceVariable(name)
        | InterpolatedStringPart::ArrayOffset { variable: name, .. }
        | InterpolatedStringPart::ObjectProperty { variable: name, .. }
        | InterpolatedStringPart::AccessChain { variable: name, .. } => {
            is_request_superglobal_name(name)
        }
        InterpolatedStringPart::Literal(_) => false,
    }
}

fn assign_target_contains_request_state_access(target: &AssignTarget) -> bool {
    match target {
        AssignTarget::Variable { name, .. } => is_request_superglobal_name(name),
        AssignTarget::ArrayIndex { name, index, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && index.as_ref().is_some_and(|index| {
                        globals_indices_may_reference_request_superglobal(&[index])
                    }))
                || index
                    .as_ref()
                    .is_some_and(expr_contains_request_state_access)
        }
        AssignTarget::NestedArrayIndex { name, indices, .. }
        | AssignTarget::NestedArrayAppend { name, indices, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(
                        &indices.iter().collect::<Vec<_>>(),
                    ))
                || indices.iter().any(expr_contains_request_state_access)
        }
        AssignTarget::DynamicProperty { property, .. } => {
            expr_contains_request_state_access(property)
        }
        AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_request_state_access)
        }
        AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => indices
            .iter()
            .chain(suffix_indices.iter())
            .any(expr_contains_request_state_access),
        AssignTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_request_state_access(property)
                || indices.iter().any(expr_contains_request_state_access)
        }
        AssignTarget::DynamicObjectPropertyArrayAppend {
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_request_state_access(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_request_state_access)
        }
        AssignTarget::NonDirectProperty { holder, .. }
        | AssignTarget::ObjectStaticProperty { target: holder, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_request_state_access(holder)
        }
        AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_request_state_access(holder)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_request_state_access)
        }
        AssignTarget::NonDirectDynamicProperty {
            holder, property, ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => {
            expr_contains_request_state_access(holder)
                || expr_contains_request_state_access(property)
        }
        AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            suffix_indices,
            ..
        } => {
            expr_contains_request_state_access(holder)
                || expr_contains_request_state_access(property)
                || indices
                    .iter()
                    .chain(suffix_indices.iter())
                    .any(expr_contains_request_state_access)
        }
        AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => false,
    }
}

fn reference_source_contains_request_state_access(source: &ReferenceSource) -> bool {
    match source {
        ReferenceSource::Variable { name, .. } => is_request_superglobal_name(name),
        ReferenceSource::ArrayIndex { name, index, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(&[index]))
                || expr_contains_request_state_access(index)
        }
        ReferenceSource::ArrayAppend { name, indices, .. }
        | ReferenceSource::NestedArrayIndex { name, indices, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(
                        &indices.iter().collect::<Vec<_>>(),
                    ))
                || indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::ObjectPropertyArrayIndex { index, .. } => {
            expr_contains_request_state_access(index)
        }
        ReferenceSource::DynamicObjectPropertyArrayIndex {
            property, index, ..
        } => {
            expr_contains_request_state_access(property)
                || expr_contains_request_state_access(index)
        }
        ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::DynamicObjectPropertyArrayAppend {
            property, indices, ..
        }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex {
            property, indices, ..
        } => {
            expr_contains_request_state_access(property)
                || indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::NonDirectObjectPropertyArrayAppend {
            holder, indices, ..
        }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex {
            holder, indices, ..
        } => {
            expr_contains_request_state_access(holder)
                || indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend {
            holder,
            property,
            indices,
            ..
        }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex {
            holder,
            property,
            indices,
            ..
        } => {
            expr_contains_request_state_access(holder)
                || expr_contains_request_state_access(property)
                || indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::StaticPropertyArrayIndex { expr, indices, .. }
        | ReferenceSource::ExpressionArrayIndex {
            target: expr,
            indices,
            ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target: expr,
            indices,
            ..
        } => {
            expr_contains_request_state_access(expr)
                || indices.iter().any(expr_contains_request_state_access)
        }
        ReferenceSource::Property { expr, .. }
        | ReferenceSource::StaticProperty { expr, .. }
        | ReferenceSource::MethodCall { expr, .. } => expr_contains_request_state_access(expr),
    }
}

fn for_action_contains_request_state_access(action: &ForAction) -> bool {
    match action {
        ForAction::Assign { target, expr } | ForAction::CompoundAssign { target, expr, .. } => {
            assign_target_contains_request_state_access(target)
                || expr_contains_request_state_access(expr)
        }
        ForAction::IncrementDecrement { target, .. } => {
            assign_target_contains_request_state_access(target)
        }
        ForAction::Expr { expr } => expr_contains_request_state_access(expr),
    }
}

fn unset_target_contains_request_state_access(target: &UnsetTarget) -> bool {
    match target {
        UnsetTarget::Variable { name, .. } => is_request_superglobal_name(name),
        UnsetTarget::ArrayIndex { name, index, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(&[index]))
                || expr_contains_request_state_access(index)
        }
        UnsetTarget::NestedArrayIndex { name, indices, .. } => {
            is_request_superglobal_name(name)
                || (is_globals_superglobal_name(name)
                    && globals_indices_may_reference_request_superglobal(
                        &indices.iter().collect::<Vec<_>>(),
                    ))
                || indices.iter().any(expr_contains_request_state_access)
        }
        UnsetTarget::DynamicObjectProperty { property, .. } => {
            expr_contains_request_state_access(property)
        }
        UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
        | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
            indices.iter().any(expr_contains_request_state_access)
        }
        UnsetTarget::DynamicObjectPropertyArrayIndex {
            property, indices, ..
        } => {
            expr_contains_request_state_access(property)
                || indices.iter().any(expr_contains_request_state_access)
        }
        UnsetTarget::NonDirectObjectProperty { holder, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, .. } => {
            expr_contains_request_state_access(holder)
        }
        UnsetTarget::NonDirectDynamicObjectProperty {
            holder, property, ..
        }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder, property, ..
        } => {
            expr_contains_request_state_access(holder)
                || expr_contains_request_state_access(property)
        }
        UnsetTarget::ObjectStaticProperty { target, .. } => {
            expr_contains_request_state_access(target)
        }
        UnsetTarget::ObjectProperty { .. }
        | UnsetTarget::StaticProperty { .. }
        | UnsetTarget::SelfStaticProperty { .. }
        | UnsetTarget::ParentStaticProperty { .. }
        | UnsetTarget::LateStaticProperty { .. } => false,
    }
}

fn request_superglobal_root_name(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::Variable(name, _) if is_request_superglobal_name(name) => Some(name.as_str()),
        _ => None,
    }
}

fn request_superglobal_root_assign_target_name(target: &AssignTarget) -> Option<&str> {
    match target {
        AssignTarget::Variable { name, .. } if is_request_superglobal_name(name) => {
            Some(name.as_str())
        }
        _ => None,
    }
}

fn request_superglobal_root_reference_source_name(source: &ReferenceSource) -> Option<&str> {
    match source {
        ReferenceSource::Variable { name, .. } if is_request_superglobal_name(name) => {
            Some(name.as_str())
        }
        _ => None,
    }
}

fn request_superglobal_keyed_reference_target<'a>(
    target: &'a AssignTarget,
) -> Option<(&'a str, &'a Expr)> {
    match target {
        AssignTarget::ArrayIndex {
            name,
            index: Some(index),
            ..
        } if is_request_superglobal_name(name) => Some((name.as_str(), index)),
        _ => None,
    }
}

fn request_superglobal_keyed_reference_source<'a>(
    source: &'a ReferenceSource,
) -> Option<(&'a str, &'a Expr)> {
    match source {
        ReferenceSource::ArrayIndex { name, index, .. } if is_request_superglobal_name(name) => {
            Some((name.as_str(), index))
        }
        _ => None,
    }
}

fn request_superglobal_path_reference_target<'a>(
    target: &'a AssignTarget,
) -> Option<(&'a str, Vec<&'a Expr>)> {
    match target {
        AssignTarget::NestedArrayIndex { name, indices, .. }
            if is_request_superglobal_name(name) =>
        {
            Some((name.as_str(), indices.iter().collect()))
        }
        _ => None,
    }
}

fn request_superglobal_path_reference_source<'a>(
    source: &'a ReferenceSource,
) -> Option<(&'a str, Vec<&'a Expr>)> {
    match source {
        ReferenceSource::NestedArrayIndex { name, indices, .. }
            if is_request_superglobal_name(name) =>
        {
            Some((name.as_str(), indices.iter().collect()))
        }
        _ => None,
    }
}

fn request_superglobal_append_reference_target<'a>(
    target: &'a AssignTarget,
) -> Option<(&'a str, Vec<&'a Expr>)> {
    match target {
        AssignTarget::ArrayIndex {
            name, index: None, ..
        } if is_request_superglobal_name(name) => Some((name.as_str(), Vec::new())),
        AssignTarget::NestedArrayAppend {
            name,
            indices,
            suffix_indices,
            ..
        } if is_request_superglobal_name(name) && suffix_indices.is_empty() => {
            Some((name.as_str(), indices.iter().collect()))
        }
        _ => None,
    }
}

fn request_superglobal_append_reference_source<'a>(
    source: &'a ReferenceSource,
) -> Option<(&'a str, Vec<&'a Expr>)> {
    match source {
        ReferenceSource::ArrayAppend { name, indices, .. } if is_request_superglobal_name(name) => {
            Some((name.as_str(), indices.iter().collect()))
        }
        _ => None,
    }
}

fn request_superglobal_expr_span(expr: &Expr) -> Option<Span> {
    match expr {
        Expr::Variable(name, span) if is_request_superglobal_name(name) => Some(*span),
        Expr::Index { target, .. } | Expr::AppendIndex { target, .. } => {
            request_superglobal_expr_span(target)
        }
        _ => None,
    }
}

#[derive(Debug, Clone)]
struct RequestArrayKeyConsumerAccess {
    span: Span,
    label: String,
}

fn php_string_key_label(value: &str) -> String {
    let escaped = value.replace('\\', "\\\\").replace('"', "\\\"");
    format!("\"{escaped}\"")
}

fn request_index_label(index: &Expr) -> String {
    match index {
        Expr::String(value, _) => php_string_key_label(value),
        Expr::Int(value, _) => value.to_string(),
        Expr::Float(value, _) => format_float_literal(*value),
        Expr::Bool(value, _) => {
            if *value {
                "true".to_string()
            } else {
                "false".to_string()
            }
        }
        Expr::Null(_) => "null".to_string(),
        _ => "<dynamic>".to_string(),
    }
}

fn request_superglobal_expr_label(expr: &Expr) -> Option<String> {
    match expr {
        Expr::Variable(name, _) if is_request_superglobal_name(name) => Some(format!("${name}")),
        Expr::Index { target, index, .. } => {
            let target = request_superglobal_expr_label(target)?;
            Some(format!("{target}[{}]", request_index_label(index)))
        }
        Expr::AppendIndex { target, .. } => {
            let target = request_superglobal_expr_label(target)?;
            Some(format!("{target}[]"))
        }
        _ => None,
    }
}

fn request_array_key_consumer_access<'a>(
    indices: impl IntoIterator<Item = &'a Expr>,
) -> Option<RequestArrayKeyConsumerAccess> {
    indices.into_iter().find_map(|index| {
        request_superglobal_expr_label(index).map(|label| RequestArrayKeyConsumerAccess {
            span: index.span(),
            label,
        })
    })
}

fn request_assign_target_array_key_consumer_access(
    target: &AssignTarget,
) -> Option<RequestArrayKeyConsumerAccess> {
    match target {
        AssignTarget::ArrayIndex { index, .. } => index
            .as_ref()
            .and_then(|index| request_array_key_consumer_access(std::iter::once(index))),
        AssignTarget::NestedArrayIndex { indices, .. }
        | AssignTarget::ObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::DynamicObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::NonDirectObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex { indices, .. }
        | AssignTarget::StaticPropertyArrayIndex { indices, .. } => {
            request_array_key_consumer_access(indices)
        }
        AssignTarget::NestedArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::ObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::DynamicObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::NonDirectObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        }
        | AssignTarget::StaticPropertyArrayAppend {
            indices,
            suffix_indices,
            ..
        } => request_array_key_consumer_access(indices.iter().chain(suffix_indices.iter())),
        AssignTarget::Variable { .. }
        | AssignTarget::List { .. }
        | AssignTarget::Property { .. }
        | AssignTarget::NonDirectProperty { .. }
        | AssignTarget::NonDirectDynamicProperty { .. }
        | AssignTarget::ObjectStaticProperty { .. }
        | AssignTarget::DynamicObjectStaticProperty { .. }
        | AssignTarget::DynamicProperty { .. }
        | AssignTarget::StaticProperty { .. }
        | AssignTarget::DynamicStaticProperty { .. }
        | AssignTarget::SelfStaticProperty { .. }
        | AssignTarget::DynamicSelfStaticProperty { .. }
        | AssignTarget::ParentStaticProperty { .. }
        | AssignTarget::DynamicParentStaticProperty { .. }
        | AssignTarget::LateStaticProperty { .. }
        | AssignTarget::DynamicLateStaticProperty { .. }
        | AssignTarget::UnsupportedExpression { .. } => None,
    }
}

fn request_reference_source_array_key_consumer_access(
    source: &ReferenceSource,
) -> Option<RequestArrayKeyConsumerAccess> {
    match source {
        ReferenceSource::ArrayIndex { index, .. }
        | ReferenceSource::ObjectPropertyArrayIndex { index, .. }
        | ReferenceSource::DynamicObjectPropertyArrayIndex { index, .. } => {
            request_array_key_consumer_access(std::iter::once(index))
        }
        ReferenceSource::ArrayAppend { indices, .. }
        | ReferenceSource::NestedArrayIndex { indices, .. }
        | ReferenceSource::ObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::DynamicObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::ObjectPropertyNestedArrayIndex { indices, .. }
        | ReferenceSource::DynamicObjectPropertyNestedArrayIndex { indices, .. }
        | ReferenceSource::StaticPropertyArrayIndex { indices, .. }
        | ReferenceSource::NonDirectDynamicObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::NonDirectDynamicObjectPropertyNestedArrayIndex { indices, .. }
        | ReferenceSource::NonDirectObjectPropertyArrayAppend { indices, .. }
        | ReferenceSource::NonDirectObjectPropertyNestedArrayIndex { indices, .. } => {
            request_array_key_consumer_access(indices)
        }
        ReferenceSource::ExpressionArrayIndex {
            target, indices, ..
        }
        | ReferenceSource::ExpressionArrayAppend {
            target, indices, ..
        } => request_superglobal_expr_label(target)
            .map(|label| RequestArrayKeyConsumerAccess {
                span: target.span(),
                label,
            })
            .or_else(|| request_array_key_consumer_access(indices)),
        ReferenceSource::Property { .. }
        | ReferenceSource::StaticProperty { .. }
        | ReferenceSource::MethodCall { .. }
        | ReferenceSource::Variable { .. } => None,
    }
}

fn request_for_action_array_key_consumer_access(
    action: &ForAction,
) -> Option<RequestArrayKeyConsumerAccess> {
    match action {
        ForAction::Assign { target, .. } | ForAction::CompoundAssign { target, .. } => {
            request_assign_target_array_key_consumer_access(target)
        }
        ForAction::IncrementDecrement { target, .. } => {
            request_assign_target_array_key_consumer_access(target)
        }
        ForAction::Expr { expr } => request_array_key_consumer_access(std::iter::once(expr)),
    }
}

fn request_stmt_array_key_consumer_access(stmt: &Stmt) -> Option<RequestArrayKeyConsumerAccess> {
    match stmt {
        Stmt::Assign { target, .. }
        | Stmt::CompoundAssign { target, .. }
        | Stmt::NullCoalesceAssign { target, .. } => {
            request_assign_target_array_key_consumer_access(target)
        }
        Stmt::ReferenceAssign { target, source, .. } => {
            request_assign_target_array_key_consumer_access(target)
                .or_else(|| request_reference_source_array_key_consumer_access(source))
        }
        Stmt::IncrementDecrement { target, .. } => {
            request_assign_target_array_key_consumer_access(target)
        }
        Stmt::UnsetArrayIndex { index, .. } => {
            request_array_key_consumer_access(std::iter::once(index))
        }
        Stmt::UnsetNestedArrayIndex { indices, .. } => request_array_key_consumer_access(indices),
        Stmt::UnsetMany { targets, .. } => targets.iter().find_map(|target| match target {
            UnsetTarget::ArrayIndex { index, .. } => {
                request_array_key_consumer_access(std::iter::once(index))
            }
            UnsetTarget::NestedArrayIndex { indices, .. }
            | UnsetTarget::ObjectPropertyArrayIndex { indices, .. }
            | UnsetTarget::DynamicObjectPropertyArrayIndex { indices, .. }
            | UnsetTarget::NonDirectObjectPropertyArrayIndex { indices, .. }
            | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex { indices, .. }
            | UnsetTarget::StaticPropertyArrayIndex { indices, .. } => {
                request_array_key_consumer_access(indices)
            }
            UnsetTarget::Variable { .. }
            | UnsetTarget::ObjectProperty { .. }
            | UnsetTarget::DynamicObjectProperty { .. }
            | UnsetTarget::NonDirectObjectProperty { .. }
            | UnsetTarget::NonDirectDynamicObjectProperty { .. }
            | UnsetTarget::ObjectStaticProperty { .. }
            | UnsetTarget::StaticProperty { .. }
            | UnsetTarget::SelfStaticProperty { .. }
            | UnsetTarget::ParentStaticProperty { .. }
            | UnsetTarget::LateStaticProperty { .. } => None,
        }),
        Stmt::For {
            initializers,
            increments,
            ..
        } => initializers
            .iter()
            .chain(increments.iter())
            .find_map(request_for_action_array_key_consumer_access),
        _ => None,
    }
}

fn request_superglobal_consumed_args_span(args: &[Expr]) -> Option<Span> {
    args.iter().find_map(request_superglobal_expr_span)
}

