#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeObjectArrayAccessReceiverKind {
    ErrorControlReceiver,
    PropertyValue,
    CallResult,
    DynamicCallResult,
    InstanceMethodCallResult,
    StaticMethodCallResult,
    NewObjectResult,
    CloneResult,
    StaticPropertyValue,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct NativeObjectArrayAccessOperationResult {
    operation: NativeObjectArrayAccessOperation,
    receiver_kind: NativeObjectArrayAccessReceiverKind,
    span: Span,
}

impl NativeObjectArrayAccessOperation {
    #[cfg(test)]
    fn result_kind(self) -> NativeObjectPropertyOperationResultKind {
        match self {
            Self::Read => NativeObjectPropertyOperationResultKind::Value,
            Self::NullCoalesceRead => NativeObjectPropertyOperationResultKind::Value,
            Self::Write | Self::AppendWrite | Self::CompoundUpdate | Self::NullCoalesceWrite => {
                NativeObjectPropertyOperationResultKind::Value
            }
            Self::Isset | Self::Empty => NativeObjectPropertyOperationResultKind::Bool,
            Self::Unset => NativeObjectPropertyOperationResultKind::Bool,
        }
    }
}

impl NativeObjectArrayAccessReceiverKind {
    fn from_object_offset_receiver(expr: &Expr) -> Option<(Self, Span)> {
        match expr {
            Expr::ErrorControl { expr, span } => Self::from_object_offset_receiver(expr.as_ref())
                .map(|_| (Self::ErrorControlReceiver, *span)),
            Expr::Property { span, .. } | Expr::DynamicProperty { span, .. } => {
                Some((Self::PropertyValue, *span))
            }
            Expr::Call { span, .. } => Some((Self::CallResult, *span)),
            Expr::DynamicCall { span, .. } => Some((Self::DynamicCallResult, *span)),
            Expr::MethodCall { span, .. } | Expr::DynamicMethodCall { span, .. } => {
                Some((Self::InstanceMethodCallResult, *span))
            }
            Expr::ParentMethodCall { span, .. }
            | Expr::StaticMethodCall { span, .. }
            | Expr::ObjectStaticMethodCall { span, .. }
            | Expr::SelfMethodCall { span, .. }
            | Expr::LateStaticMethodCall { span, .. } => {
                Some((Self::StaticMethodCallResult, *span))
            }
            Expr::New { span, .. } => Some((Self::NewObjectResult, *span)),
            Expr::Clone { span, .. } => Some((Self::CloneResult, *span)),
            Expr::ObjectStaticProperty { span, .. }
            | Expr::StaticProperty { span, .. }
            | Expr::SelfStaticProperty { span, .. }
            | Expr::ParentStaticProperty { span, .. }
            | Expr::LateStaticProperty { span, .. } => Some((Self::StaticPropertyValue, *span)),
            _ => None,
        }
    }
}

impl NativeObjectArrayAccessOperationResult {
    fn error_control_receiver(operation: NativeObjectArrayAccessOperation, span: Span) -> Self {
        Self {
            operation,
            receiver_kind: NativeObjectArrayAccessReceiverKind::ErrorControlReceiver,
            span,
        }
    }

    fn from_expr_at(expr: &Expr, operation: NativeObjectArrayAccessOperation) -> Option<Self> {
        if let Some(result) =
            native_object_array_access_error_control_operation_result_from_expr(expr, operation)
        {
            return Some(result);
        }

        Self::from_expr_without_error_control(expr, operation)
    }

    fn from_expr_without_error_control(
        expr: &Expr,
        operation: NativeObjectArrayAccessOperation,
    ) -> Option<Self> {
        let target = match expr {
            Expr::Index { target, .. } | Expr::AppendIndex { target, .. } => target.as_ref(),
            _ => return None,
        };
        let (receiver_kind, span) =
            NativeObjectArrayAccessReceiverKind::from_object_offset_receiver(target)?;
        Some(Self {
            operation,
            receiver_kind,
            span,
        })
    }

    #[cfg(test)]
    fn result_kind(self) -> NativeObjectPropertyOperationResultKind {
        self.operation.result_kind()
    }

    fn llvm_rejection(self) -> &'static str {
        self.rejection(NativeCallBackend::Llvm)
    }

    fn assembly_rejection(self) -> &'static str {
        self.rejection(NativeCallBackend::Assembly)
    }

    fn rejection(self, backend: NativeCallBackend) -> &'static str {
        match (backend, self.receiver_kind) {
            (_, NativeObjectArrayAccessReceiverKind::ErrorControlReceiver) => match backend {
                NativeCallBackend::Llvm => LLVM_ERROR_CONTROL_REJECTION,
                NativeCallBackend::Assembly => ASSEMBLY_ERROR_CONTROL_REJECTION,
            },
            (_, NativeObjectArrayAccessReceiverKind::CallResult) => {
                backend.function_call_rejection()
            }
            (_, NativeObjectArrayAccessReceiverKind::DynamicCallResult) => {
                backend.dynamic_function_call_rejection()
            }
            (_, NativeObjectArrayAccessReceiverKind::InstanceMethodCallResult)
            | (_, NativeObjectArrayAccessReceiverKind::StaticMethodCallResult) => {
                backend.method_call_rejection()
            }
            (_, NativeObjectArrayAccessReceiverKind::NewObjectResult) => {
                backend.object_instantiation_rejection()
            }
            (NativeCallBackend::Llvm, NativeObjectArrayAccessReceiverKind::CloneResult) => {
                LLVM_CLONE_REJECTION
            }
            (NativeCallBackend::Assembly, NativeObjectArrayAccessReceiverKind::CloneResult) => {
                ASSEMBLY_CLONE_REJECTION
            }
            (NativeCallBackend::Llvm, NativeObjectArrayAccessReceiverKind::StaticPropertyValue) => {
                LLVM_STATIC_MEMBER_REJECTION
            }
            (
                NativeCallBackend::Assembly,
                NativeObjectArrayAccessReceiverKind::StaticPropertyValue,
            ) => ASSEMBLY_STATIC_MEMBER_REJECTION,
            (NativeCallBackend::Llvm, NativeObjectArrayAccessReceiverKind::PropertyValue) => {
                LLVM_ARRAY_ACCESS_REJECTION
            }
            (NativeCallBackend::Assembly, NativeObjectArrayAccessReceiverKind::PropertyValue) => {
                ASSEMBLY_ARRAY_ACCESS_REJECTION
            }
        }
    }
}

fn native_object_array_access_error_control_operation_result_from_expr(
    expr: &Expr,
    operation: NativeObjectArrayAccessOperation,
) -> Option<NativeObjectArrayAccessOperationResult> {
    let Expr::ErrorControl { expr, span } = expr else {
        return None;
    };
    NativeObjectArrayAccessOperationResult::from_expr_without_error_control(
        expr.as_ref(),
        operation,
    )
    .is_some()
    .then(|| NativeObjectArrayAccessOperationResult::error_control_receiver(operation, *span))
}

fn native_object_array_access_operation_result_from_expr(
    expr: &Expr,
    operation: NativeObjectArrayAccessOperation,
) -> Option<NativeObjectArrayAccessOperationResult> {
    NativeObjectArrayAccessOperationResult::from_expr_at(expr, operation)
}

fn native_object_array_access_receiver_from_property_holder(
    holder: &Expr,
    fallback_span: Span,
) -> (NativeObjectArrayAccessReceiverKind, Span) {
    NativeObjectArrayAccessReceiverKind::from_object_offset_receiver(holder).unwrap_or((
        NativeObjectArrayAccessReceiverKind::PropertyValue,
        fallback_span,
    ))
}

fn native_object_array_access_operation_result_from_assign_target(
    target: &AssignTarget,
    operation: NativeObjectArrayAccessOperation,
) -> Option<NativeObjectArrayAccessOperationResult> {
    let (receiver_kind, span) = match target {
        AssignTarget::ObjectPropertyArrayIndex { span, .. }
        | AssignTarget::DynamicObjectPropertyArrayIndex { span, .. }
        | AssignTarget::ObjectPropertyArrayAppend { span, .. }
        | AssignTarget::DynamicObjectPropertyArrayAppend { span, .. } => {
            (NativeObjectArrayAccessReceiverKind::PropertyValue, *span)
        }
        AssignTarget::NonDirectObjectPropertyArrayIndex { holder, span, .. }
        | AssignTarget::NonDirectObjectPropertyArrayAppend { holder, span, .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayIndex { holder, span, .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { holder, span, .. } => {
            native_object_array_access_receiver_from_property_holder(holder, *span)
        }
        _ => return None,
    };

    Some(NativeObjectArrayAccessOperationResult {
        operation,
        receiver_kind,
        span,
    })
}

fn native_object_array_access_assignment_operation_result(
    target: &AssignTarget,
) -> Option<NativeObjectArrayAccessOperationResult> {
    let operation = match target {
        AssignTarget::ObjectPropertyArrayAppend { .. }
        | AssignTarget::DynamicObjectPropertyArrayAppend { .. }
        | AssignTarget::NonDirectObjectPropertyArrayAppend { .. }
        | AssignTarget::NonDirectDynamicObjectPropertyArrayAppend { .. } => {
            NativeObjectArrayAccessOperation::AppendWrite
        }
        _ => NativeObjectArrayAccessOperation::Write,
    };
    native_object_array_access_operation_result_from_assign_target(target, operation)
}

fn native_object_array_access_compound_operation_result(
    target: &AssignTarget,
) -> Option<NativeObjectArrayAccessOperationResult> {
    native_object_array_access_operation_result_from_assign_target(
        target,
        NativeObjectArrayAccessOperation::CompoundUpdate,
    )
}

fn native_object_array_access_null_coalesce_write_operation_result(
    target: &AssignTarget,
) -> Option<NativeObjectArrayAccessOperationResult> {
    native_object_array_access_operation_result_from_assign_target(
        target,
        NativeObjectArrayAccessOperation::NullCoalesceWrite,
    )
}

fn native_object_array_access_unset_operation_result_from_target(
    target: &UnsetTarget,
) -> Option<NativeObjectArrayAccessOperationResult> {
    let (receiver_kind, span) = match target {
        UnsetTarget::ObjectPropertyArrayIndex { span, .. }
        | UnsetTarget::DynamicObjectPropertyArrayIndex { span, .. } => {
            (NativeObjectArrayAccessReceiverKind::PropertyValue, *span)
        }
        UnsetTarget::NonDirectObjectPropertyArrayIndex { holder, span, .. }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex { holder, span, .. } => {
            native_object_array_access_receiver_from_property_holder(holder, *span)
        }
        _ => return None,
    };

    Some(NativeObjectArrayAccessOperationResult {
        operation: NativeObjectArrayAccessOperation::Unset,
        receiver_kind,
        span,
    })
}

fn native_object_array_access_unset_operation_result_from_stmt(
    stmt: &Stmt,
) -> Option<NativeObjectArrayAccessOperationResult> {
    let Stmt::UnsetMany { targets, .. } = stmt else {
        return None;
    };
    targets
        .iter()
        .find_map(native_object_array_access_unset_operation_result_from_target)
}

fn is_object_public_property_assign_target(target: &AssignTarget) -> bool {
    matches!(
        target,
        AssignTarget::Property { .. }
            | AssignTarget::DynamicProperty { .. }
            | AssignTarget::NonDirectProperty { .. }
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeNonLocalOwnerOperation {
    Assignment,
    Unset,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct NativeNonLocalOwnerBoundary {
    operation: NativeNonLocalOwnerOperation,
    span: Span,
}

impl NativeNonLocalOwnerBoundary {
    fn assignment(span: Span) -> Self {
        Self {
            operation: NativeNonLocalOwnerOperation::Assignment,
            span,
        }
    }

    fn unset(span: Span) -> Self {
        Self {
            operation: NativeNonLocalOwnerOperation::Unset,
            span,
        }
    }

    fn rejection(self, backend: NativeCallBackend) -> &'static str {
        match self.operation {
            NativeNonLocalOwnerOperation::Assignment => backend.non_local_assignment_rejection(),
            NativeNonLocalOwnerOperation::Unset => backend.non_local_unset_rejection(),
        }
    }
}

fn native_non_local_assignment_owner_boundary(
    target: &AssignTarget,
) -> Option<NativeNonLocalOwnerBoundary> {
    matches!(
        target,
        AssignTarget::Property { .. }
            | AssignTarget::DynamicProperty { .. }
            | AssignTarget::NonDirectProperty { .. }
            | AssignTarget::NonDirectDynamicProperty { .. }
            | AssignTarget::StaticProperty { .. }
            | AssignTarget::DynamicStaticProperty { .. }
            | AssignTarget::ObjectStaticProperty { .. }
            | AssignTarget::DynamicObjectStaticProperty { .. }
            | AssignTarget::SelfStaticProperty { .. }
            | AssignTarget::DynamicSelfStaticProperty { .. }
            | AssignTarget::ParentStaticProperty { .. }
            | AssignTarget::DynamicParentStaticProperty { .. }
            | AssignTarget::LateStaticProperty { .. }
            | AssignTarget::DynamicLateStaticProperty { .. }
    )
    .then(|| NativeNonLocalOwnerBoundary::assignment(target.span()))
}

fn unset_target_span(target: &UnsetTarget) -> Span {
    match target {
        UnsetTarget::Variable { span, .. }
        | UnsetTarget::ArrayIndex { span, .. }
        | UnsetTarget::NestedArrayIndex { span, .. }
        | UnsetTarget::ObjectPropertyArrayIndex { span, .. }
        | UnsetTarget::DynamicObjectPropertyArrayIndex { span, .. }
        | UnsetTarget::NonDirectObjectPropertyArrayIndex { span, .. }
        | UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex { span, .. }
        | UnsetTarget::ObjectProperty { span, .. }
        | UnsetTarget::DynamicObjectProperty { span, .. }
        | UnsetTarget::NonDirectObjectProperty { span, .. }
        | UnsetTarget::NonDirectDynamicObjectProperty { span, .. }
        | UnsetTarget::ObjectStaticProperty { span, .. }
        | UnsetTarget::StaticPropertyArrayIndex { span, .. }
        | UnsetTarget::StaticProperty { span, .. }
        | UnsetTarget::SelfStaticProperty { span, .. }
        | UnsetTarget::ParentStaticProperty { span, .. }
        | UnsetTarget::LateStaticProperty { span, .. } => *span,
    }
}

fn native_non_local_unset_target_owner_boundary(
    target: &UnsetTarget,
) -> Option<NativeNonLocalOwnerBoundary> {
    matches!(
        target,
        UnsetTarget::ObjectProperty { .. }
            | UnsetTarget::DynamicObjectProperty { .. }
            | UnsetTarget::NonDirectObjectProperty { .. }
            | UnsetTarget::NonDirectDynamicObjectProperty { .. }
            | UnsetTarget::ObjectStaticProperty { .. }
            | UnsetTarget::StaticProperty { .. }
            | UnsetTarget::SelfStaticProperty { .. }
            | UnsetTarget::ParentStaticProperty { .. }
            | UnsetTarget::LateStaticProperty { .. }
    )
    .then(|| NativeNonLocalOwnerBoundary::unset(unset_target_span(target)))
}

fn native_non_local_unset_statement_owner_boundary(
    stmt: &Stmt,
) -> Option<NativeNonLocalOwnerBoundary> {
    match stmt {
        Stmt::UnsetObjectProperty { span, .. }
        | Stmt::UnsetDynamicObjectProperty { span, .. }
        | Stmt::UnsetStaticProperty { span, .. }
        | Stmt::UnsetSelfStaticProperty { span, .. }
        | Stmt::UnsetParentStaticProperty { span, .. }
        | Stmt::UnsetLateStaticProperty { span, .. } => {
            Some(NativeNonLocalOwnerBoundary::unset(*span))
        }
        Stmt::UnsetMany { targets, .. } => targets
            .iter()
            .find_map(native_non_local_unset_target_owner_boundary),
        _ => None,
    }
}

fn is_object_offset_expr(expr: &Expr) -> bool {
    matches!(
        expr,
        Expr::Property { .. }
            | Expr::DynamicProperty { .. }
            | Expr::MethodCall { .. }
            | Expr::DynamicMethodCall { .. }
            | Expr::New { .. }
            | Expr::Clone { .. }
            | Expr::ObjectStaticProperty { .. }
            | Expr::DynamicObjectStaticProperty { .. }
            | Expr::StaticProperty { .. }
            | Expr::DynamicStaticProperty { .. }
            | Expr::SelfStaticProperty { .. }
            | Expr::DynamicSelfStaticProperty { .. }
            | Expr::ParentStaticProperty { .. }
            | Expr::DynamicParentStaticProperty { .. }
            | Expr::LateStaticProperty { .. }
            | Expr::DynamicLateStaticProperty { .. }
    )
}

fn find_static_local_span(statements: &[Stmt]) -> Option<Span> {
    for statement in statements {
        match statement {
            Stmt::StaticLocal { span, .. } => return Some(*span),
            Stmt::If {
                then_branch,
                else_branch,
                ..
            } => {
                if let Some(span) = find_static_local_span(then_branch) {
                    return Some(span);
                }
                if let Some(span) = find_static_local_span(else_branch) {
                    return Some(span);
                }
            }
            Stmt::While { body, .. }
            | Stmt::DoWhile { body, .. }
            | Stmt::For { body, .. }
            | Stmt::Foreach { body, .. } => {
                if let Some(span) = find_static_local_span(body) {
                    return Some(span);
                }
            }
            Stmt::Switch { cases, .. } => {
                for case in cases {
                    if let Some(span) = find_static_local_span(&case.body) {
                        return Some(span);
                    }
                }
            }
            Stmt::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                if let Some(span) = find_static_local_span(body) {
                    return Some(span);
                }
                for catch in catches {
                    if let Some(span) = find_static_local_span(&catch.body) {
                        return Some(span);
                    }
                }
                if let Some(finally_body) = finally_body {
                    if let Some(span) = find_static_local_span(finally_body) {
                        return Some(span);
                    }
                }
            }
            Stmt::Function(function) => {
                if let Some(span) = find_static_local_span(&function.body) {
                    return Some(span);
                }
            }
            Stmt::Class(class) => {
                for member in &class.members {
                    if let ClassMember::Method(method) = member {
                        if let Some(span) = find_static_local_span(&method.function.body) {
                            return Some(span);
                        }
                    }
                }
            }
            _ => {}
        }
    }
    None
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NativeRuntimeIrTarget {
    Pointer32,
    Pointer64,
}

impl NativeRuntimeIrTarget {
    fn host() -> Self {
        if usize::BITS == 32 {
            Self::Pointer32
        } else {
            Self::Pointer64
        }
    }

    fn usize_ir_type(self) -> &'static str {
        match self {
            Self::Pointer32 => "i32",
            Self::Pointer64 => "i64",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeDiagnosticRequestKeyOperationConsumer {
    KeyedOperation,
    PathOperation,
    BagMutation,
    KeyedMutation,
    PathMutation,
}

impl NativeDiagnosticRequestKeyOperationConsumer {
    fn abi_name(self) -> &'static str {
        match self {
            Self::KeyedOperation => "phpc_native_request_state_superglobal_operation",
            Self::PathOperation => "phpc_native_request_state_superglobal_path_operation",
            Self::BagMutation => "phpc_native_request_state_superglobal_bag_mutation_operation",
            Self::KeyedMutation => "phpc_native_request_state_superglobal_keyed_mutation_operation",
            Self::PathMutation => "phpc_native_request_state_superglobal_path_mutation_operation",
        }
    }

    fn llvm_callee(self) -> String {
        format!("@{}", self.abi_name())
    }
}

pub fn native_runtime_scalar_echo_probe_ir() -> String {
    native_runtime_scalar_echo_probe_ir_for_target(NativeRuntimeIrTarget::host())
}

