#[derive(Clone, Copy)]
enum CStaticPropertyNameOperand<'a> {
    Literal(&'a str),
    Dynamic(&'a Expr),
}

impl<'a> CStaticPropertyNameOperand<'a> {
    fn literal(self) -> Option<&'a str> {
        match self {
            Self::Literal(name) => Some(name),
            Self::Dynamic(_) => None,
        }
    }

    fn is_dynamic(self) -> bool {
        matches!(self, Self::Dynamic(_))
    }
}

