#[derive(Debug, Clone, PartialEq, Eq)]
struct CNativeObjectFacts {
    declared_class_keys: HashSet<String>,
    implemented_interface_keys: HashSet<String>,
}

impl CNativeValueFacts {
    fn is_empty(&self) -> bool {
        self.object
            .as_ref()
            .map_or(true, CNativeObjectFacts::is_empty)
    }

    fn object(object: CNativeObjectFacts) -> Option<Self> {
        if object.is_empty() {
            None
        } else {
            Some(Self {
                object: Some(object),
            })
        }
    }

    fn intersection(&self, other: &Self) -> Option<Self> {
        match (&self.object, &other.object) {
            (Some(left), Some(right)) => Self::object(left.intersection(right)),
            _ => None,
        }
    }

    fn has_definite_native_object_interface(&self, interface_name: &str) -> bool {
        self.object
            .as_ref()
            .is_some_and(|object| object.has_definite_interface(interface_name))
    }
}

impl CNativeObjectFacts {
    fn is_empty(&self) -> bool {
        self.declared_class_keys.is_empty() && self.implemented_interface_keys.is_empty()
    }

    fn for_declared_class(class_key: String, class: &CDeclaredClass) -> Self {
        Self {
            declared_class_keys: HashSet::from([class_key]),
            implemented_interface_keys: class
                .interface_names
                .iter()
                .map(|interface| interface.to_ascii_lowercase())
                .collect(),
        }
    }

    fn intersection(&self, other: &Self) -> Self {
        Self {
            declared_class_keys: self
                .declared_class_keys
                .intersection(&other.declared_class_keys)
                .cloned()
                .collect(),
            implemented_interface_keys: self
                .implemented_interface_keys
                .intersection(&other.implemented_interface_keys)
                .cloned()
                .collect(),
        }
    }

    fn has_definite_interface(&self, interface_name: &str) -> bool {
        self.implemented_interface_keys
            .contains(&interface_name.to_ascii_lowercase())
    }
}

impl CNativeDescriptorClosureSummary {
    fn for_function(function: &FunctionDecl, return_summary: CNativeCallableReturnSummary) -> Self {
        Self {
            params: function.params.clone(),
            required_arg_count: native_user_function_required_arg_count(function),
            param_count: function.params.len(),
            is_variadic: native_user_function_variadic_param(function).is_some(),
            return_summary,
        }
    }

    fn accepts_arg_count(&self, arg_count: usize) -> bool {
        if arg_count < self.required_arg_count {
            return false;
        }
        self.is_variadic || arg_count <= self.param_count
    }

    fn source_call_argument_plan(&self) -> NativeMethodStaticSourceCallArgumentPlan {
        NativeMethodStaticSourceCallArgumentPlan {
            params: self.params.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CDeclaredClassAllocationMetadata {
    cleanup_risk: CDeclaredClassCleanupRisk,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CDeclaredClassCleanupRisk {
    destructor_observable: bool,
}

impl CDeclaredClassAllocationMetadata {
    fn cleanup_safe() -> Self {
        Self {
            cleanup_risk: CDeclaredClassCleanupRisk::none(),
        }
    }

    fn requires_destructor_observable_cleanup_boundary(&self) -> bool {
        self.cleanup_risk
            .requires_destructor_observable_cleanup_boundary()
    }
}

impl CDeclaredClassCleanupRisk {
    fn none() -> Self {
        Self {
            destructor_observable: false,
        }
    }

    fn destructor_observable() -> Self {
        Self {
            destructor_observable: true,
        }
    }

    fn include(&mut self, other: Self) {
        self.destructor_observable |= other.destructor_observable;
    }

    fn requires_destructor_observable_cleanup_boundary(self) -> bool {
        self.destructor_observable
    }
}

