    fn globals_symbol_table_is_active(&self) -> bool {
        self.native_globals_symbol_table_handle.is_some()
    }

    fn direct_variables_route_through_global_symbol_table(&self) -> bool {
        (self.function_return_status.is_none()
            || self.function_return_mode == CFunctionReturnMode::IncludeUnit
            || self.route_direct_variables_through_symbol_table)
            && self.globals_symbol_table_is_active()
    }

    fn variable_array_path_routes_through_global_symbol_table(&self, name: &str) -> bool {
        self.direct_variables_route_through_global_symbol_table()
            || self.global_import_names.contains(name)
    }

    fn native_value_facts_for_declared_class_key(
        &self,
        class_key: &str,
    ) -> Option<CNativeValueFacts> {
        let class = self.declared_classes.get(class_key)?;
        CNativeValueFacts::object(CNativeObjectFacts::for_declared_class(
            class_key.to_string(),
            class,
        ))
    }

    fn native_value_facts_for_dynamic_declared_class_variable(
        &self,
        variable: &str,
    ) -> Option<CNativeValueFacts> {
        let values = self
            .variables
            .get(variable)
            .and_then(|value| self.known_string_values_for_value(value))?;
        let mut facts: Option<CNativeValueFacts> = None;
        for class_name in values.values() {
            let class_key = Self::declared_class_key(class_name);
            let class_facts = self.native_value_facts_for_declared_class_key(&class_key)?;
            facts = Some(match facts {
                Some(previous) => previous.intersection(&class_facts)?,
                None => class_facts,
            });
        }
        facts
    }

    fn native_value_facts_for_new_class_name(
        &self,
        class_name: &NewClassName,
    ) -> Option<CNativeValueFacts> {
        match class_name {
            NewClassName::Named(name) => {
                let key = Self::declared_class_key(name);
                self.native_value_facts_for_declared_class_key(&key)
            }
            NewClassName::DynamicVariable(variable) => {
                self.native_value_facts_for_dynamic_declared_class_variable(variable)
            }
            NewClassName::DynamicExpression(expr) => {
                let mut facts: Option<CNativeValueFacts> = None;
                for class_key in self.dynamic_declared_class_known_keys_for_expr(expr)? {
                    let class_facts = self.native_value_facts_for_declared_class_key(&class_key)?;
                    facts = Some(match facts {
                        Some(previous) => previous.intersection(&class_facts)?,
                        None => class_facts,
                    });
                }
                facts
            }
            NewClassName::SelfClass | NewClassName::ParentClass | NewClassName::StaticClass => None,
        }
    }

    fn constructor_this_property_value_facts_for_new_class_name(
        &self,
        class_name: &NewClassName,
    ) -> Option<HashMap<String, CNativeValueFacts>> {
        let NewClassName::Named(name) = class_name else {
            return None;
        };
        let key = Self::declared_class_key(name);
        let class = self.declared_classes.get(&key)?;
        let (_, constructor) = self.declared_class_constructor_for_instantiation(class)?;
        (!constructor.this_property_value_facts.is_empty())
            .then_some(constructor.this_property_value_facts.clone())
    }

    fn intersect_native_value_fact_iter<I>(&self, facts: I) -> Option<CNativeValueFacts>
    where
        I: IntoIterator<Item = Option<CNativeValueFacts>>,
    {
        let mut merged: Option<CNativeValueFacts> = None;
        let mut saw_fact = false;
        for facts in facts {
            let facts = facts?;
            saw_fact = true;
            merged = Some(match merged {
                Some(previous) => previous.intersection(&facts)?,
                None => facts,
            });
        }
        saw_fact.then_some(merged).flatten()
    }

    fn native_callable_return_summary_for_identity(
        &self,
        identity: &CNativeCallableIdentity,
        arg_count: usize,
    ) -> Option<CNativeCallableReturnSummary> {
        match identity {
            CNativeCallableIdentity::GeneratedFunction { function_key } => {
                let function = self.user_functions.get(function_key)?;
                if !native_user_function_accepts_arg_count(&function.decl, arg_count) {
                    return None;
                }
                let result_kind = if function.decl.returns_by_reference {
                    CNativeCallableResultKind::Reference
                } else {
                    CNativeCallableResultKind::NativeValue
                };
                Some(CNativeCallableReturnSummary {
                    result_kind,
                    facts: function.return_facts.clone(),
                })
            }
            CNativeCallableIdentity::DeclaredInstanceMethod {
                class_key,
                method_key,
            } => self.native_callable_return_summary_for_declared_method_identity(
                class_key,
                method_key,
                CNativeCallableDeclaredMethodStaticness::Instance,
                arg_count,
            ),
            CNativeCallableIdentity::DeclaredStaticMethod {
                class_key,
                method_key,
            } => self.native_callable_return_summary_for_declared_method_identity(
                class_key,
                method_key,
                CNativeCallableDeclaredMethodStaticness::Static,
                arg_count,
            ),
            CNativeCallableIdentity::RuntimeBuiltin { name } => {
                let signature = native_builtin_signature_for_name(name)?;
                if !signature.accepts_arg_count(arg_count) {
                    return None;
                }
                let result_kind = if signature.returns_by_reference {
                    CNativeCallableResultKind::Reference
                } else {
                    CNativeCallableResultKind::NativeValue
                };
                Some(CNativeCallableReturnSummary {
                    result_kind,
                    facts: None,
                })
            }
            CNativeCallableIdentity::DescriptorClosure { closure_key } => self
                .native_descriptor_closure_return_summaries
                .get(closure_key)
                .filter(|summary| summary.accepts_arg_count(arg_count))
                .map(|summary| summary.return_summary.clone()),
        }
    }

    fn native_callable_return_summary_for_declared_method_identity(
        &self,
        class_key: &str,
        method_key: &str,
        staticness: CNativeCallableDeclaredMethodStaticness,
        arg_count: usize,
    ) -> Option<CNativeCallableReturnSummary> {
        let class = self.declared_classes.get(class_key)?;
        let method = class
            .methods
            .iter()
            .find(|method| Self::declared_method_key(&method.decl.name) == method_key)?;
        if !staticness.matches_method(method)
            || !native_user_function_accepts_arg_count(&method.decl, arg_count)
        {
            return None;
        }
        let result_kind = if method.decl.returns_by_reference {
            CNativeCallableResultKind::Reference
        } else {
            CNativeCallableResultKind::NativeValue
        };
        Some(CNativeCallableReturnSummary {
            result_kind,
            facts: method.return_facts.clone(),
        })
    }

    fn declared_method_is_callable_from_external_context(
        &self,
        method: &CDeclaredClassMethod,
        context: CNativeCallableDeclaredMethodExternalContext,
    ) -> bool {
        match context {
            CNativeCallableDeclaredMethodExternalContext::ClassString => {
                method.visibility == ClassVisibility::Public && method.is_static
            }
            CNativeCallableDeclaredMethodExternalContext::ObjectReceiverArray => {
                method.visibility == ClassVisibility::Public
            }
            CNativeCallableDeclaredMethodExternalContext::InvokableObject => {
                method.visibility == ClassVisibility::Public
                    && !method.is_static
                    && Self::declared_method_key(&method.decl.name)
                        == Self::declared_method_key("__invoke")
            }
        }
    }

    fn native_callable_identity_for_declared_method(
        &self,
        class: &CDeclaredClass,
        method: &CDeclaredClassMethod,
    ) -> CNativeCallableIdentity {
        let class_key = Self::declared_class_key(&class.name);
        let method_key = Self::declared_method_key(&method.decl.name);
        if method.is_static {
            CNativeCallableIdentity::DeclaredStaticMethod {
                class_key,
                method_key,
            }
        } else {
            CNativeCallableIdentity::DeclaredInstanceMethod {
                class_key,
                method_key,
            }
        }
    }

    fn native_facts_for_callable_identities_with_result_kind<I>(
        &self,
        identities: I,
        arg_count: usize,
        expected_result_kind: CNativeCallableResultKind,
    ) -> Option<CNativeValueFacts>
    where
        I: IntoIterator<Item = CNativeCallableIdentity>,
    {
        self.intersect_native_value_fact_iter(identities.into_iter().map(|identity| {
            let summary = self.native_callable_return_summary_for_identity(&identity, arg_count)?;
            (summary.result_kind == expected_result_kind)
                .then_some(summary.facts)
                .flatten()
        }))
    }

    fn native_value_facts_for_callable_identities<I>(
        &self,
        identities: I,
        arg_count: usize,
    ) -> Option<CNativeValueFacts>
    where
        I: IntoIterator<Item = CNativeCallableIdentity>,
    {
        self.native_facts_for_callable_identities_with_result_kind(
            identities,
            arg_count,
            CNativeCallableResultKind::NativeValue,
        )
    }

    fn native_reference_return_facts_for_callable_identities<I>(
        &self,
        identities: I,
        arg_count: usize,
    ) -> Option<CNativeValueFacts>
    where
        I: IntoIterator<Item = CNativeCallableIdentity>,
    {
        self.native_facts_for_callable_identities_with_result_kind(
            identities,
            arg_count,
            CNativeCallableResultKind::Reference,
        )
    }

    fn native_callable_identities_for_user_function_call(
        &self,
        name: &str,
    ) -> Option<Vec<CNativeCallableIdentity>> {
        let function_key = self.direct_call_registered_user_function_key(name)?;
        Some(vec![CNativeCallableIdentity::GeneratedFunction {
            function_key,
        }])
    }

    fn native_callable_identity_for_string_value(
        &self,
        value: &str,
    ) -> Option<CNativeCallableIdentity> {
        let function_key = Self::user_function_key(value);
        if self.user_functions.contains_key(&function_key) {
            return Some(CNativeCallableIdentity::GeneratedFunction { function_key });
        }

        if let Some((class_name, method_name)) = native_scoped_callable_string_parts(value) {
            return self.native_callable_static_method_identity(class_name, method_name);
        }

        native_dynamic_callable_builtin_canonical_name(value).map(|name| {
            CNativeCallableIdentity::RuntimeBuiltin {
                name: name.to_string(),
            }
        })
    }

    fn known_callable_expr_has_blocked_runtime_builtin_source_call(&self, expr: &Expr) -> bool {
        let Some(values) = self.static_known_string_values_for_expr(expr) else {
            return false;
        };
        values.values().iter().any(|value| {
            native_builtin_signature_for_name(value).is_some_and(|signature| {
                matches!(
                    signature.source_call_support,
                    CNativeBuiltinSignatureSourceCallSupport::Blocked(_)
                )
            })
        })
    }

    fn native_callable_identities_for_known_string_values(
        &self,
        values: KnownString,
    ) -> Option<HashSet<CNativeCallableIdentity>> {
        let mut identities = HashSet::new();
        for value in values.values() {
            identities.insert(self.native_callable_identity_for_string_value(value)?);
        }
        (!identities.is_empty()).then_some(identities)
    }

    fn native_value_facts_for_user_function_call(
        &self,
        name: &str,
        args: &[Expr],
    ) -> Option<CNativeValueFacts> {
        self.native_value_facts_for_callable_identities(
            self.native_callable_identities_for_user_function_call(name)?,
            args.len(),
        )
    }

    fn native_callable_identities_for_declared_method_candidates(
        &self,
        candidates: Vec<(CDeclaredClass, CDeclaredClassMethod)>,
        staticness: CNativeCallableDeclaredMethodStaticness,
    ) -> Option<Vec<CNativeCallableIdentity>> {
        let identities = candidates
            .into_iter()
            .map(|(class, method)| {
                let class_key = Self::declared_class_key(&class.name);
                let method_key = Self::declared_method_key(&method.decl.name);
                match staticness {
                    CNativeCallableDeclaredMethodStaticness::Instance => {
                        CNativeCallableIdentity::DeclaredInstanceMethod {
                            class_key,
                            method_key,
                        }
                    }
                    CNativeCallableDeclaredMethodStaticness::Static => {
                        CNativeCallableIdentity::DeclaredStaticMethod {
                            class_key,
                            method_key,
                        }
                    }
                }
            })
            .collect::<Vec<_>>();
        (!identities.is_empty()).then_some(identities)
    }

    fn native_value_facts_for_declared_method_candidates(
        &self,
        candidates: Vec<(CDeclaredClass, CDeclaredClassMethod)>,
        staticness: CNativeCallableDeclaredMethodStaticness,
        args: &[Expr],
    ) -> Option<CNativeValueFacts> {
        self.native_value_facts_for_callable_identities(
            self.native_callable_identities_for_declared_method_candidates(candidates, staticness)?,
            args.len(),
        )
    }

    fn native_value_facts_for_declared_class_method_call(
        &self,
        method_name: &str,
        args: &[Expr],
    ) -> Option<CNativeValueFacts> {
        self.native_value_facts_for_declared_method_candidates(
            self.declared_class_method_candidates(method_name),
            CNativeCallableDeclaredMethodStaticness::Instance,
            args,
        )
    }

    fn native_value_facts_for_declared_object_static_method_call(
        &self,
        method_name: &str,
        args: &[Expr],
    ) -> Option<CNativeValueFacts> {
        self.native_value_facts_for_declared_method_candidates(
            self.declared_class_static_method_candidates(method_name),
            CNativeCallableDeclaredMethodStaticness::Static,
            args,
        )
    }

    fn native_value_facts_for_declared_class_static_method_call(
        &self,
        class_name: &str,
        method_name: &str,
        args: &[Expr],
    ) -> Option<CNativeValueFacts> {
        let (class, method) = self.declared_class_static_method(class_name, method_name)?;
        if method.visibility != ClassVisibility::Public {
            return None;
        }
        let identity = CNativeCallableIdentity::DeclaredStaticMethod {
            class_key: Self::declared_class_key(&class.name),
            method_key: Self::declared_method_key(&method.decl.name),
        };
        self.native_value_facts_for_callable_identities(vec![identity], args.len())
    }

    fn callable_value_declared_method_for_identity(
        &self,
        identity: &CNativeCallableIdentity,
    ) -> Option<(NativeMethodStaticSignatureFamily, CDeclaredClassMethod)> {
        match identity {
            CNativeCallableIdentity::DeclaredInstanceMethod {
                class_key,
                method_key,
            } => {
                let class = self.declared_classes.get(class_key)?;
                let method = class.methods.iter().find(|method| {
                    Self::declared_method_key(&method.decl.name) == *method_key && !method.is_static
                })?;
                Some((
                    NativeMethodStaticSignatureFamily::ReceiverMethod,
                    method.clone(),
                ))
            }
            CNativeCallableIdentity::DeclaredStaticMethod {
                class_key,
                method_key,
            } => {
                let class = self.declared_classes.get(class_key)?;
                let method = class.methods.iter().find(|method| {
                    Self::declared_method_key(&method.decl.name) == *method_key && method.is_static
                })?;
                Some((
                    NativeMethodStaticSignatureFamily::StaticMethod,
                    method.clone(),
                ))
            }
            CNativeCallableIdentity::GeneratedFunction { .. }
            | CNativeCallableIdentity::RuntimeBuiltin { .. }
            | CNativeCallableIdentity::DescriptorClosure { .. } => None,
        }
    }

    fn callable_value_source_call_contract_candidate_for_identity(
        &self,
        identity: &CNativeCallableIdentity,
        arg_count: Option<usize>,
    ) -> Option<(
        NativeMethodStaticSignatureFamily,
        CScopedCallableStringSignature,
        NativeMethodStaticSourceCallArgumentStrategy,
    )> {
        match identity {
            CNativeCallableIdentity::GeneratedFunction { function_key } => {
                let function = &self.user_functions.get(function_key)?.decl;
                if arg_count.is_some_and(|arg_count| {
                    !native_user_function_accepts_arg_count(function, arg_count)
                }) {
                    return None;
                }
                Some((
                    NativeMethodStaticSignatureFamily::GeneratedFunction,
                    CScopedCallableStringSignature::from_function(function),
                    NativeMethodStaticSourceCallArgumentStrategy::for_function(function, arg_count),
                ))
            }
            CNativeCallableIdentity::DeclaredInstanceMethod { .. }
            | CNativeCallableIdentity::DeclaredStaticMethod { .. } => {
                let (family, method) =
                    self.callable_value_declared_method_for_identity(identity)?;
                if !native_method_static_source_call_arity_compatible(&method, arg_count) {
                    return None;
                }
                Some((
                    family,
                    CScopedCallableStringSignature::from_method(&method),
                    NativeMethodStaticSourceCallArgumentStrategy::for_method(&method, arg_count),
                ))
            }
            CNativeCallableIdentity::RuntimeBuiltin { name } => {
                let signature = native_builtin_signature_for_name(name)?;
                Some((
                    NativeMethodStaticSignatureFamily::RuntimeBuiltin,
                    signature.source_call_signature_for_arg_count(arg_count)?,
                    NativeMethodStaticSourceCallArgumentStrategy::Frame(
                        signature.source_call_argument_plan(arg_count)?,
                    ),
                ))
            }
            CNativeCallableIdentity::DescriptorClosure { closure_key } => {
                let summary = self
                    .native_descriptor_closure_return_summaries
                    .get(closure_key)?;
                if arg_count.is_some_and(|arg_count| !summary.accepts_arg_count(arg_count)) {
                    return None;
                }
                let argument_plan = summary.source_call_argument_plan();
                let signature = CScopedCallableStringSignature {
                    fixed_param_by_reference: argument_plan
                        .params
                        .iter()
                        .take(argument_plan.fixed_count())
                        .map(|param| param.by_reference)
                        .collect(),
                    returns_by_reference: summary.return_summary.result_kind
                        == CNativeCallableResultKind::Reference,
                };
                Some((
                    NativeMethodStaticSignatureFamily::DescriptorClosure,
                    signature,
                    NativeMethodStaticSourceCallArgumentStrategy::Frame(argument_plan),
                ))
            }
        }
    }

    fn callable_value_source_call_contract_from_identities<I>(
        &self,
        identities: I,
        arg_count: Option<usize>,
        require_param_names: bool,
    ) -> Option<NativeMethodStaticSignatureFallbackContract>
    where
        I: IntoIterator<Item = CNativeCallableIdentity>,
    {
        let mut family = None;
        let mut candidate_count = 0;
        let mut arity_compatible_count = 0;
        let mut signature = None;
        let mut argument_strategy: Option<NativeMethodStaticSourceCallArgumentStrategy> = None;
        for identity in identities {
            candidate_count += 1;
            let (identity_family, identity_signature, identity_argument_strategy) = self
                .callable_value_source_call_contract_candidate_for_identity(&identity, arg_count)?;
            arity_compatible_count += 1;
            family = Some(match family {
                Some(NativeMethodStaticSignatureFamily::StaticMethod)
                    if identity_family == NativeMethodStaticSignatureFamily::ReceiverMethod =>
                {
                    NativeMethodStaticSignatureFamily::ReceiverMethod
                }
                Some(previous) => previous,
                None => identity_family,
            });
            match &signature {
                Some(previous) if previous != &identity_signature => return None,
                Some(_) => {}
                None => signature = Some(identity_signature),
            }
            match &argument_strategy {
                Some(previous)
                    if !native_method_static_argument_strategies_semantically_match(
                        previous,
                        &identity_argument_strategy,
                        require_param_names,
                    ) =>
                {
                    return None;
                }
                Some(_) => {}
                None => argument_strategy = Some(identity_argument_strategy),
            }
        }

        Some(NativeMethodStaticSignatureFallbackContract {
            family: family?,
            candidate_count,
            arity_compatible_count,
            availability: NativeMethodStaticSignatureAvailability::Known(signature?),
            argument_strategy: argument_strategy
                .unwrap_or(NativeMethodStaticSourceCallArgumentStrategy::ForwardCallSite),
        })
    }

    fn native_callable_array_target_and_method<'a>(
        &self,
        items: &'a [ArrayItem],
    ) -> Option<(&'a Expr, &'a Expr)> {
        let mut next_index = 0_i64;
        let mut target = None;
        let mut method = None;

        for item in items {
            if item.by_reference {
                return None;
            }
            let index = match &item.key {
                Some(Expr::Int(index, _)) if *index >= 0 => *index,
                Some(_) => return None,
                None => {
                    let index = next_index;
                    next_index = next_index.checked_add(1)?;
                    index
                }
            };
            if item.key.is_some() && index >= next_index {
                next_index = index.checked_add(1)?;
            }

            match index {
                0 if target.is_none() => target = Some(&item.value),
                1 if method.is_none() => method = Some(&item.value),
                _ => return None,
            }
        }

        Some((target?, method?))
    }

    fn native_callable_literal_class_name(&self, expr: &Expr) -> Option<String> {
        match expr {
            Expr::String(class_name, _) | Expr::ClassNameConstant { class_name, .. } => {
                Some(class_name.clone())
            }
            _ => None,
        }
    }

    fn native_callable_literal_method_name(&self, expr: &Expr) -> Option<String> {
        match expr {
            Expr::String(method_name, _) => Some(method_name.clone()),
            _ => None,
        }
    }

    fn native_callable_static_method_identity(
        &self,
        class_name: &str,
        method_name: &str,
    ) -> Option<CNativeCallableIdentity> {
        let (class, method) = self.declared_class_method_for_external_callable_context(
            class_name,
            method_name,
            CNativeCallableDeclaredMethodExternalContext::ClassString,
        )?;
        Some(self.native_callable_identity_for_declared_method(&class, &method))
    }

    fn declared_class_method_for_external_callable_context(
        &self,
        class_name: &str,
        method_name: &str,
        context: CNativeCallableDeclaredMethodExternalContext,
    ) -> Option<(CDeclaredClass, CDeclaredClassMethod)> {
        let class_key = Self::declared_class_key(class_name);
        let method_key = Self::declared_method_key(method_name);
        for lookup_key in self.declared_class_lookup_keys(&class_key)? {
            let class = self
                .declared_classes
                .get(&lookup_key)
                .expect("declared class lookup key has metadata");
            if let Some(method) = class.methods.iter().find(|method| {
                Self::declared_method_key(&method.decl.name) == method_key
                    && self.declared_method_is_callable_from_external_context(method, context)
            }) {
                return Some((class.clone(), method.clone()));
            }
        }
        None
    }

    fn scoped_callable_string_signature_for_value(
        &self,
        value: &str,
    ) -> Option<CScopedCallableStringSignature> {
        let (class_name, method_name) = native_scoped_callable_string_parts(value)?;
        let (_, method) = self.declared_class_method_for_external_callable_context(
            class_name,
            method_name,
            CNativeCallableDeclaredMethodExternalContext::ClassString,
        )?;
        Some(CScopedCallableStringSignature::from_method(&method))
    }

    fn scoped_callable_string_signature_for_values(
        &self,
        values: &KnownString,
    ) -> Option<CScopedCallableStringSignature> {
        let mut signature = None;
        for value in values.values() {
            let value_signature = self.scoped_callable_string_signature_for_value(value)?;
            match &signature {
                Some(previous) if previous != &value_signature => return None,
                Some(_) => {}
                None => signature = Some(value_signature),
            }
        }
        signature
    }

    fn scoped_callable_string_signature_for_expr(
        &self,
        expr: &Expr,
    ) -> Option<CScopedCallableStringSignature> {
        let values = self.static_known_string_values_for_expr(expr)?;
        self.scoped_callable_string_signature_for_values(&values)
    }

    fn callable_string_signature_for_expr(
        &self,
        expr: &Expr,
        arg_count: usize,
    ) -> Option<CScopedCallableStringSignature> {
        if let Some(signature) = self.scoped_callable_string_signature_for_expr(expr) {
            return Some(signature);
        }
        let values = self.static_known_string_values_for_expr(expr)?;
        native_builtin_runtime_source_call_signature_for_values(&values, arg_count)
    }

    fn receiver_method_signature_fallback_contract(
        &self,
        method_name: &str,
        arg_count: usize,
    ) -> NativeMethodStaticSignatureFallbackContract {
        let candidates = self.declared_class_method_candidates(method_name);
        native_method_static_signature_fallback_contract_from_methods(
            NativeMethodStaticSignatureFamily::ReceiverMethod,
            candidates.iter().map(|(_, method)| method),
            Some(arg_count),
        )
    }

    fn receiver_method_source_call_signature_contract(
        &self,
        target: &Expr,
        method_name: &str,
        arg_count: usize,
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        self.receiver_method_source_call_signature_contract_for_arg_count(
            target,
            method_name,
            Some(arg_count),
            access_context,
        )
    }

    fn receiver_method_source_call_signature_contract_for_args(
        &self,
        target: &Expr,
        method_name: &str,
        args: &[Expr],
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        self.receiver_method_source_call_signature_contract_for_arg_count_with_options(
            target,
            method_name,
            native_source_call_arg_count_for_args(args),
            access_context,
            call_arguments_have_named(args) || call_arguments_have_spread(args),
        )
    }

    fn receiver_method_source_call_signature_contract_for_arg_count(
        &self,
        target: &Expr,
        method_name: &str,
        arg_count: Option<usize>,
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        self.receiver_method_source_call_signature_contract_for_arg_count_with_options(
            target,
            method_name,
            arg_count,
            access_context,
            false,
        )
    }

    fn receiver_method_source_call_signature_contract_for_arg_count_with_options(
        &self,
        target: &Expr,
        method_name: &str,
        arg_count: Option<usize>,
        access_context: NativeSourceCallAccessContext<'_>,
        require_param_names: bool,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let facts = self.native_value_facts_for_expr(target)?;
        let object = facts.object.as_ref()?;
        if object.declared_class_keys.is_empty() {
            return self.interface_receiver_method_source_call_signature_contract(
                object,
                method_name,
                arg_count,
                access_context,
                require_param_names,
            );
        }

        let mut methods = Vec::new();
        let mut saw_magic_call = false;
        for class_key in &object.declared_class_keys {
            match self.declared_class_receiver_method_for_key(class_key, method_name) {
                Some((class, method)) => {
                    if !self.declared_class_member_visible_from_source_access(
                        &class.name,
                        method.visibility,
                        access_context,
                    ) && self
                        .declared_class_public_receiver_magic_call_method_for_key(class_key)
                        .is_some()
                    {
                        saw_magic_call = true;
                        continue;
                    }
                    if !native_method_static_source_call_arity_compatible(&method, arg_count) {
                        return None;
                    }
                    methods.push(method);
                }
                None if self
                    .declared_class_public_receiver_magic_call_method_for_key(class_key)
                    .is_some() =>
                {
                    saw_magic_call = true;
                }
                None => return None,
            }
        }

        if saw_magic_call {
            return Some(NativeMethodStaticSignatureFallbackContract {
                family: NativeMethodStaticSignatureFamily::ReceiverMethod,
                candidate_count: methods.len(),
                arity_compatible_count: methods.len(),
                availability: NativeMethodStaticSignatureAvailability::RuntimeFallback(
                    NativeMethodStaticSignatureFallbackReason::MagicReceiverFallback,
                ),
                argument_strategy: NativeMethodStaticSourceCallArgumentStrategy::RuntimeDynamic,
            });
        }

        let contract = native_method_static_signature_fallback_contract_from_methods_with_options(
            NativeMethodStaticSignatureFamily::ReceiverMethod,
            methods.iter(),
            arg_count,
            require_param_names,
        );
        matches!(
            contract.availability,
            NativeMethodStaticSignatureAvailability::Known(_)
        )
        .then_some(contract)
    }

    fn interface_receiver_method_source_call_signature_contract(
        &self,
        object: &CNativeObjectFacts,
        method_name: &str,
        arg_count: Option<usize>,
        access_context: NativeSourceCallAccessContext<'_>,
        require_param_names: bool,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let interface_methods =
            self.declared_interface_receiver_methods_for_object_facts(object, method_name)?;
        let mut contract = native_method_static_signature_contract_from_interface_methods(
            NativeMethodStaticSignatureFamily::ReceiverMethod,
            interface_methods.iter().map(|method| &method.method),
            arg_count,
        );
        if arg_count.is_none() && !require_param_names {
            return matches!(
                contract.availability,
                NativeMethodStaticSignatureAvailability::Known(_)
            )
            .then_some(contract);
        }
        let implementation_methods = self
            .declared_interface_implementation_receiver_methods_for_object_facts(
                object,
                method_name,
                access_context,
            )?;
        let implementation_contract =
            native_method_static_signature_fallback_contract_from_methods_with_options(
                NativeMethodStaticSignatureFamily::ReceiverMethod,
                implementation_methods.iter(),
                arg_count,
                true,
            );
        if !matches!(
            (
                &contract.availability,
                &implementation_contract.availability
            ),
            (
                NativeMethodStaticSignatureAvailability::Known(_),
                NativeMethodStaticSignatureAvailability::Known(_),
            )
        ) {
            return None;
        }
        if !native_method_static_argument_strategies_semantically_match(
            &contract.argument_strategy,
            &implementation_contract.argument_strategy,
            true,
        ) {
            return None;
        }
        contract.candidate_count = implementation_contract.candidate_count;
        contract.arity_compatible_count = implementation_contract.arity_compatible_count;
        contract.argument_strategy = implementation_contract.argument_strategy;
        Some(contract)
    }

    fn declared_interface_receiver_methods_for_object_facts(
        &self,
        object: &CNativeObjectFacts,
        method_name: &str,
    ) -> Option<Vec<CDeclaredInterfaceMethod>> {
        let method_key = Self::declared_method_key(method_name);
        let mut methods = Vec::new();
        let mut seen = HashSet::new();
        for interface_key in &object.implemented_interface_keys {
            let interface_methods = self.declared_interface_methods(interface_key).ok()?;
            for method in interface_methods {
                let key = format!(
                    "{}::{}",
                    method.declaring_interface_name.to_ascii_lowercase(),
                    Self::declared_method_key(&method.method.function.name)
                );
                if !method.method.is_static
                    && Self::declared_method_key(&method.method.function.name) == method_key
                    && seen.insert(key)
                {
                    methods.push(method);
                }
            }
        }
        (!methods.is_empty()).then_some(methods)
    }

    fn declared_interface_implementation_receiver_methods_for_object_facts(
        &self,
        object: &CNativeObjectFacts,
        method_name: &str,
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<Vec<CDeclaredClassMethod>> {
        let mut methods = Vec::new();
        let mut seen = HashSet::new();
        for class_key in &self.declared_class_order {
            let class = self
                .declared_classes
                .get(class_key)
                .expect("registered class key has metadata");
            if !object
                .implemented_interface_keys
                .iter()
                .any(|interface_key| {
                    class
                        .interface_names
                        .iter()
                        .any(|name| Self::declared_interface_key(name) == *interface_key)
                })
            {
                continue;
            }
            let (declaring_class, method) =
                self.declared_class_receiver_method_for_key(class_key, method_name)?;
            if !self.declared_class_member_visible_from_source_access(
                &declaring_class.name,
                method.visibility,
                access_context,
            ) || method.is_static
            {
                return None;
            }
            let key = format!(
                "{}::{}",
                Self::declared_class_key(&declaring_class.name),
                Self::declared_method_key(&method.decl.name)
            );
            if seen.insert(key) {
                methods.push(method);
            }
        }
        (!methods.is_empty()).then_some(methods)
    }

    fn receiver_dynamic_method_source_call_signature_contract(
        &self,
        target: &Expr,
        method: &Expr,
        arg_count: usize,
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        self.receiver_dynamic_method_source_call_signature_contract_for_arg_count_with_options(
            target,
            method,
            Some(arg_count),
            access_context,
            false,
        )
    }

    fn receiver_dynamic_method_source_call_signature_contract_for_args(
        &self,
        target: &Expr,
        method: &Expr,
        args: &[Expr],
        access_context: NativeSourceCallAccessContext<'_>,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        self.receiver_dynamic_method_source_call_signature_contract_for_arg_count_with_options(
            target,
            method,
            native_source_call_arg_count_for_args(args),
            access_context,
            call_arguments_have_named(args) || call_arguments_have_spread(args),
        )
    }

    fn receiver_dynamic_method_source_call_signature_contract_for_arg_count_with_options(
        &self,
        target: &Expr,
        method: &Expr,
        arg_count: Option<usize>,
        access_context: NativeSourceCallAccessContext<'_>,
        require_param_names: bool,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let facts = self.native_value_facts_for_expr(target)?;
        let object = facts.object.as_ref()?;
        if object.declared_class_keys.is_empty() {
            return None;
        }

        let Some(method_names) = self.static_known_string_values_for_expr(method) else {
            if object.declared_class_keys.iter().all(|class_key| {
                self.declared_class_public_magic_call_method_for_key(class_key)
                    .is_some()
            }) {
                return Some(NativeMethodStaticSignatureFallbackContract {
                    family: NativeMethodStaticSignatureFamily::ReceiverMethod,
                    candidate_count: 0,
                    arity_compatible_count: 0,
                    availability: NativeMethodStaticSignatureAvailability::RuntimeFallback(
                        NativeMethodStaticSignatureFallbackReason::MagicReceiverFallback,
                    ),
                    argument_strategy: NativeMethodStaticSourceCallArgumentStrategy::RuntimeDynamic,
                });
            }
            return Some(native_method_static_runtime_signature_fallback_contract(
                NativeMethodStaticSignatureFamily::ReceiverMethod,
            ));
        };
        let mut methods = Vec::new();
        let mut saw_magic_call = false;
        let mut saw_runtime_lookup_only_name = false;

        for class_key in &object.declared_class_keys {
            for method_name in method_names.values() {
                if let Some((class, method)) =
                    self.declared_class_receiver_method_for_key(class_key, method_name)
                {
                    if !self.declared_class_member_visible_from_source_access(
                        &class.name,
                        method.visibility,
                        access_context,
                    ) && self
                        .declared_class_public_magic_call_method_for_key(class_key)
                        .is_some()
                    {
                        saw_magic_call = true;
                        continue;
                    }
                    if !native_method_static_source_call_arity_compatible(&method, arg_count) {
                        return None;
                    }
                    methods.push(method);
                    continue;
                }
                if self
                    .declared_class_public_magic_call_method_for_key(class_key)
                    .is_some()
                {
                    saw_magic_call = true;
                } else {
                    saw_runtime_lookup_only_name = true;
                }
            }
        }

        if saw_magic_call && methods.is_empty() {
            return Some(NativeMethodStaticSignatureFallbackContract {
                family: NativeMethodStaticSignatureFamily::ReceiverMethod,
                candidate_count: 0,
                arity_compatible_count: 0,
                availability: NativeMethodStaticSignatureAvailability::RuntimeFallback(
                    NativeMethodStaticSignatureFallbackReason::MagicReceiverFallback,
                ),
                argument_strategy: NativeMethodStaticSourceCallArgumentStrategy::RuntimeDynamic,
            });
        }

        if saw_magic_call || methods.is_empty() || saw_runtime_lookup_only_name {
            return Some(native_method_static_runtime_signature_fallback_contract(
                NativeMethodStaticSignatureFamily::ReceiverMethod,
            ));
        }

        Some(
            native_method_static_signature_fallback_contract_from_methods_with_options(
                NativeMethodStaticSignatureFamily::ReceiverMethod,
                methods.iter(),
                arg_count,
                require_param_names,
            ),
        )
    }

    fn static_method_signature_fallback_contract(
        &self,
        method_name: &str,
        arg_count: usize,
    ) -> NativeMethodStaticSignatureFallbackContract {
        let candidates = self.declared_class_static_method_candidates(method_name);
        native_method_static_signature_fallback_contract_from_methods(
            NativeMethodStaticSignatureFamily::StaticMethod,
            candidates.iter().map(|(_, method)| method),
            Some(arg_count),
        )
    }

