    fn emit_materialized_call_argument_spread_unpack(
        &mut self,
        materialized: &str,
        value: CNativeValueMaterialization,
        failure_cleanup: &str,
    ) {
        let value_aux_cleanup = native_value_aux_cleanup_after_consuming_handle(&value);
        let diagnostic = self.next_native_name("materialized_unpack_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        let unpack_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); phpc_native_diagnostic_free({diagnostic}); {diagnostic}.ptr = NULL; }} {}{failure_cleanup}",
            c_cleanup_sequence(&value_aux_cleanup)
        );
        let error_exit = self.native_error_exit(&unpack_failure_cleanup);
        self.body.push(format!(
            "if (!phpc_native_materialized_call_arguments_unpack_array_value_and_free({materialized}, {}, &{diagnostic})) {{ {error_exit} }}",
            value.handle
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.extend(value_aux_cleanup);
    }

    fn emit_materialized_call_argument_entries_handle(
        &mut self,
        params: Option<&[FunctionParam]>,
        args: &[Expr],
        owner_failure_cleanup: &str,
        callee: NativeCallCallee,
    ) -> CompileResult<(String, String)> {
        self.uses_native_callable_helpers = true;
        self.uses_native_materialized_call_argument_helpers = true;

        let materialized = self.next_native_name("materialized_call_args");
        self.body.push(format!(
            "phpc_NativeMaterializedCallArgumentsHandle {materialized} = phpc_native_materialized_call_arguments_new();"
        ));
        let materialized_error_exit = self.native_error_exit(owner_failure_cleanup);
        self.body.push(format!(
            "if (phpc_native_materialized_call_arguments_is_null({materialized})) {{ {materialized_error_exit} }}"
        ));
        let materialized_failure_cleanup = format!(
            "phpc_native_materialized_call_arguments_free({materialized}); {owner_failure_cleanup}"
        );

        let fixed_param_count = params.map(native_function_fixed_param_count).unwrap_or(0);
        let mut next_positional_index = 0usize;
        let mut positional_param_mapping_is_stable = true;
        for arg in args {
            let source_failure_cleanup = materialized_failure_cleanup.clone();
            match arg {
                Expr::SpreadArgument { expr, .. } => {
                    positional_param_mapping_is_stable = false;
                    let value = self
                        .materialize_native_value_result_operand(expr, &source_failure_cleanup)?;
                    self.emit_materialized_call_argument_spread_unpack(
                        &materialized,
                        value,
                        &source_failure_cleanup,
                    );
                }
                Expr::NamedArgument { name, expr, .. } => {
                    positional_param_mapping_is_stable = false;
                    let push_reference = params.is_some_and(|params| {
                        params
                            .iter()
                            .take(fixed_param_count)
                            .find(|param| param.name == *name)
                            .is_some_and(|param| param.by_reference)
                    });
                    if push_reference {
                        let reference = self.materialize_call_reference_argument(
                            expr,
                            expr.span(),
                            &source_failure_cleanup,
                            callee,
                        )?;
                        self.emit_materialized_call_argument_reference_push(
                            &materialized,
                            reference,
                            Some(name.as_str()),
                            &source_failure_cleanup,
                        );
                    } else {
                        let value = self.materialize_native_value_result_operand(
                            expr,
                            &source_failure_cleanup,
                        )?;
                        self.emit_materialized_call_argument_value_push(
                            &materialized,
                            value,
                            Some(name.as_str()),
                            &source_failure_cleanup,
                        );
                    }
                }
                _ => {
                    let push_reference = params.is_some_and(|params| {
                        positional_param_mapping_is_stable
                            && next_positional_index < fixed_param_count
                            && params[next_positional_index].by_reference
                    });
                    if positional_param_mapping_is_stable {
                        next_positional_index += 1;
                    }
                    if push_reference {
                        let reference = self.materialize_call_reference_argument(
                            arg,
                            arg.span(),
                            &source_failure_cleanup,
                            callee,
                        )?;
                        self.emit_materialized_call_argument_reference_push(
                            &materialized,
                            reference,
                            None,
                            &source_failure_cleanup,
                        );
                    } else {
                        let value = self.materialize_native_value_result_operand(
                            arg,
                            &source_failure_cleanup,
                        )?;
                        self.emit_materialized_call_argument_value_push(
                            &materialized,
                            value,
                            None,
                            &source_failure_cleanup,
                        );
                    }
                }
            }
        }

        Ok((materialized, materialized_failure_cleanup))
    }

    fn emit_materialized_native_source_call_arguments_handle(
        &mut self,
        prefix: &str,
        params: &[FunctionParam],
        args: &[Expr],
        span: Span,
        owner_failure_cleanup: &str,
        callee: NativeCallCallee,
    ) -> CompileResult<String> {
        let (materialized, materialized_failure_cleanup) = self
            .emit_materialized_call_argument_entries_handle(
                Some(params),
                args,
                owner_failure_cleanup,
                callee,
            )?;

        let fixed_count = native_function_fixed_param_count(params);
        let fixed_params = params.iter().take(fixed_count).collect::<Vec<_>>();
        let mut metadata_cleanup = Vec::new();
        let mut parameter_names = Vec::new();
        let mut required_flags = Vec::new();
        let mut by_reference_flags = Vec::new();
        let mut default_handles = Vec::new();

        for (index, param) in fixed_params.iter().enumerate() {
            let name = self.emit_native_static_text_source_call_string_operand(
                "materialized_parameter_name",
                &param.name,
            );
            metadata_cleanup.extend(name.cleanup_after_use.clone());
            parameter_names.push(name.handle);
            required_flags.push(if param.default.is_none() { "1" } else { "0" }.to_string());
            by_reference_flags.push(if param.by_reference { "1" } else { "0" }.to_string());

            if let Some(default) = &param.default {
                let default_failure_cleanup = format!(
                    "{}{materialized_failure_cleanup}",
                    c_cleanup_sequence(&metadata_cleanup)
                );
                let value = self
                    .materialize_native_value_result_operand(default, &default_failure_cleanup)?;
                metadata_cleanup.extend(value.cleanup_after_use.clone());
                default_handles.push(value.handle);
            } else {
                default_handles.push("(phpc_NativeValueHandle){0}".to_string());
            }

            debug_assert_eq!(parameter_names.len(), index + 1);
        }

        let (parameter_name_arg, required_arg, by_reference_arg, default_arg) = if fixed_count == 0
        {
            let names = self.next_native_name("materialized_parameter_names");
            let required = self.next_native_name("materialized_parameter_required");
            let by_reference = self.next_native_name("materialized_parameter_by_reference");
            let defaults = self.next_native_name("materialized_parameter_defaults");
            self.body.push(format!(
                "phpc_NativeStringHandle {names}[1] = {{ (phpc_NativeStringHandle){{0}} }};"
            ));
            self.body.push(format!("uint8_t {required}[1] = {{ 0 }};"));
            self.body
                .push(format!("uint8_t {by_reference}[1] = {{ 0 }};"));
            self.body.push(format!(
                "phpc_NativeValueHandle {defaults}[1] = {{ (phpc_NativeValueHandle){{0}} }};"
            ));
            (names, required, by_reference, defaults)
        } else {
            let names = self.next_native_name("materialized_parameter_names");
            let required = self.next_native_name("materialized_parameter_required");
            let by_reference = self.next_native_name("materialized_parameter_by_reference");
            let defaults = self.next_native_name("materialized_parameter_defaults");
            self.body.push(format!(
                "phpc_NativeStringHandle {names}[{fixed_count}] = {{ {} }};",
                parameter_names.join(", ")
            ));
            self.body.push(format!(
                "uint8_t {required}[{fixed_count}] = {{ {} }};",
                required_flags.join(", ")
            ));
            self.body.push(format!(
                "uint8_t {by_reference}[{fixed_count}] = {{ {} }};",
                by_reference_flags.join(", ")
            ));
            self.body.push(format!(
                "phpc_NativeValueHandle {defaults}[{fixed_count}] = {{ {} }};",
                default_handles.join(", ")
            ));
            (names, required, by_reference, defaults)
        };

        let has_variadic = native_function_variadic_param(params).is_some();
        let variadic_by_reference = native_function_variadic_param(params)
            .map(|(_, param)| param.by_reference)
            .unwrap_or(false);
        let variadic_name = if let Some((_, param)) = native_function_variadic_param(params) {
            let name = self.emit_native_static_text_source_call_string_operand(
                "materialized_variadic_parameter_name",
                &param.name,
            );
            metadata_cleanup.extend(name.cleanup_after_use.clone());
            name.handle
        } else {
            "(phpc_NativeStringHandle){0}".to_string()
        };
        let call_arguments = self.next_native_name(prefix);
        let diagnostic = self.next_native_name("materialized_finalize_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "phpc_NativeCallArgumentsHandle {call_arguments} = phpc_native_materialized_call_arguments_finalize_with_diagnostic({materialized}, {parameter_name_arg}, {required_arg}, {by_reference_arg}, {default_arg}, {fixed_count}, {variadic_name}, {}, {}, &{diagnostic});",
            if has_variadic { "true" } else { "false" },
            if variadic_by_reference { "true" } else { "false" }
        ));
        let finalize_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); phpc_native_diagnostic_free({diagnostic}); {diagnostic}.ptr = NULL; }} {}{materialized_failure_cleanup}",
            c_cleanup_sequence(&metadata_cleanup)
        );
        let finalize_error_exit = self.native_error_exit(&finalize_failure_cleanup);
        self.body.push(format!(
            "if ({diagnostic}.ptr != NULL) {{ {finalize_error_exit} }}"
        ));
        self.body.push(format!(
            "if (phpc_native_call_arguments_is_null({call_arguments})) {{ {finalize_error_exit} }}"
        ));
        self.body.push(format!(
            "phpc_native_materialized_call_arguments_free({materialized});"
        ));
        self.body.extend(metadata_cleanup);

        let _ = span;
        Ok(call_arguments)
    }

    fn emit_runtime_dynamic_materialized_source_call_arguments_handle(
        &mut self,
        prefix: &str,
        callable: &str,
        args: &[Expr],
        owner_failure_cleanup: &str,
    ) -> CompileResult<String> {
        let (materialized, materialized_failure_cleanup) = self
            .emit_materialized_call_argument_entries_handle(
                None,
                args,
                owner_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
        let call_arguments = self.next_native_name(prefix);
        let diagnostic = self.next_native_name("runtime_signature_finalize_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "phpc_NativeCallArgumentsHandle {call_arguments} = phpc_native_callable_value_finalize_materialized_arguments_with_diagnostic({callable}, {materialized}, &{diagnostic});"
        ));
        let finalize_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); phpc_native_diagnostic_free({diagnostic}); {diagnostic}.ptr = NULL; }} {materialized_failure_cleanup}"
        );
        let finalize_error_exit = self.native_error_exit(&finalize_failure_cleanup);
        self.body.push(format!(
            "if ({diagnostic}.ptr != NULL) {{ {finalize_error_exit} }}"
        ));
        self.body.push(format!(
            "if (phpc_native_call_arguments_is_null({call_arguments})) {{ {finalize_error_exit} }}"
        ));
        self.body.push(format!(
            "phpc_native_materialized_call_arguments_free({materialized});"
        ));
        Ok(call_arguments)
    }

    fn emit_materialized_forwarded_native_source_call_arguments(
        &mut self,
        call_arguments: &str,
        args: &[Expr],
        owner_failure_cleanup: &str,
    ) -> CompileResult<()> {
        let (materialized, materialized_failure_cleanup) = self
            .emit_materialized_call_argument_entries_handle(
                None,
                args,
                owner_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
        let diagnostic = self.next_native_name("materialized_forward_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "if (!phpc_native_materialized_call_arguments_forward_source_to_call_arguments_with_diagnostic({materialized}, {call_arguments}, &{diagnostic})) {{ {} }}",
            self.native_error_exit(&format!(
                "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); phpc_native_diagnostic_free({diagnostic}); {diagnostic}.ptr = NULL; }} {materialized_failure_cleanup}"
            ))
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.push(format!(
            "phpc_native_materialized_call_arguments_free({materialized});"
        ));
        Ok(())
    }

    fn emit_native_source_call_argument(
        &mut self,
        call_arguments: &str,
        arg: &Expr,
        source_name: Option<&str>,
        span: Span,
        call_cleanup: &str,
        callee: NativeCallCallee,
        push_reference: bool,
    ) -> CompileResult<()> {
        let arg = call_argument_expr(arg);
        if push_reference {
            let reference =
                self.materialize_call_reference_argument(arg, span, call_cleanup, callee)?;
            if let Some(source_name) = source_name {
                let name = self.emit_native_static_text_source_call_string_operand(
                    "named_call_argument",
                    source_name,
                );
                let name_cleanup = c_cleanup_sequence(&name.cleanup_after_use);
                let push_failure_cleanup = format!("{name_cleanup}{call_cleanup}");
                self.body.push(format!(
                    "if (!phpc_native_call_arguments_push_named_reference_and_free({call_arguments}, {}, {})) {{ {} }}",
                    name.handle,
                    reference.handle,
                    self.native_error_exit(&push_failure_cleanup)
                ));
                self.body.extend(name.cleanup_after_use);
            } else {
                self.body.push(format!(
                    "if (!phpc_native_call_arguments_push_reference_and_free({call_arguments}, {})) {{ {} }}",
                    reference.handle,
                    self.native_error_exit(call_cleanup)
                ));
            }
        } else {
            let value = self.materialize_native_value_result_operand(arg, call_cleanup)?;
            self.emit_native_source_call_materialized_value_argument_push(
                call_arguments,
                value,
                source_name,
                call_cleanup,
            );
        }
        Ok(())
    }

    fn normalize_native_call_arguments_for_params(
        &self,
        params: &[FunctionParam],
        args: &[Expr],
        span: Span,
    ) -> CompileResult<NormalizedCallArguments> {
        let signature = call_argument_signature_from_params(params).map_err(|error| {
            self.unsupported(
                span,
                format!("unsupported named argument metadata for native call lowering: {error}"),
            )
        })?;
        normalize_call_arguments(&signature, &call_argument_contract_kinds(args)).map_err(|error| {
            self.unsupported(
                span,
                format!("unsupported named argument binding for native call lowering: {error}"),
            )
        })
    }

    fn normalize_native_magic_source_call_arguments(
        &self,
        args: &[Expr],
        span: Span,
    ) -> CompileResult<NormalizedCallArguments> {
        let signature = CallArgumentSignature::new(vec![
            CallArgumentParameter::optional("args").with_variadic()
        ])
        .map_err(|error| {
            self.unsupported(
                span,
                format!(
                    "unsupported named magic argument metadata for native call lowering: {error}"
                ),
            )
        })?;
        normalize_call_arguments(&signature, &call_argument_contract_kinds(args)).map_err(|error| {
            self.unsupported(
                span,
                format!(
                    "unsupported named magic argument binding for native call lowering: {error}"
                ),
            )
        })
    }

    fn normalized_call_argument_source_modes(
        &self,
        plan: &NormalizedCallArguments,
        source_count: usize,
    ) -> Vec<CallArgumentPassingMode> {
        let mut modes = vec![CallArgumentPassingMode::Value; source_count];
        for slot in &plan.fixed_slots {
            if let CallArgumentSlotSource::Supplied { source_index } = slot.source {
                modes[source_index] = slot.passing_mode;
            }
        }
        if let Some(variadic) = &plan.variadic_slot {
            for entry in &variadic.entries {
                modes[entry.source_index] = variadic.entry_passing_mode;
            }
        }
        modes
    }

    fn pending_evaluated_call_argument_cleanup(
        evaluated: &[Option<CNativeEvaluatedCallArgument>],
        consumed: &[bool],
        excluding_source_index: Option<usize>,
    ) -> String {
        let mut cleanup = String::new();
        for (index, argument) in evaluated.iter().enumerate() {
            if consumed[index] || excluding_source_index == Some(index) {
                continue;
            }
            if let Some(argument) = argument {
                cleanup.push_str(&c_cleanup_sequence(argument.cleanup_after_use()));
            }
        }
        cleanup
    }

    fn materialize_normalized_call_argument_sources(
        &mut self,
        args: &[Expr],
        plan: &NormalizedCallArguments,
        span: Span,
        call_cleanup: &str,
        callee: NativeCallCallee,
    ) -> CompileResult<(Vec<Option<CNativeEvaluatedCallArgument>>, Vec<bool>)> {
        let mut evaluated = (0..args.len()).map(|_| None).collect::<Vec<_>>();
        let consumed = vec![false; args.len()];
        let source_modes = self.normalized_call_argument_source_modes(plan, args.len());

        for source in &plan.source_evaluations {
            let source_index = source.source_index;
            let expr = call_argument_expr(&args[source_index]);
            let failure_cleanup = format!(
                "{}{call_cleanup}",
                Self::pending_evaluated_call_argument_cleanup(&evaluated, &consumed, None)
            );
            let argument = match source_modes[source_index] {
                CallArgumentPassingMode::Reference => {
                    let reference = self.materialize_call_reference_argument(
                        expr,
                        span,
                        &failure_cleanup,
                        callee,
                    )?;
                    CNativeEvaluatedCallArgument::Reference {
                        handle: reference.handle,
                        cleanup_after_use: reference.cleanup_after_use,
                    }
                }
                CallArgumentPassingMode::Value => {
                    let value =
                        self.materialize_native_value_result_operand(expr, &failure_cleanup)?;
                    let cleanup_after_consuming_handle =
                        native_value_aux_cleanup_after_consuming_handle(&value);
                    CNativeEvaluatedCallArgument::Value {
                        handle: value.handle,
                        cleanup_after_use: value.cleanup_after_use,
                        cleanup_after_consuming_handle,
                    }
                }
            };
            evaluated[source_index] = Some(argument);
        }

        Ok((evaluated, consumed))
    }

    fn emit_evaluated_call_argument_push(
        &mut self,
        call_arguments: &str,
        evaluated: &mut [Option<CNativeEvaluatedCallArgument>],
        consumed: &mut [bool],
        source_index: usize,
        source_name: Option<&str>,
        call_cleanup: &str,
        span: Span,
    ) -> CompileResult<()> {
        let pending_cleanup =
            Self::pending_evaluated_call_argument_cleanup(evaluated, consumed, Some(source_index));
        let failure_cleanup = format!("{pending_cleanup}{call_cleanup}");
        let Some(argument) = evaluated[source_index].as_ref() else {
            return Err(self.unsupported(
                span,
                "internal call argument lowering error: normalized source slot was not evaluated",
            ));
        };

        match argument {
            CNativeEvaluatedCallArgument::Reference { handle, .. } => {
                if let Some(source_name) = source_name {
                    let name = self.emit_native_static_text_source_call_string_operand(
                        "named_call_argument",
                        source_name,
                    );
                    let name_cleanup = c_cleanup_sequence(&name.cleanup_after_use);
                    let failure_cleanup = format!("{name_cleanup}{failure_cleanup}");
                    self.body.push(format!(
                        "if (!phpc_native_call_arguments_push_named_reference_and_free({call_arguments}, {}, {handle})) {{ {} }}",
                        name.handle,
                        self.native_error_exit(&failure_cleanup)
                    ));
                    self.body.extend(name.cleanup_after_use);
                } else {
                    self.body.push(format!(
                        "if (!phpc_native_call_arguments_push_reference_and_free({call_arguments}, {handle})) {{ {} }}",
                        self.native_error_exit(&failure_cleanup)
                    ));
                }
            }
            CNativeEvaluatedCallArgument::Value {
                handle,
                cleanup_after_consuming_handle,
                ..
            } => {
                if let Some(source_name) = source_name {
                    let name = self.emit_native_static_text_source_call_string_operand(
                        "named_call_argument",
                        source_name,
                    );
                    let name_cleanup = c_cleanup_sequence(&name.cleanup_after_use);
                    let failure_cleanup = format!("{name_cleanup}{failure_cleanup}");
                    self.body.push(format!(
                        "if (!phpc_native_call_arguments_push_named_value_and_free({call_arguments}, {}, {handle})) {{ {} }}",
                        name.handle,
                        self.native_error_exit(&failure_cleanup)
                    ));
                    self.body.extend(name.cleanup_after_use);
                } else {
                    self.body.push(format!(
                        "if (!phpc_native_call_arguments_push_value_and_free({call_arguments}, {handle})) {{ {} }}",
                        self.native_error_exit(&failure_cleanup)
                    ));
                }
                self.body.extend(cleanup_after_consuming_handle.clone());
            }
        }
        consumed[source_index] = true;
        Ok(())
    }

    fn emit_variadic_argument_array_insert_named_materialized(
        &mut self,
        array: &str,
        param: &FunctionParam,
        name: &str,
        value: CNativeValueMaterialization,
        callable_name: &str,
        failure_cleanup: &str,
        span: Span,
    ) -> CompileResult<()> {
        let array_failure_cleanup = format!("phpc_native_array_free({array}); {failure_cleanup}");
        let value = self.coerce_variadic_argument_value(
            param,
            value,
            callable_name,
            &array_failure_cleanup,
        );
        let key_value =
            self.emit_native_value_for_cvalue(CValue::String(name.to_string()), span)?;
        let key_cleanup = format!("phpc_native_value_free({key_value});");
        let key = self.next_native_name("named_variadic_key");
        self.body.push(format!(
            "phpc_NativeArrayKeyMaterializationResult {key} = phpc_native_value_to_array_key({key_value});"
        ));
        self.body.push(key_cleanup);
        let diagnostic = self.next_native_name("named_variadic_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        let insert_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} phpc_native_array_key_materialization_result_free({key}); {}{array_failure_cleanup}",
            c_cleanup_sequence(&value.cleanup_after_use)
        );
        let error_exit = self.native_error_exit(&insert_failure_cleanup);
        self.body.push(format!(
            "if (!phpc_native_array_insert_key_value_with_diagnostic({array}, {key}, {}, &{diagnostic})) {{ {error_exit} }}",
            value.handle
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.push(format!(
            "phpc_native_array_key_materialization_result_free({key});"
        ));
        self.body.extend(value.cleanup_after_use);
        Ok(())
    }

    fn emit_variadic_argument_array_append_reference_materialized(
        &mut self,
        array: &str,
        reference_handle: &str,
        cleanup_after_use: &[String],
        failure_cleanup: &str,
    ) {
        self.uses_native_reference_helpers = true;
        let diagnostic = self.next_native_name("variadic_ref_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        let append_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} {}phpc_native_array_free({array}); {failure_cleanup}",
            c_cleanup_sequence(cleanup_after_use)
        );
        let error_exit = self.native_error_exit(&append_failure_cleanup);
        self.body.push(format!(
            "if (!phpc_native_array_append_reference_with_diagnostic({array}, {reference_handle}, &{diagnostic})) {{ {error_exit} }}"
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.extend(cleanup_after_use.iter().cloned());
    }

    fn emit_variadic_argument_array_insert_named_reference_materialized(
        &mut self,
        array: &str,
        name: &str,
        reference_handle: &str,
        cleanup_after_use: &[String],
        failure_cleanup: &str,
        span: Span,
    ) -> CompileResult<()> {
        self.uses_native_reference_helpers = true;
        let array_failure_cleanup = format!("phpc_native_array_free({array}); {failure_cleanup}");
        let key_value =
            self.emit_native_value_for_cvalue(CValue::String(name.to_string()), span)?;
        let key_cleanup = format!("phpc_native_value_free({key_value});");
        let key = self.next_native_name("named_variadic_key");
        self.body.push(format!(
            "phpc_NativeArrayKeyMaterializationResult {key} = phpc_native_value_to_array_key({key_value});"
        ));
        self.body.push(key_cleanup);
        let diagnostic = self.next_native_name("named_variadic_ref_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        let insert_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} phpc_native_array_key_materialization_result_free({key}); {}{array_failure_cleanup}",
            c_cleanup_sequence(cleanup_after_use)
        );
        let error_exit = self.native_error_exit(&insert_failure_cleanup);
        self.body.push(format!(
            "if (!phpc_native_array_insert_key_reference_with_diagnostic({array}, {key}, {reference_handle}, &{diagnostic})) {{ {error_exit} }}"
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.push(format!(
            "phpc_native_array_key_materialization_result_free({key});"
        ));
        self.body.extend(cleanup_after_use.iter().cloned());
        Ok(())
    }

    fn materialize_variadic_argument_array_from_normalized_entries(
        &mut self,
        param: &FunctionParam,
        variadic: &crate::call_arguments::CallArgumentVariadicSlot,
        args: &[Expr],
        evaluated: &mut [Option<CNativeEvaluatedCallArgument>],
        consumed: &mut [bool],
        callable_name: &str,
        failure_cleanup: &str,
        span: Span,
    ) -> CompileResult<CNativeValueMaterialization> {
        let pending_cleanup =
            Self::pending_evaluated_call_argument_cleanup(evaluated, consumed, None);
        let array =
            self.emit_empty_variadic_argument_array(&format!("{pending_cleanup}{failure_cleanup}"));
        for entry in &variadic.entries {
            let source_index = entry.source_index;
            let pending_cleanup = Self::pending_evaluated_call_argument_cleanup(
                evaluated,
                consumed,
                Some(source_index),
            );
            let entry_failure_cleanup = format!("{pending_cleanup}{failure_cleanup}");
            match variadic.entry_passing_mode {
                CallArgumentPassingMode::Value => {
                    let Some(CNativeEvaluatedCallArgument::Value {
                        handle,
                        cleanup_after_use,
                        ..
                    }) = evaluated[source_index].as_ref()
                    else {
                        return Err(self.unsupported(
                            span,
                            "unsupported named argument binding for native call lowering: variadic source slot did not produce a value",
                        ));
                    };
                    let value = CNativeValueMaterialization {
                        handle: handle.clone(),
                        cleanup_after_use: cleanup_after_use.clone(),
                    };
                    match &entry.key {
                        CallArgumentVariadicKey::NextInteger => {
                            self.emit_variadic_argument_array_append(
                                &array,
                                param,
                                value,
                                callable_name,
                                &entry_failure_cleanup,
                            );
                        }
                        CallArgumentVariadicKey::Named(name) => {
                            self.emit_variadic_argument_array_insert_named_materialized(
                                &array,
                                param,
                                name,
                                value,
                                callable_name,
                                &entry_failure_cleanup,
                                call_argument_expr(&args[source_index]).span(),
                            )?;
                        }
                    }
                }
                CallArgumentPassingMode::Reference => {
                    let Some(CNativeEvaluatedCallArgument::Reference {
                        handle,
                        cleanup_after_use,
                    }) = evaluated[source_index].as_ref()
                    else {
                        return Err(self.unsupported(
                            span,
                            "unsupported named argument binding for native call lowering: by-reference variadic source slot did not produce a reference",
                        ));
                    };
                    match &entry.key {
                        CallArgumentVariadicKey::NextInteger => {
                            self.emit_variadic_argument_array_append_reference_materialized(
                                &array,
                                handle,
                                cleanup_after_use,
                                &entry_failure_cleanup,
                            );
                        }
                        CallArgumentVariadicKey::Named(name) => {
                            self.emit_variadic_argument_array_insert_named_reference_materialized(
                                &array,
                                name,
                                handle,
                                cleanup_after_use,
                                &entry_failure_cleanup,
                                call_argument_expr(&args[source_index]).span(),
                            )?;
                        }
                    }
                }
            }
            consumed[source_index] = true;
        }

        let pending_cleanup =
            Self::pending_evaluated_call_argument_cleanup(evaluated, consumed, None);
        Ok(self.materialize_variadic_argument_array_value(
            array,
            &format!("{pending_cleanup}{failure_cleanup}"),
        ))
    }

    fn emit_normalized_native_source_call_arguments(
        &mut self,
        call_arguments: &str,
        params: &[FunctionParam],
        args: &[Expr],
        span: Span,
        call_cleanup: &str,
        callee: NativeCallCallee,
        callable_name: &str,
    ) -> CompileResult<()> {
        let plan = self.normalize_native_call_arguments_for_params(params, args, span)?;
        let (mut evaluated, mut consumed) = self.materialize_normalized_call_argument_sources(
            args,
            &plan,
            span,
            call_cleanup,
            callee,
        )?;

        for slot in &plan.fixed_slots {
            let param = params
                .get(slot.parameter_index)
                .expect("normalized fixed slot must refer to declared parameter");
            match slot.source {
                CallArgumentSlotSource::Supplied { source_index } => {
                    self.emit_evaluated_call_argument_push(
                        call_arguments,
                        &mut evaluated,
                        &mut consumed,
                        source_index,
                        None,
                        call_cleanup,
                        span,
                    )?;
                }
                CallArgumentSlotSource::Default => {
                    let default = param.default.as_ref().ok_or_else(|| {
                        self.unsupported(
                            span,
                            "unsupported named argument binding for native call lowering: required parameter has no source or default",
                        )
                    })?;
                    self.emit_native_source_call_argument(
                        call_arguments,
                        default,
                        None,
                        span,
                        call_cleanup,
                        callee,
                        param.by_reference,
                    )?;
                }
            }
        }

        if let Some(variadic) = &plan.variadic_slot {
            let param = params
                .get(variadic.parameter_index)
                .expect("normalized variadic slot must refer to declared parameter");
            let variadic_value = self.materialize_variadic_argument_array_from_normalized_entries(
                param,
                variadic,
                args,
                &mut evaluated,
                &mut consumed,
                callable_name,
                call_cleanup,
                span,
            )?;
            self.emit_native_source_call_materialized_value_argument_push(
                call_arguments,
                variadic_value,
                None,
                call_cleanup,
            );
        }

        Ok(())
    }

    fn emit_runtime_callable_value_call_arguments(
        &mut self,
        call_arguments: &str,
        args: &[Expr],
        span: Span,
        call_cleanup: &str,
        callee: NativeCallCallee,
        signature: Option<&CScopedCallableStringSignature>,
        preserve_named_source_keys_for_magic_args: bool,
    ) -> CompileResult<()> {
        if preserve_named_source_keys_for_magic_args && signature.is_none() {
            if call_arguments_have_spread(args) {
                return self.emit_materialized_forwarded_native_source_call_arguments(
                    call_arguments,
                    args,
                    call_cleanup,
                );
            }
            if call_arguments_have_named(args) {
                let plan = self.normalize_native_magic_source_call_arguments(args, span)?;
                let (mut evaluated, mut consumed) = self
                    .materialize_normalized_call_argument_sources(
                        args,
                        &plan,
                        span,
                        call_cleanup,
                        callee,
                    )?;
                let Some(variadic) = &plan.variadic_slot else {
                    return Err(self.unsupported(
                        span,
                        "internal named magic argument lowering error: source-order variadic slot was not produced",
                    ));
                };
                for entry in &variadic.entries {
                    let source_name = match &entry.key {
                        CallArgumentVariadicKey::NextInteger => None,
                        CallArgumentVariadicKey::Named(name) => Some(name.as_str()),
                    };
                    self.emit_evaluated_call_argument_push(
                        call_arguments,
                        &mut evaluated,
                        &mut consumed,
                        entry.source_index,
                        source_name,
                        call_cleanup,
                        span,
                    )?;
                }
                return Ok(());
            }
        }
        if call_arguments_have_named(args) {
            return Err(self.unsupported(span, NAMED_ARGUMENT_UNSUPPORTED_CALL_FAMILY_REJECTION));
        }
        if call_arguments_have_spread(args) {
            return Err(self.unsupported(
                span,
                ARGUMENT_UNPACKING_REQUIRES_MATERIALIZED_ENTRY_PRODUCER_REJECTION,
            ));
        }

        for (index, arg) in args.iter().enumerate() {
            let push_reference = signature.map_or_else(
                || self.runtime_dynamic_call_reference_argument_is_supported(arg),
                |signature| signature.param_is_by_reference(index),
            );
            self.emit_native_source_call_argument(
                call_arguments,
                arg,
                None,
                span,
                call_cleanup,
                callee,
                push_reference,
            )?;
        }
        Ok(())
    }

    fn emit_native_method_static_source_call_arguments_handle(
        &mut self,
        prefix: &str,
        args: &[Expr],
        span: Span,
        owner_failure_cleanup: &str,
        signature_contract: &NativeMethodStaticSignatureFallbackContract,
    ) -> CompileResult<String> {
        match signature_contract.argument_strategy() {
            NativeMethodStaticSourceCallArgumentStrategy::RuntimeDynamic
            | NativeMethodStaticSourceCallArgumentStrategy::ForwardCallSite => self
                .emit_native_source_call_arguments_handle(
                    prefix,
                    args,
                    span,
                    owner_failure_cleanup,
                    NativeCallCallee::MethodDispatch,
                    signature_contract.signature(),
                    signature_contract.preserves_named_source_keys_for_magic_args(),
                ),
            NativeMethodStaticSourceCallArgumentStrategy::Frame(plan) => {
                if call_arguments_have_spread(args) {
                    return self.emit_materialized_native_source_call_arguments_handle(
                        prefix,
                        &plan.params,
                        args,
                        span,
                        owner_failure_cleanup,
                        NativeCallCallee::MethodDispatch,
                    );
                }

                let call_arguments = self
                    .emit_empty_native_source_call_arguments_handle(prefix, owner_failure_cleanup);
                let call_cleanup = format!(
                    "phpc_native_call_arguments_free({call_arguments}); {owner_failure_cleanup}"
                );
                self.emit_native_method_static_source_call_frame_arguments(
                    &call_arguments,
                    args,
                    span,
                    &call_cleanup,
                    plan,
                )?;
                if plan.variadic_param().is_some() {
                    let mark_error_exit = self.native_error_exit(&call_cleanup);
                    self.body.push(format!(
                        "if (!phpc_native_call_arguments_mark_finalized_variadic({call_arguments})) {{ {mark_error_exit} }}"
                    ));
                }
                Ok(call_arguments)
            }
        }
    }

    fn emit_native_method_static_source_call_frame_arguments(
        &mut self,
        call_arguments: &str,
        args: &[Expr],
        span: Span,
        call_cleanup: &str,
        plan: &NativeMethodStaticSourceCallArgumentPlan,
    ) -> CompileResult<()> {
        self.emit_normalized_native_source_call_arguments(
            call_arguments,
            &plan.params,
            args,
            span,
            call_cleanup,
            NativeCallCallee::MethodDispatch,
            "method/static source-call",
        )
    }

    fn materialize_variadic_argument_array_from_exprs(
        &mut self,
        param: &FunctionParam,
        args: &[Expr],
        callable_name: &str,
        failure_cleanup: &str,
    ) -> CompileResult<CNativeValueMaterialization> {
        if param.by_reference {
            return Err(self.unsupported(
                param.span,
                "unsupported native call lowering: by-reference variadic collection requires materialized reference slots",
            ));
        }

        let array = self.emit_empty_variadic_argument_array(failure_cleanup);
        for arg in args {
            let arg_failure_cleanup = format!("phpc_native_array_free({array}); {failure_cleanup}");
            let value = self.materialize_native_value_result_operand(arg, &arg_failure_cleanup)?;
            self.emit_variadic_argument_array_append(
                &array,
                param,
                value,
                callable_name,
                failure_cleanup,
            );
        }
        Ok(self.materialize_variadic_argument_array_value(array, failure_cleanup))
    }

    fn emit_empty_variadic_argument_array(&mut self, failure_cleanup: &str) -> String {
        self.uses_native_array_helpers = true;
        let array = self.next_native_name("variadic_args");
        self.body.push(format!(
            "phpc_NativeArrayHandle {array} = phpc_native_array_empty();"
        ));
        let error_exit = self.native_error_exit(failure_cleanup);
        self.body
            .push(format!("if ({array}.ptr == NULL) {{ {error_exit} }}"));
        array
    }

    fn emit_variadic_argument_array_append(
        &mut self,
        array: &str,
        param: &FunctionParam,
        value: CNativeValueMaterialization,
        callable_name: &str,
        failure_cleanup: &str,
    ) {
        let array_failure_cleanup = format!("phpc_native_array_free({array}); {failure_cleanup}");
        let value = self.coerce_variadic_argument_value(
            param,
            value,
            callable_name,
            &array_failure_cleanup,
        );
        self.emit_variadic_argument_array_append_materialized(array, value, &array_failure_cleanup);
    }

    fn coerce_variadic_argument_value(
        &mut self,
        param: &FunctionParam,
        value: CNativeValueMaterialization,
        callable_name: &str,
        failure_cleanup: &str,
    ) -> CNativeValueMaterialization {
        let Some(type_decl) = param
            .type_decl
            .as_ref()
            .filter(|decl| !native_function_type_decl_is_mixed(decl))
        else {
            return value;
        };

        let handle = self.next_native_name("variadic_arg");
        let original_cleanup = value.cleanup_after_use.clone();
        let type_failure_cleanup =
            format!("{}{failure_cleanup}", c_cleanup_sequence(&original_cleanup));
        self.emit_call_frame_type_coercion_assignment_for_callable(
            &handle,
            &value.handle,
            callable_name,
            &format!("parameter ${}", param.name),
            &type_decl.text,
            &type_failure_cleanup,
        );
        self.body.extend(original_cleanup);
        CNativeValueMaterialization {
            handle: handle.clone(),
            cleanup_after_use: vec![format!("phpc_native_value_free({handle});")],
        }
    }

    fn emit_variadic_collection_type_coercion_assignment(
        &mut self,
        target_handle: &str,
        source_handle: &str,
        param: &FunctionParam,
        callable_name: &str,
        failure_cleanup: &str,
    ) {
        let Some(type_decl) = param
            .type_decl
            .as_ref()
            .filter(|decl| !native_function_type_decl_is_mixed(decl))
        else {
            self.body.push(format!(
                "{target_handle} = phpc_native_value_clone({source_handle});"
            ));
            let error_exit = self.native_error_exit(failure_cleanup);
            self.body.push(format!(
                "if ({target_handle}.ptr == NULL) {{ {error_exit} }}"
            ));
            return;
        };

        self.uses_native_string_helpers = true;
        self.uses_native_call_type_helpers = true;

        let (callable_bytes, callable_len) =
            self.emit_call_type_static_bytes("call_type_callable_bytes", callable_name);
        let (label_bytes, label_len) = self.emit_call_type_static_bytes(
            "call_type_label_bytes",
            &format!("parameter ${}", param.name),
        );
        let (type_bytes, type_len) =
            self.emit_call_type_static_bytes("call_type_decl_bytes", &type_decl.text);
        let diagnostic = self.next_native_name("variadic_collection_type_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "{target_handle} = phpc_native_value_coerce_variadic_collection_type_with_diagnostic({source_handle}, {callable_bytes}, {callable_len}, {label_bytes}, {label_len}, {type_bytes}, {type_len}, &{diagnostic});"
        ));
        let error_exit = self.native_error_exit(failure_cleanup);
        self.body.push(format!(
            "if ({diagnostic}.ptr != NULL || {target_handle}.ptr == NULL) {{ if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} if ({target_handle}.ptr != NULL) {{ phpc_native_value_free({target_handle}); }} {error_exit} }}"
        ));
    }

    fn emit_variadic_argument_array_append_materialized(
        &mut self,
        array: &str,
        value: CNativeValueMaterialization,
        failure_cleanup: &str,
    ) {
        let diagnostic = self.next_native_name("variadic_arg_diagnostic");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        let append_failure_cleanup = format!(
            "if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} {}{failure_cleanup}",
            c_cleanup_sequence(&value.cleanup_after_use)
        );
        let error_exit = self.native_error_exit(&append_failure_cleanup);
        self.body.push(format!(
            "if (!phpc_native_array_append_value_with_diagnostic({array}, {}, &{diagnostic})) {{ {error_exit} }}",
            value.handle
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        self.body.extend(value.cleanup_after_use);
    }

    fn materialize_variadic_argument_array_value(
        &mut self,
        array: String,
        failure_cleanup: &str,
    ) -> CNativeValueMaterialization {
        let value = self.next_native_name("variadic_args_value");
        self.body.push(format!(
            "phpc_NativeValueHandle {value} = phpc_native_value_from_array({array});"
        ));
        let error_exit = self.native_error_exit(&format!(
            "phpc_native_array_free({array}); {failure_cleanup}"
        ));
        self.body
            .push(format!("if ({value}.ptr == NULL) {{ {error_exit} }}"));
        self.body.push(format!("phpc_native_array_free({array});"));
        CNativeValueMaterialization {
            handle: value.clone(),
            cleanup_after_use: vec![format!("phpc_native_value_free({value});")],
        }
    }

    fn materialize_runtime_dynamic_user_function_call(
        &mut self,
        callee_value: CValue,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeValueMaterialization>> {
        self.uses_native_string_helpers = true;
        self.uses_native_dynamic_call_helpers = true;

        let callee = self.materialize_native_array_c_value_handle(callee_value, span)?;
        let shared_cleanup = callee.cleanup_after_use.clone();

        let matched = self.next_native_name("dynamic_user_function_matched");
        let status = self.next_native_name("dynamic_user_function_status");
        let result = self.next_native_name("dynamic_user_function_result");
        self.body.push(format!("_Bool {matched} = 0;"));
        self.body.push(format!("int {status} = 0;"));
        self.body.push(format!(
            "phpc_NativeValueHandle {result} = (phpc_NativeValueHandle){{0}};"
        ));

        let functions = self
            .user_function_order
            .iter()
            .map(|key| {
                self.user_functions
                    .get(key)
                    .expect("registered function key has metadata")
                    .clone()
            })
            .collect::<Vec<_>>();

        if functions
            .iter()
            .any(|function| function.frame_environment.root_symbols)
            || self.runtime_dynamic_call_needs_symbol_table_for_reference_args(&functions, args)
        {
            let symbol_table_failure_cleanup =
                format!("{}{}", c_cleanup_sequence(&shared_cleanup), failure_cleanup);
            self.ensure_globals_symbol_table(&symbol_table_failure_cleanup, span)?;
        }

        self.emit_runtime_dynamic_descriptor_closure_branch(
            &callee.handle,
            args,
            &shared_cleanup,
            failure_cleanup,
            &matched,
            &result,
        )?;
        self.emit_runtime_dynamic_callable_array_branch(
            &callee.handle,
            args,
            span,
            &shared_cleanup,
            failure_cleanup,
            &matched,
            &result,
        )?;
        self.emit_runtime_dynamic_callable_object_branch(
            &callee.handle,
            args,
            span,
            &shared_cleanup,
            failure_cleanup,
            &matched,
            &result,
        )?;

        'function_branches: for function in functions {
            let (name_bytes, name_len) =
                self.emit_call_type_static_bytes("dynamic_call_name_bytes", &function.decl.name);
            self.body.push(format!(
                "if (!{matched} && phpc_native_value_dynamic_call_name_matches({}, {name_bytes}, {name_len})) {{",
                callee.handle
            ));
            self.body.push(format!("  {matched} = 1;"));

            if function.frame_environment.request_state {
                let branch_failure_cleanup =
                    format!("{}{}", c_cleanup_sequence(&shared_cleanup), failure_cleanup);
                self.emit_runtime_dynamic_call_failure(
                    &callee.handle,
                    "request-state frame environment handoff is only supported for direct generated user-function calls",
                    &branch_failure_cleanup,
                    "  ",
                );
                self.body.push("}".to_string());
                continue;
            }

            if !native_user_function_accepts_arg_count(&function.decl, args.len()) {
                let branch_failure_cleanup =
                    format!("{}{}", c_cleanup_sequence(&shared_cleanup), failure_cleanup);
                self.emit_runtime_dynamic_call_failure(
                    &callee.handle,
                    "argument count is outside the generated frame arity/default/variadic subset",
                    &branch_failure_cleanup,
                    "  ",
                );
                self.body.push("}".to_string());
                continue;
            }

            let mut branch_cleanup = Vec::new();
            let mut call_args = vec![self.user_function_call_depth_argument()];
            let fixed_count = native_user_function_fixed_param_count(&function.decl);
            for (index, param) in function.decl.params.iter().take(fixed_count).enumerate() {
                let default_failure_cleanup = format!(
                    "{}{}{}",
                    c_cleanup_sequence(&branch_cleanup),
                    c_cleanup_sequence(&shared_cleanup),
                    failure_cleanup
                );
                if param.by_reference {
                    let Some(arg) = args.get(index) else {
                        return Err(self.unsupported_call_operation(
                            NativeCallOperation::value_result(
                                span,
                                NativeCallCallee::DynamicExpression,
                                NativeCallBlocker::UnknownCalleeDiagnostics,
                            ),
                        ));
                    };
                    if !self.runtime_dynamic_call_reference_argument_is_supported(arg) {
                        let branch_failure_cleanup = format!(
                            "{}{}{}",
                            c_cleanup_sequence(&branch_cleanup),
                            c_cleanup_sequence(&shared_cleanup),
                            failure_cleanup
                        );
                        self.emit_runtime_dynamic_call_failure(
                            &callee.handle,
                            "by-reference parameter binding requires a supported lvalue argument in the generated-C runtime dynamic frame subset",
                            &branch_failure_cleanup,
                            "  ",
                        );
                        self.body.push("}".to_string());
                        continue 'function_branches;
                    }
                    let reference = self.materialize_call_reference_argument(
                        arg,
                        span,
                        &default_failure_cleanup,
                        NativeCallCallee::DynamicExpression,
                    )?;
                    branch_cleanup.extend(reference.cleanup_after_use);
                    call_args.push(reference.handle);
                    continue;
                }

                let value_expr = if let Some(arg) = args.get(index) {
                    arg
                } else {
                    param.default.as_ref().ok_or_else(|| {
                        self.unsupported_call_operation(NativeCallOperation::value_result(
                            span,
                            NativeCallCallee::DynamicExpression,
                            NativeCallBlocker::UnknownCalleeDiagnostics,
                        ))
                    })?
                };
                let value = self.materialize_native_value_result_operand(
                    value_expr,
                    &default_failure_cleanup,
                )?;
                branch_cleanup.extend(value.cleanup_after_use.clone());
                call_args.push(value.handle);
            }
            if let Some((_, variadic_param)) = native_user_function_variadic_param(&function.decl) {
                let variadic_failure_cleanup = format!(
                    "{}{}{}",
                    c_cleanup_sequence(&branch_cleanup),
                    c_cleanup_sequence(&shared_cleanup),
                    failure_cleanup
                );
                let callable_name = format!("{}()", function.decl.name);
                let variadic_value = self.materialize_variadic_argument_array_from_exprs(
                    variadic_param,
                    &args[fixed_count..],
                    &callable_name,
                    &variadic_failure_cleanup,
                )?;
                branch_cleanup.extend(variadic_value.cleanup_after_use.clone());
                call_args.push(variadic_value.handle);
            }
            if function.frame_environment.root_symbols {
                let table_failure_cleanup = format!(
                    "{}{}{}",
                    c_cleanup_sequence(&branch_cleanup),
                    c_cleanup_sequence(&shared_cleanup),
                    failure_cleanup
                );
                let table = self.ensure_globals_symbol_table(&table_failure_cleanup, span)?;
                call_args.insert(1, table);
            }
            self.body.push(format!("  {status} = 0;"));
            call_args.push(format!("&{status}"));
            self.body.push(format!(
                "  {result} = {}({});",
                function.c_name,
                call_args.join(", ")
            ));
            let call_failure_cleanup = format!(
                "{}{}{}",
                c_cleanup_sequence(&branch_cleanup),
                c_cleanup_sequence(&shared_cleanup),
                failure_cleanup
            );
            let error_exit = self.native_error_exit(&call_failure_cleanup);
            self.body.push(format!(
                "  if ({status} != 1 || {result}.ptr == NULL) {{ {error_exit} }}"
            ));
            for cleanup in branch_cleanup {
                self.body.push(format!("  {cleanup}"));
            }
            self.body.push("}".to_string());
        }

        self.emit_runtime_dynamic_callable_builtin_branches(
            &callee.handle,
            args,
            span,
            &shared_cleanup,
            failure_cleanup,
            &matched,
            &result,
        )?;

        let unknown_failure_cleanup =
            format!("{}{}", c_cleanup_sequence(&shared_cleanup), failure_cleanup);
        self.body.push(format!("if (!{matched}) {{"));
        self.emit_runtime_dynamic_call_failure(
            &callee.handle,
            "runtime dynamic generated-C lookup did not find a registered user-function frame or supported native builtin family",
            &unknown_failure_cleanup,
            "  ",
        );
        self.body.push("}".to_string());
        self.body.extend(shared_cleanup);

        Ok(Some(CNativeValueMaterialization {
            handle: result.clone(),
            cleanup_after_use: vec![format!("phpc_native_value_free({result});")],
        }))
    }

    fn emit_runtime_dynamic_descriptor_closure_branch(
        &mut self,
        callee_handle: &str,
        args: &[Expr],
        shared_cleanup: &[String],
        failure_cleanup: &str,
        matched: &str,
        result: &str,
    ) -> CompileResult<()> {
        self.uses_native_closure_helpers = true;
        self.uses_native_reference_helpers = true;
        if let Some(arg) = args
            .iter()
            .find(|arg| self.runtime_dynamic_call_reference_argument_needs_symbol_table(arg))
        {
            let table_failure_cleanup =
                format!("{}{}", c_cleanup_sequence(shared_cleanup), failure_cleanup);
            self.ensure_globals_symbol_table(&table_failure_cleanup, arg.span())?;
        }

        self.body.push(format!(
            "if (!{matched} && phpc_native_value_is_descriptor_closure({callee_handle})) {{"
        ));
        self.body.push(format!("  {matched} = 1;"));

        let mut branch_cleanup = Vec::new();
        let mut closure_args = Vec::new();
        for (index, arg) in args.iter().enumerate() {
            let argument = self.materialize_descriptor_closure_argument(
                callee_handle,
                index,
                arg,
                shared_cleanup,
                failure_cleanup,
                &branch_cleanup,
            )?;
            branch_cleanup.extend(argument.cleanup_after_use);
            closure_args.push(argument.handle);
        }

        let (arg_handles, arg_count) = if closure_args.is_empty() {
            ("NULL".to_string(), "0".to_string())
        } else {
            let handles = self.next_native_name("closure_arg_values");
            let argument_entries = closure_args
                .iter()
                .map(|argument| argument.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            self.body.push(format!(
                "  phpc_NativeClosureArgument {handles}[] = {{ {argument_entries} }};"
            ));
            (handles, closure_args.len().to_string())
        };

        let invocation = self.next_native_name("closure_invoke_result");
        self.body.push(format!(
            "  phpc_NativeClosureInvocationResult {invocation} = phpc_native_closure_invoke_result({callee_handle}, {}, {arg_handles}, {arg_count});",
            self.user_function_call_depth_argument()
        ));
        let branch_failure_cleanup = format!(
            "{}{}{}",
            c_cleanup_sequence(&branch_cleanup),
            c_cleanup_sequence(shared_cleanup),
            failure_cleanup
        );
        let error_exit = self.native_error_exit(&format!(
            "phpc_native_closure_result_report_diagnostic({invocation}); phpc_native_closure_result_free({invocation}); {branch_failure_cleanup}"
        ));
        self.body.push(format!(
            "  if ({invocation}.diagnostic.ptr != NULL || ({invocation}.value.ptr == NULL && {invocation}.reference.ptr == NULL)) {{ {error_exit} }}"
        ));
        self.body
            .push(format!("  if ({invocation}.value.ptr != NULL) {{"));
        self.body
            .push(format!("    {result} = {invocation}.value;"));
        self.body.push(format!(
            "    {invocation}.value = (phpc_NativeValueHandle){{0}};"
        ));
        self.body.push("  } else {".to_string());
        self.body.push(format!(
            "    {result} = phpc_native_reference_value_clone({invocation}.reference);"
        ));
        self.body
            .push(format!("    if ({result}.ptr == NULL) {{ {error_exit} }}"));
        self.body.push("  }".to_string());
        self.body
            .push(format!("  phpc_native_closure_result_free({invocation});"));
        for cleanup in branch_cleanup {
            self.body.push(format!("  {cleanup}"));
        }
        self.body.push("}".to_string());

        Ok(())
    }

    fn emit_runtime_dynamic_callable_array_branch(
        &mut self,
        callee_handle: &str,
        args: &[Expr],
        span: Span,
        shared_cleanup: &[String],
        failure_cleanup: &str,
        matched: &str,
        result: &str,
    ) -> CompileResult<()> {
        let instance_candidates = self
            .declared_class_dynamic_method_candidates()
            .into_iter()
            .filter(|(_, method)| method.visibility == ClassVisibility::Public)
            .collect::<Vec<_>>();
        let static_candidates = self
            .declared_class_dynamic_static_method_candidates()
            .into_iter()
            .filter(|(_, _, method)| method.visibility == ClassVisibility::Public)
            .collect::<Vec<_>>();
        if instance_candidates.is_empty() && static_candidates.is_empty() {
            return Ok(());
        }

        self.uses_native_dynamic_call_helpers = true;
        self.uses_native_object_instanceof_helpers = true;
        self.uses_native_object_method_helpers = true;

        let parts = self.next_native_name("callable_array_parts");
        let array_matched = self.next_native_name("callable_array_matched");
        let status = self.next_native_name("callable_array_status");
        self.body.push(format!("if (!{matched}) {{"));
        self.body.push(format!(
            "  phpc_NativeCallableArrayParts {parts} = phpc_native_value_callable_array_parts({callee_handle});"
        ));
        self.body.push(format!(
            "  if ({parts}.status == PHPC_NATIVE_CALLABLE_ARRAY_PARTS_OK) {{"
        ));
        self.body.push(format!("    {matched} = 1;"));
        self.body.push(format!("    _Bool {array_matched} = 0;"));
        self.body.push(format!("    int {status} = 0;"));

        for (target_class_name, _method_class, method) in static_candidates {
            let (class_name, class_name_len) = self
                .emit_call_type_static_bytes("callable_array_class_name_bytes", &target_class_name);
            let (method_name, method_name_len) = self
                .emit_call_type_static_bytes("callable_array_method_name_bytes", &method.decl.name);
            self.body.push(format!(
                "    if (!{array_matched} && phpc_native_value_dynamic_call_name_matches({parts}.target, {class_name}, {class_name_len}) && phpc_native_value_dynamic_call_name_matches({parts}.method, {method_name}, {method_name_len})) {{"
            ));
            self.body.push(format!("      {array_matched} = 1;"));

            let parts_cleanup = format!("phpc_native_callable_array_parts_free({parts});");
            if !native_user_function_accepts_arg_count(&method.decl, args.len()) {
                let branch_failure_cleanup = format!(
                    "{parts_cleanup}{}{}",
                    c_cleanup_sequence(shared_cleanup),
                    failure_cleanup
                );
                self.emit_runtime_dynamic_call_failure(
                    callee_handle,
                    "callable array resolved to a generated public static method but argument count is outside the generated frame arity/default/variadic subset",
                    &branch_failure_cleanup,
                    "      ",
                );
                self.body.push("    }".to_string());
                continue;
            }

            let argument_failure_cleanup = format!(
                "{parts_cleanup}{}{}",
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let frame_arguments = self.materialize_declared_method_frame_arguments(
                &target_class_name,
                &method,
                None,
                args,
                span,
                &argument_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
            let (mut call_args, branch_cleanup) = frame_arguments.into_call_args_and_cleanup();
            self.body.push(format!("      {status} = 0;"));
            call_args.push(format!("&{status}"));
            self.body.push(format!(
                "      {result} = {}({});",
                method.c_name,
                call_args.join(", ")
            ));
            let call_failure_cleanup = format!(
                "{}{parts_cleanup}{}{}",
                c_cleanup_sequence(&branch_cleanup),
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let error_exit = self.native_error_exit(&call_failure_cleanup);
            self.body.push(format!(
                "      if ({status} != 1 || {result}.ptr == NULL) {{ {error_exit} }}"
            ));
            for cleanup in branch_cleanup {
                self.body.push(format!("      {cleanup}"));
            }
            self.body.push("    }".to_string());
        }

        for (class, method) in instance_candidates {
            let (method_name, method_name_len) = self
                .emit_call_type_static_bytes("callable_array_method_name_bytes", &method.decl.name);
            let (class_name, class_name_len) =
                self.emit_call_type_static_bytes("callable_array_class_name_bytes", &class.name);
            let diagnostic = self.next_native_name("callable_array_receiver_diagnostic");
            let class_match = self.next_native_name("callable_array_receiver_match");
            self.body.push(format!(
                "    if (!{array_matched} && phpc_native_value_dynamic_call_name_matches({parts}.method, {method_name}, {method_name_len})) {{"
            ));
            self.body.push(format!(
                "      phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"
            ));
            self.body.push(format!(
                "      _Bool {class_match} = phpc_native_value_class_relationship_matches_with_diagnostic({parts}.target, {class_name}, {class_name_len}, 0, &{diagnostic});"
            ));
            let parts_cleanup = format!("phpc_native_callable_array_parts_free({parts});");
            let class_failure_cleanup = format!(
                "phpc_native_diagnostic_report({diagnostic}); {parts_cleanup}{}{}",
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let class_error_exit = self.native_error_exit(&class_failure_cleanup);
            self.body.push(format!(
                "      if ({diagnostic}.ptr != NULL) {{ {class_error_exit} }}"
            ));
            self.body
                .push(format!("      phpc_native_diagnostic_free({diagnostic});"));
            self.body.push(format!("      if ({class_match}) {{"));
            self.body.push(format!("        {array_matched} = 1;"));

            if !native_user_function_accepts_arg_count(&method.decl, args.len()) {
                let branch_failure_cleanup = format!(
                    "{parts_cleanup}{}{}",
                    c_cleanup_sequence(shared_cleanup),
                    failure_cleanup
                );
                self.emit_runtime_dynamic_call_failure(
                    callee_handle,
                    "callable array resolved to a generated public instance method but argument count is outside the generated frame arity/default/variadic subset",
                    &branch_failure_cleanup,
                    "        ",
                );
                self.body.push("      }".to_string());
                self.body.push("    }".to_string());
                continue;
            }

            let argument_failure_cleanup = format!(
                "{parts_cleanup}{}{}",
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let frame_arguments = self.materialize_declared_method_frame_arguments(
                &class.name,
                &method,
                Some(&format!("{parts}.target")),
                args,
                span,
                &argument_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
            let (mut call_args, branch_cleanup) = frame_arguments.into_call_args_and_cleanup();
            self.body.push(format!("        {status} = 0;"));
            call_args.push(format!("&{status}"));
            self.body.push(format!(
                "        {result} = {}({});",
                method.c_name,
                call_args.join(", ")
            ));
            let call_failure_cleanup = format!(
                "{}{parts_cleanup}{}{}",
                c_cleanup_sequence(&branch_cleanup),
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let error_exit = self.native_error_exit(&call_failure_cleanup);
            self.body.push(format!(
                "        if ({status} != 1 || {result}.ptr == NULL) {{ {error_exit} }}"
            ));
            for cleanup in branch_cleanup {
                self.body.push(format!("        {cleanup}"));
            }
            self.body.push("      }".to_string());
            self.body.push("    }".to_string());
        }

        let array_failure_cleanup = format!(
            "phpc_native_callable_array_parts_free({parts}); {}{}",
            c_cleanup_sequence(shared_cleanup),
            failure_cleanup
        );
        self.body.push(format!("    if (!{array_matched}) {{"));
        self.emit_runtime_dynamic_call_failure(
            callee_handle,
            "callable array did not resolve to a supported generated public method frame",
            &array_failure_cleanup,
            "      ",
        );
        self.body.push("    }".to_string());
        self.body.push(format!(
            "    phpc_native_callable_array_parts_free({parts});"
        ));
        self.body.push("  }".to_string());
        self.body.push("}".to_string());

        Ok(())
    }

    fn emit_runtime_dynamic_callable_object_branch(
        &mut self,
        callee_handle: &str,
        args: &[Expr],
        span: Span,
        shared_cleanup: &[String],
        failure_cleanup: &str,
        matched: &str,
        result: &str,
    ) -> CompileResult<()> {
        let candidates = self
            .declared_class_callable_object_candidates()
            .into_iter()
            .filter(|(_, method)| method.visibility == ClassVisibility::Public)
            .collect::<Vec<_>>();
        if candidates.is_empty() {
            return Ok(());
        }

        self.uses_native_array_helpers = true;
        self.uses_native_object_instanceof_helpers = true;
        self.uses_native_object_method_helpers = true;

        let object_matched = self.next_native_name("callable_object_matched");
        let status = self.next_native_name("callable_object_status");
        self.body.push(format!(
            "if (!{matched} && phpc_native_value_type_predicate({callee_handle}, PHPC_NATIVE_VALUE_TYPE_IS_OBJECT)) {{"
        ));
        self.body.push(format!("  {matched} = 1;"));
        self.body.push(format!("  _Bool {object_matched} = 0;"));
        self.body.push(format!("  int {status} = 0;"));

        for (class, method) in candidates {
            let (class_name, class_name_len) =
                self.emit_call_type_static_bytes("callable_object_class_name_bytes", &class.name);
            let diagnostic = self.next_native_name("callable_object_match_diagnostic");
            let class_match = self.next_native_name("callable_object_class_match");
            self.body.push(format!("  if (!{object_matched}) {{"));
            self.body.push(format!(
                "    phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"
            ));
            self.body.push(format!(
                "    _Bool {class_match} = phpc_native_value_class_relationship_matches_with_diagnostic({callee_handle}, {class_name}, {class_name_len}, 0, &{diagnostic});"
            ));
            let class_failure_cleanup = format!(
                "phpc_native_diagnostic_report({diagnostic}); {}{}",
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let class_error_exit = self.native_error_exit(&class_failure_cleanup);
            self.body.push(format!(
                "    if ({diagnostic}.ptr != NULL) {{ {class_error_exit} }}"
            ));
            self.body
                .push(format!("    phpc_native_diagnostic_free({diagnostic});"));
            self.body.push(format!("    if ({class_match}) {{"));
            self.body.push(format!("      {object_matched} = 1;"));

            if !native_user_function_accepts_arg_count(&method.decl, args.len()) {
                let reason =
                    "callable object resolved to a generated public __invoke method but argument count is outside the generated frame arity/default/variadic subset";
                let branch_failure_cleanup =
                    format!("{}{}", c_cleanup_sequence(shared_cleanup), failure_cleanup);
                self.emit_method_dispatch_failure(
                    callee_handle,
                    "__invoke",
                    reason,
                    &branch_failure_cleanup,
                    "      ",
                );
                self.body.push("    }".to_string());
                self.body.push("  }".to_string());
                continue;
            }

            let argument_failure_cleanup =
                format!("{}{}", c_cleanup_sequence(shared_cleanup), failure_cleanup);
            let frame_arguments = self.materialize_declared_method_frame_arguments(
                &class.name,
                &method,
                Some(callee_handle),
                args,
                span,
                &argument_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
            let (mut call_args, branch_cleanup) = frame_arguments.into_call_args_and_cleanup();
            self.body.push(format!("      {status} = 0;"));
            call_args.push(format!("&{status}"));
            self.body.push(format!(
                "      {result} = {}({});",
                method.c_name,
                call_args.join(", ")
            ));
            let call_failure_cleanup = format!(
                "{}{}{}",
                c_cleanup_sequence(&branch_cleanup),
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let error_exit = self.native_error_exit(&call_failure_cleanup);
            self.body.push(format!(
                "      if ({status} != 1 || {result}.ptr == NULL) {{ {error_exit} }}"
            ));
            for cleanup in branch_cleanup {
                self.body.push(format!("      {cleanup}"));
            }
            self.body.push("    }".to_string());
            self.body.push("  }".to_string());
        }

        let object_failure_cleanup =
            format!("{}{}", c_cleanup_sequence(shared_cleanup), failure_cleanup);
        self.body.push(format!("  if (!{object_matched}) {{"));
        self.emit_method_dispatch_failure(
            callee_handle,
            "__invoke",
            "object receiver did not provide a supported generated public __invoke method",
            &object_failure_cleanup,
            "    ",
        );
        self.body.push("  }".to_string());
        self.body.push("}".to_string());

        Ok(())
    }

    fn materialize_descriptor_closure_argument(
        &mut self,
        callee_handle: &str,
        index: usize,
        arg: &Expr,
        shared_cleanup: &[String],
        failure_cleanup: &str,
        prior_cleanup: &[String],
    ) -> CompileResult<CNativeValueMaterialization> {
        let argument = self.next_native_name("closure_arg");
        self.body.push(format!(
            "  phpc_NativeClosureArgument {argument} = {{ (phpc_NativeValueHandle){{0}}, (phpc_NativeReferenceHandle){{0}}, 0 }};"
        ));
        let current_cleanup = vec![
            format!("phpc_native_value_free({argument}.value);"),
            format!("phpc_native_reference_free({argument}.reference);"),
        ];
        let current_cleanup_sequence = c_cleanup_sequence(&current_cleanup);
        self.body.push(format!(
            "  if (phpc_native_closure_value_param_is_by_reference({callee_handle}, {index})) {{"
        ));
        if self.runtime_dynamic_call_reference_argument_is_supported(arg) {
            let reference_failure_cleanup = format!(
                "{}{}{}{}",
                c_cleanup_sequence(prior_cleanup),
                current_cleanup_sequence,
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            let reference = self.materialize_call_reference_argument(
                arg,
                arg.span(),
                &reference_failure_cleanup,
                NativeCallCallee::DynamicExpression,
            )?;
            self.body
                .push(format!("    {argument}.reference = {};", reference.handle));
            self.body.push(format!(
                "    {argument}.flags = PHPC_NATIVE_CLOSURE_ARGUMENT_BY_REFERENCE;"
            ));
            let value = self.next_native_name("closure_reference_arg_value");
            self.body.push(format!(
                "    phpc_NativeValueHandle {value} = phpc_native_reference_value_clone({});",
                reference.handle
            ));
            let error_exit = self.native_error_exit(&reference_failure_cleanup);
            self.body
                .push(format!("    if ({value}.ptr == NULL) {{ {error_exit} }}"));
            self.body.push(format!("    {argument}.value = {value};"));
        } else {
            let reference_failure_cleanup = format!(
                "{}{}{}{}",
                c_cleanup_sequence(prior_cleanup),
                current_cleanup_sequence,
                c_cleanup_sequence(shared_cleanup),
                failure_cleanup
            );
            self.emit_descriptor_closure_reference_argument_failure(
                callee_handle,
                index,
                &reference_failure_cleanup,
                "    ",
            );
        }
        self.body.push("  } else {".to_string());
        let value_failure_cleanup = format!(
            "{}{}{}{}",
            c_cleanup_sequence(prior_cleanup),
            current_cleanup_sequence,
            c_cleanup_sequence(shared_cleanup),
            failure_cleanup
        );
        let value = self.materialize_native_value_result_operand(arg, &value_failure_cleanup)?;
        self.body
            .push(format!("    {argument}.value = {};", value.handle));
        self.body
            .extend(native_value_aux_cleanup_after_consuming_handle(&value));
        self.body.push("  }".to_string());

        Ok(CNativeValueMaterialization {
            handle: argument,
            cleanup_after_use: current_cleanup,
        })
    }

    fn emit_descriptor_closure_reference_argument_failure(
        &mut self,
        callee_handle: &str,
        index: usize,
        failure_cleanup: &str,
        indent: &str,
    ) {
        self.uses_native_closure_helpers = true;

        let diagnostic = self.next_native_name("closure_reference_arg_diagnostic");
        self.body.push(format!(
            "{indent}phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"
        ));
        self.body.push(format!(
            "{indent}phpc_native_closure_reference_argument_failure_with_diagnostic({callee_handle}, {index}, &{diagnostic});"
        ));
        let error_exit = self.native_error_exit(failure_cleanup);
        self.body.push(format!(
            "{indent}if ({diagnostic}.ptr != NULL) {{ phpc_native_diagnostic_report({diagnostic}); {diagnostic}.ptr = NULL; }} {error_exit}"
        ));
    }

    fn runtime_dynamic_call_reference_argument_is_supported(&self, arg: &Expr) -> bool {
        if self.source_call_reference_argument_is_supported(arg) {
            return true;
        }
        if self.reference_call_arrayaccess_argument_is_supported(arg) {
            return true;
        }
        if Self::request_superglobal_reference_argument_is_supported(arg) {
            return true;
        }

        if let Expr::Variable(name, _) = arg {
            if matches!(
                self.variables.get(name),
                Some(CValue::NativeReferenceHandle(_))
            ) {
                return true;
            }
        }

        self.c_reference_path_for_expr(arg).is_some_and(|path| {
            !is_request_superglobal_name(path.name)
                && !is_globals_superglobal_name(path.name)
                && (!path.append || !path.keys.is_empty())
        })
    }

    fn runtime_dynamic_call_reference_argument_needs_symbol_table(&self, arg: &Expr) -> bool {
        if Self::request_superglobal_reference_argument_is_supported(arg) {
            return false;
        }

        if let Expr::Variable(name, _) = arg {
            if matches!(
                self.variables.get(name),
                Some(CValue::NativeReferenceHandle(_))
            ) {
                return false;
            }
        }

        self.runtime_dynamic_call_reference_argument_is_supported(arg)
    }

    fn source_call_reference_argument_is_supported(&self, arg: &Expr) -> bool {
        match arg {
            Expr::Call { name, args, .. } => self
                .direct_call_registered_user_function(name)
                .is_some_and(|function| {
                    function.decl.returns_by_reference
                        && native_user_function_accepts_arg_count(&function.decl, args.len())
                }),
            Expr::DynamicCall { callee, args, .. } => self
                .source_call_reference_signature_for_dynamic_call(callee, args)
                .is_some(),
            Expr::MethodCall {
                target,
                method,
                args,
                ..
            } => self
                .receiver_method_source_call_reference_signature_contract_for_args(
                    target, method, args,
                )
                .is_some(),
            Expr::StaticMethodCall {
                class_name,
                method,
                args,
                ..
            } => self
                .static_method_source_call_reference_signature_contract_for_args(
                    class_name, method, args,
                )
                .is_some(),
            Expr::LateStaticMethodCall { method, args, .. } => self
                .late_static_method_source_call_reference_signature_contract_for_args(method, args)
                .is_some(),
            Expr::New {
                class_name, args, ..
            } => self
                .declared_constructor_reference_result_candidate(class_name, args.len())
                .is_some(),
            _ => false,
        }
    }

    fn declared_constructor_reference_result_candidate(
        &self,
        class_name: &NewClassName,
        arg_count: usize,
    ) -> Option<(CDeclaredClass, CDeclaredClassMethod)> {
        let NewClassName::Named(name) = class_name else {
            return None;
        };
        let key = Self::declared_class_key(name);
        if self.declared_class_requires_destructor_observable_cleanup_boundary(&key) {
            return None;
        }
        let class = self.declared_classes.get(&key)?.clone();
        let (_, constructor) = self.declared_class_constructor_for_instantiation(&class)?;
        native_user_function_accepts_arg_count(&constructor.decl, arg_count)
            .then_some((class, constructor))
    }

    fn receiver_method_source_call_reference_signature_contract(
        &self,
        target: &Expr,
        method_name: &str,
        arg_count: usize,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let caller_scope = self.active_declared_class_name.as_deref();
        let access_context = Self::current_declared_class_access_context(
            caller_scope,
            NativeSourceCallAccessContext::ObjectReceiver,
        );
        let contract = self.receiver_method_source_call_signature_contract(
            target,
            method_name,
            arg_count,
            access_context,
        )?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn receiver_method_source_call_reference_signature_contract_for_args(
        &self,
        target: &Expr,
        method_name: &str,
        args: &[Expr],
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let caller_scope = self.active_declared_class_name.as_deref();
        let access_context = Self::current_declared_class_access_context(
            caller_scope,
            NativeSourceCallAccessContext::ObjectReceiver,
        );
        let contract = self.receiver_method_source_call_signature_contract_for_args(
            target,
            method_name,
            args,
            access_context,
        )?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn static_method_source_call_reference_signature_contract(
        &self,
        class_name: &str,
        method_name: &str,
        arg_count: usize,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let contract = self.static_method_source_call_signature_contract(
            class_name,
            method_name,
            arg_count,
            NativeSourceCallAccessContext::Static,
        )?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn static_method_source_call_reference_signature_contract_for_args(
        &self,
        class_name: &str,
        method_name: &str,
        args: &[Expr],
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let contract = self.static_method_source_call_signature_contract_for_args(
            class_name,
            method_name,
            args,
            NativeSourceCallAccessContext::Static,
        )?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn late_static_method_source_call_reference_signature_contract(
        &self,
        method_name: &str,
        arg_count: usize,
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let contract =
            self.late_static_method_source_call_signature_contract(method_name, arg_count)?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn late_static_method_source_call_reference_signature_contract_for_args(
        &self,
        method_name: &str,
        args: &[Expr],
    ) -> Option<NativeMethodStaticSignatureFallbackContract> {
        let contract =
            self.late_static_method_source_call_signature_contract_for_args(method_name, args)?;
        contract
            .signature()
            .is_some_and(|signature| signature.returns_by_reference)
            .then_some(contract)
    }

    fn source_call_reference_signature_for_dynamic_call(
        &self,
        callee: &Expr,
        args: &[Expr],
    ) -> Option<Option<CScopedCallableStringSignature>> {
        let scoped_signature = self.callable_string_signature_for_expr(callee, args.len());
        if scoped_signature
            .as_ref()
            .is_some_and(|signature| signature.returns_by_reference)
        {
            return Some(scoped_signature);
        }

        let identities = self.native_callable_identities_for_expr(callee)?;
        let mut saw_identity = false;
        for identity in identities {
            let summary =
                self.native_callable_return_summary_for_identity(&identity, args.len())?;
            if summary.result_kind != CNativeCallableResultKind::Reference {
                return None;
            }
            saw_identity = true;
        }

        saw_identity.then_some(scoped_signature)
    }

    fn try_materialize_source_call_reference_argument(
        &mut self,
        expr: &Expr,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeReferenceMaterialization>> {
        match expr {
            Expr::Call { name, args, span } => {
                let Some(function) = self.direct_call_registered_user_function(name).cloned()
                else {
                    return Ok(None);
                };
                if !function.decl.returns_by_reference {
                    return Ok(None);
                }
                self.materialize_direct_user_function_reference_call(
                    &function,
                    args,
                    *span,
                    failure_cleanup,
                    NativeCallCallee::DirectNamed,
                )
                .map(Some)
            }
            Expr::DynamicCall { callee, args, span } => self
                .try_materialize_dynamic_source_call_reference_argument(
                    callee,
                    args,
                    *span,
                    failure_cleanup,
                ),
            Expr::MethodCall {
                target,
                method,
                args,
                span,
            } => self.try_materialize_receiver_method_source_call_reference_argument(
                target,
                method,
                args,
                *span,
                failure_cleanup,
            ),
            Expr::StaticMethodCall {
                class_name,
                method,
                args,
                span,
            } => self.try_materialize_static_method_source_call_reference_argument(
                class_name,
                method,
                args,
                *span,
                failure_cleanup,
            ),
            Expr::LateStaticMethodCall { method, args, span } => self
                .try_materialize_late_static_method_source_call_reference_argument(
                    method,
                    args,
                    *span,
                    failure_cleanup,
                ),
            Expr::New {
                class_name,
                args,
                span,
            } => self.try_materialize_constructor_source_call_reference_argument(
                class_name,
                args,
                *span,
                failure_cleanup,
            ),
            _ => Ok(None),
        }
    }

    fn try_materialize_constructor_source_call_reference_argument(
        &mut self,
        class_name: &NewClassName,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeReferenceMaterialization>> {
        let Some((class, constructor)) =
            self.declared_constructor_reference_result_candidate(class_name, args.len())
        else {
            return Ok(None);
        };

        let receiver =
            self.materialize_declared_class_instantiation(class.clone(), failure_cleanup)?;
        self.materialize_declared_class_constructor_source_call_reference(
            &class.name,
            &constructor,
            receiver,
            args,
            span,
            failure_cleanup,
        )
        .map(Some)
    }

    fn try_materialize_dynamic_source_call_reference_argument(
        &mut self,
        callee: &Expr,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeReferenceMaterialization>> {
        let Some(scoped_signature) =
            self.source_call_reference_signature_for_dynamic_call(callee, args)
        else {
            return Ok(None);
        };

        self.uses_native_string_helpers = true;
        self.uses_native_callable_helpers = true;
        self.uses_native_reference_helpers = true;

        let callee_value = self.emit_expr(callee)?;
        let descriptor_closure_only =
            self.cvalue_has_only_descriptor_closure_callable_identities(&callee_value);
        let descriptor_closure_argument_plan = if descriptor_closure_only {
            self.descriptor_closure_source_call_argument_plan_for_cvalue(&callee_value)
        } else {
            None
        };
        let callee = self.materialize_native_array_c_value_handle(callee_value, span)?;
        let callee_cleanup = c_cleanup_sequence(&callee.cleanup_after_use);

        if descriptor_closure_only {
            return self
                .materialize_descriptor_closure_reference_source_call(
                    callee,
                    args,
                    span,
                    failure_cleanup,
                    scoped_signature.as_ref(),
                    descriptor_closure_argument_plan.as_ref(),
                )
                .map(Some);
        }

        let table_failure_cleanup = format!("{callee_cleanup}{failure_cleanup}");
        let table = self.ensure_native_callable_table(&table_failure_cleanup);
        if self
            .user_functions
            .values()
            .any(|function| function.frame_environment.root_symbols)
        {
            let symbol_table_failure_cleanup = format!("{callee_cleanup}{failure_cleanup}");
            let root_symbols =
                self.ensure_globals_symbol_table(&symbol_table_failure_cleanup, span)?;
            self.body
                .push(format!("phpc_user_callable_root_symbols = {root_symbols};"));
        }
        if self
            .user_functions
            .values()
            .any(|function| function.frame_environment.request_state)
        {
            let request_state = self.ensure_native_request_state_handle();
            self.body.push(format!(
                "phpc_user_callable_request_state = {request_state};"
            ));
        }

        let lookup_diagnostic = self.next_native_name("source_reference_lookup_diagnostic");
        let callable = self.next_native_name("source_reference_callable");
        self.body.push(format!(
            "phpc_NativeDiagnosticHandle {lookup_diagnostic} = {{0}};"
        ));
        self.body.push(format!(
            "phpc_NativeCallableValueHandle {callable} = phpc_native_callable_lookup_value_or_closure_with_context_diagnostic({table}, {}, (phpc_NativeStringHandle){{0}}, &{lookup_diagnostic});",
            callee.handle
        ));
        self.emit_report_native_diagnostic(&lookup_diagnostic);
        let lookup_error_exit =
            self.native_error_exit(&format!("{callee_cleanup}{failure_cleanup}"));
        self.body.push(format!(
            "if ({callable}.ptr == NULL) {{ {lookup_error_exit} }}"
        ));

        let callable_failure_cleanup = format!(
            "phpc_native_callable_value_free({callable}); {callee_cleanup}{failure_cleanup}"
        );
        let call_arguments = self.emit_native_source_call_arguments_handle(
            "source_reference_args",
            args,
            span,
            &callable_failure_cleanup,
            NativeCallCallee::DynamicExpression,
            scoped_signature.as_ref(),
            false,
        )?;

        let invoke_diagnostic = self.next_native_name("source_reference_invoke_diagnostic");
        self.body.push(format!(
            "phpc_NativeDiagnosticHandle {invoke_diagnostic} = {{0}};"
        ));
        let carrier = self.native_source_call_carrier(
            NativeInvokeResultTarget::CallableValueHandle,
            NativeSourceCallResultConsumer::Reference,
            span,
        )?;
        let emitted_reference = self
            .emit_native_source_call_carrier_invocation(
                carrier,
                &[callable.clone()],
                &call_arguments,
                &invoke_diagnostic,
                "source_reference_result",
            )
            .expect("reference source-call carrier must produce a reference handle");
        let reference = self.next_native_name("source_reference_result");
        self.body.push(format!(
            "phpc_NativeReferenceHandle {reference} = {emitted_reference};"
        ));
        self.body
            .push(format!("phpc_native_callable_value_free({callable});"));
        self.emit_report_native_diagnostic(&invoke_diagnostic);
        let invoke_error_exit =
            self.native_error_exit(&format!("{callee_cleanup}{failure_cleanup}"));
        self.body.push(format!(
            "if ({reference}.ptr == NULL) {{ {invoke_error_exit} }}"
        ));
        self.body.extend(callee.cleanup_after_use);

        Ok(Some(CNativeReferenceMaterialization {
            handle: reference.clone(),
            cleanup_after_use: vec![format!("phpc_native_reference_free({reference});")],
        }))
    }

    fn try_materialize_receiver_method_source_call_reference_argument(
        &mut self,
        target: &Expr,
        method_name: &str,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeReferenceMaterialization>> {
        let Some(signature_contract) = self
            .receiver_method_source_call_reference_signature_contract_for_args(
                target,
                method_name,
                args,
            )
        else {
            return Ok(None);
        };

        self.uses_native_reference_helpers = true;
        let receiver = self.materialize_native_value_result_operand(target, failure_cleanup)?;
        let receiver_cleanup = c_cleanup_sequence(&receiver.cleanup_after_use);
        let method = self.materialize_native_array_c_value_handle(
            CValue::String(method_name.to_string()),
            span,
        )?;
        let method_cleanup = c_cleanup_sequence(&method.cleanup_after_use);
        let target_failure_cleanup = format!("{method_cleanup}{receiver_cleanup}{failure_cleanup}");
        let target = self.emit_native_receiver_method_source_call_target_operands(
            receiver,
            method,
            NativeSourceCallAccessContext::ObjectReceiver,
            &target_failure_cleanup,
        );
        let binding = self.emit_native_method_static_source_call_binding_operands(
            "source_reference_receiver_args",
            target,
            args,
            span,
            failure_cleanup,
            &signature_contract,
        )?;

        let invoke_diagnostic = self.next_native_name("source_reference_receiver_diagnostic");
        self.body.push(format!(
            "phpc_NativeDiagnosticHandle {invoke_diagnostic} = {{0}};"
        ));
        let carrier = self.native_source_call_carrier(
            NativeInvokeResultTarget::ReceiverMethodLookupWithAccessContext,
            NativeSourceCallResultConsumer::Reference,
            span,
        )?;
        let emitted_reference = self
            .emit_native_source_call_carrier_invocation(
                carrier,
                &binding.target.args,
                &binding.arguments,
                &invoke_diagnostic,
                "source_reference_receiver_result",
            )
            .expect(
                "receiver-method reference source-call carrier must produce a reference handle",
            );
        self.body.extend(binding.target.cleanup_after_invocation);
        self.emit_report_native_diagnostic(&invoke_diagnostic);
        let error_exit = self.native_error_exit(failure_cleanup);
        self.body.push(format!(
            "if ({emitted_reference}.ptr == NULL) {{ {error_exit} }}"
        ));

        Ok(Some(CNativeReferenceMaterialization {
            handle: emitted_reference.clone(),
            cleanup_after_use: vec![format!("phpc_native_reference_free({emitted_reference});")],
        }))
    }

