    fn materialize_native_value_array_query_operation_expr(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<CNativeValueMaterialization> {
        match builtin {
            NativeValueArrayQueryBuiltin::KeysMatching => {
                if !(2..=3).contains(&args.len()) {
                    return Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION));
                }
                self.materialize_native_value_array_query_subject_operand_expr(
                    builtin,
                    &args[0],
                    &args[1],
                    args.get(2),
                    span,
                    failure_cleanup,
                )
            }
            NativeValueArrayQueryBuiltin::Contains | NativeValueArrayQueryBuiltin::Search => {
                if !(2..=3).contains(&args.len()) {
                    return Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION));
                }
                self.materialize_native_value_array_query_operand_subject_expr(
                    builtin,
                    &args[0],
                    &args[1],
                    args.get(2),
                    span,
                    failure_cleanup,
                )
            }
            NativeValueArrayQueryBuiltin::Flip
            | NativeValueArrayQueryBuiltin::CountValues
            | NativeValueArrayQueryBuiltin::Sum
            | NativeValueArrayQueryBuiltin::Product
            | NativeValueArrayQueryBuiltin::Count => {
                let [subject] = args else {
                    return Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION));
                };
                let subject =
                    self.materialize_native_value_result_operand(subject, failure_cleanup)?;
                let cleanup_after_use = subject.cleanup_after_use.clone();
                Ok(self.emit_native_value_array_query_operation_handle(
                    builtin,
                    subject,
                    None,
                    "0".to_string(),
                    cleanup_after_use,
                    failure_cleanup,
                ))
            }
            NativeValueArrayQueryBuiltin::FillKeys | NativeValueArrayQueryBuiltin::Combine => {
                let [subject, operand] = args else {
                    return Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION));
                };
                self.materialize_native_value_array_query_subject_operand_expr(
                    builtin,
                    subject,
                    operand,
                    None,
                    span,
                    failure_cleanup,
                )
            }
            NativeValueArrayQueryBuiltin::ChangeKeyCase => match args {
                [subject] => {
                    let subject =
                        self.materialize_native_value_result_operand(subject, failure_cleanup)?;
                    let cleanup_after_use = subject.cleanup_after_use.clone();
                    Ok(self.emit_native_value_array_query_operation_handle(
                        builtin,
                        subject,
                        None,
                        "0".to_string(),
                        cleanup_after_use,
                        failure_cleanup,
                    ))
                }
                [subject, operand] => self
                    .materialize_native_value_array_query_subject_operand_expr(
                        builtin,
                        subject,
                        operand,
                        None,
                        span,
                        failure_cleanup,
                    ),
                _ => Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION)),
            },
            NativeValueArrayQueryBuiltin::Column => match args {
                [subject, column_key] => self
                    .materialize_native_value_array_query_subject_operands_expr(
                        builtin,
                        subject,
                        &[column_key],
                        "0".to_string(),
                        failure_cleanup,
                    ),
                [subject, column_key, index_key] => self
                    .materialize_native_value_array_query_subject_operands_expr(
                        builtin,
                        subject,
                        &[column_key, index_key],
                        "0".to_string(),
                        failure_cleanup,
                    ),
                _ => Err(self.unsupported(span, ASSEMBLY_ARRAY_REJECTION)),
            },
        }
    }

    fn materialize_native_value_array_query_subject_operands_expr(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        subject_expr: &Expr,
        operand_exprs: &[&Expr],
        flags: String,
        failure_cleanup: &str,
    ) -> CompileResult<CNativeValueMaterialization> {
        let subject =
            self.materialize_native_value_result_operand(subject_expr, failure_cleanup)?;
        let mut cleanup_after_use = subject.cleanup_after_use.clone();
        let mut operands = Vec::new();
        for operand_expr in operand_exprs {
            let operand_failure_cleanup = format!(
                "{}{}",
                c_cleanup_sequence(&cleanup_after_use),
                failure_cleanup
            );
            let operand = self
                .materialize_native_value_result_operand(operand_expr, &operand_failure_cleanup)?;
            let mut next_cleanup = operand.cleanup_after_use.clone();
            next_cleanup.extend(cleanup_after_use);
            cleanup_after_use = next_cleanup;
            operands.push(operand);
        }

        Ok(
            self.emit_native_value_array_query_operation_handle_with_operands(
                builtin,
                subject,
                operands,
                flags,
                cleanup_after_use,
                failure_cleanup,
            ),
        )
    }

    fn materialize_native_value_array_query_subject_operand_expr(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        subject_expr: &Expr,
        operand_expr: &Expr,
        strict_expr: Option<&Expr>,
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<CNativeValueMaterialization> {
        let subject =
            self.materialize_native_value_result_operand(subject_expr, failure_cleanup)?;
        let operand_failure_cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&subject.cleanup_after_use),
            failure_cleanup
        );
        let operand =
            self.materialize_native_value_result_operand(operand_expr, &operand_failure_cleanup)?;
        let mut cleanup_after_use = operand.cleanup_after_use.clone();
        cleanup_after_use.extend(subject.cleanup_after_use.clone());
        let flags = self.emit_native_value_array_query_flags(strict_expr, span)?;
        Ok(self.emit_native_value_array_query_operation_handle(
            builtin,
            subject,
            Some(operand),
            flags,
            cleanup_after_use,
            failure_cleanup,
        ))
    }

    fn materialize_native_value_array_query_operand_subject_expr(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        operand_expr: &Expr,
        subject_expr: &Expr,
        strict_expr: Option<&Expr>,
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<CNativeValueMaterialization> {
        let operand =
            self.materialize_native_value_result_operand(operand_expr, failure_cleanup)?;
        let subject_failure_cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&operand.cleanup_after_use),
            failure_cleanup
        );
        let subject =
            self.materialize_native_value_result_operand(subject_expr, &subject_failure_cleanup)?;
        let mut cleanup_after_use = subject.cleanup_after_use.clone();
        cleanup_after_use.extend(operand.cleanup_after_use.clone());
        let flags = self.emit_native_value_array_query_flags(strict_expr, span)?;
        Ok(self.emit_native_value_array_query_operation_handle(
            builtin,
            subject,
            Some(operand),
            flags,
            cleanup_after_use,
            failure_cleanup,
        ))
    }

    fn emit_native_value_array_query_flags(
        &mut self,
        strict_expr: Option<&Expr>,
        span: Span,
    ) -> CompileResult<String> {
        let Some(strict_expr) = strict_expr else {
            return Ok("0".to_string());
        };

        match self.emit_expr(strict_expr)? {
            CValue::Bool(true) => Ok("PHPC_NATIVE_ARRAY_QUERY_STRICT".to_string()),
            CValue::Bool(false) => Ok("0".to_string()),
            CValue::BoolExpr(value) => {
                Ok(format!("(({value}) ? PHPC_NATIVE_ARRAY_QUERY_STRICT : 0)"))
            }
            CValue::ComparisonDecision(decision) => Ok(format!(
                "({} ? PHPC_NATIVE_ARRAY_QUERY_STRICT : 0)",
                c_comparison_decision_bool_expr(&decision)
            )),
            _ => Err(self.unsupported(span, ASSEMBLY_FUNCTION_CALL_REJECTION)),
        }
    }

    fn emit_native_array_key_exists_call(
        &mut self,
        args: &[Expr],
        span: Span,
        failure_cleanup: &str,
    ) -> CompileResult<CValue> {
        let [key_expr, subject_expr] = args else {
            return Err(
                self.unsupported_direct_call(span, NativeCallBlocker::ArgumentEvaluationCleanup)
            );
        };

        let key = self.materialize_native_value_result_operand(key_expr, failure_cleanup)?;
        let subject_failure_cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&key.cleanup_after_use),
            failure_cleanup
        );
        let subject = self.materialize_native_value_reference_slot_operand(
            subject_expr,
            &subject_failure_cleanup,
        )?;
        let mut cleanup_after_use = subject.cleanup_after_use.clone();
        cleanup_after_use.extend(key.cleanup_after_use.clone());

        Ok(CValue::BoolExpr(
            self.emit_native_array_key_exists_value_slot(
                key,
                subject,
                cleanup_after_use,
                failure_cleanup,
            ),
        ))
    }

    fn emit_native_array_key_exists_value_slot(
        &mut self,
        key: CNativeValueMaterialization,
        subject: CNativeValueReferenceSlot,
        cleanup_after_use: Vec<String>,
        failure_cleanup: &str,
    ) -> String {
        self.uses_native_array_helpers = true;
        self.uses_native_reference_helpers |= subject.is_reference;

        let result = self.next_native_name("native_array_key_exists");
        let diagnostic = self.next_native_name("array_key_exists_diagnostic");
        let helper = if subject.is_reference {
            "phpc_native_reference_array_key_exists_value_with_diagnostic"
        } else {
            "phpc_native_value_array_key_exists_value_with_diagnostic"
        };
        let subject_arg = if subject.is_reference {
            subject.reference_handle.clone()
        } else {
            subject.value_handle.clone()
        };
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "_Bool {result} = {helper}({}, {subject_arg}, &{diagnostic});",
            key.handle
        ));
        let report_call = c_diagnostic_report_call(&diagnostic);
        let cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&cleanup_after_use),
            failure_cleanup
        );
        let error_exit = self.native_error_exit(&cleanup);
        self.body.push(format!(
            "if ({diagnostic}.ptr != NULL) {{ {report_call} {diagnostic}.ptr = NULL; {error_exit} }}"
        ));
        self.body.extend(cleanup_after_use);
        result
    }

    fn emit_native_value_array_query_operation_handle(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        subject: CNativeValueMaterialization,
        operand: Option<CNativeValueMaterialization>,
        flags: String,
        cleanup_after_use: Vec<String>,
        failure_cleanup: &str,
    ) -> CNativeValueMaterialization {
        self.uses_native_string_helpers = true;
        self.uses_native_array_helpers = true;
        self.uses_native_array_lvalue_helpers = true;

        let subject_handle = subject.handle.clone();
        let operand_handle = operand
            .as_ref()
            .map(|operand| operand.handle.clone())
            .unwrap_or_else(|| "(phpc_NativeValueHandle){0}".to_string());
        let operation_tag = builtin.operation_tag();
        let diagnostic = self.next_native_name("array_query_diagnostic");
        let result = self.next_native_name("native_value_array_query");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "phpc_NativeValueHandle {result} = phpc_native_value_array_query_operation_with_diagnostic({subject_handle}, {operand_handle}, {flags}, {operation_tag}, &{diagnostic});"
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        let cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&cleanup_after_use),
            failure_cleanup
        );
        let error_exit = self.native_error_exit(&cleanup);
        self.body
            .push(format!("if ({result}.ptr == NULL) {{ {error_exit} }}"));
        self.body
            .push(format!("phpc_native_diagnostic_free({diagnostic});"));
        self.body.extend(cleanup_after_use);

        CNativeValueMaterialization {
            handle: result.clone(),
            cleanup_after_use: vec![format!("phpc_native_value_free({result});")],
        }
    }

    fn emit_native_value_array_query_operation_handle_with_operands(
        &mut self,
        builtin: NativeValueArrayQueryBuiltin,
        subject: CNativeValueMaterialization,
        operands: Vec<CNativeValueMaterialization>,
        flags: String,
        cleanup_after_use: Vec<String>,
        failure_cleanup: &str,
    ) -> CNativeValueMaterialization {
        self.uses_native_string_helpers = true;
        self.uses_native_array_helpers = true;
        self.uses_native_array_lvalue_helpers = true;

        let subject_handle = subject.handle.clone();
        let operand_array = if operands.is_empty() {
            "NULL".to_string()
        } else {
            let operand_array = self.next_native_name("array_query_operands");
            let handles = operands
                .iter()
                .map(|operand| operand.handle.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            self.body.push(format!(
                "phpc_NativeValueHandle {operand_array}[] = {{ {handles} }};"
            ));
            operand_array
        };
        let operation_tag = builtin.operation_tag();
        let diagnostic = self.next_native_name("array_query_diagnostic");
        let result = self.next_native_name("native_value_array_query");
        self.body
            .push(format!("phpc_NativeDiagnosticHandle {diagnostic} = {{0}};"));
        self.body.push(format!(
            "phpc_NativeValueHandle {result} = phpc_native_value_array_query_operation_with_operands_and_diagnostic({subject_handle}, {operand_array}, {}, {flags}, {operation_tag}, &{diagnostic});",
            operands.len()
        ));
        self.emit_report_native_diagnostic(&diagnostic);
        let cleanup = format!(
            "{}{}",
            c_cleanup_sequence(&cleanup_after_use),
            failure_cleanup
        );
        let error_exit = self.native_error_exit(&cleanup);
        self.body
            .push(format!("if ({result}.ptr == NULL) {{ {error_exit} }}"));
        self.body
            .push(format!("phpc_native_diagnostic_free({diagnostic});"));
        self.body.extend(cleanup_after_use);

        CNativeValueMaterialization {
            handle: result.clone(),
            cleanup_after_use: vec![format!("phpc_native_value_free({result});")],
        }
    }

    fn emit_native_array_foreach_cursor_value(
        &mut self,
        iterable: &str,
        index: &str,
        cursor: &str,
    ) -> String {
        let helper = match cursor {
            "key" => "phpc_native_array_foreach_iterable_key_result",
            _ => "phpc_native_array_foreach_iterable_value_result",
        };
        let result = self.next_native_name(&format!("array_foreach_{cursor}_result"));
        let cursor_value = self.next_native_name(&format!("array_foreach_{cursor}_value"));
        self.body.push(format!(
            "phpc_NativeArrayLvalueResult {result} = {helper}({iterable}, {index});"
        ));
        self.emit_native_array_lvalue_result_check(&result, "");
        self.body.push(format!(
            "phpc_NativeValueHandle {cursor_value} = {result}.value;"
        ));
        self.body
            .push(format!("{result}.value = (phpc_NativeValueHandle){{0}};"));
        self.body
            .push(format!("phpc_native_array_lvalue_result_free({result});"));
        cursor_value
    }

    fn native_foreach_body_may_mutate_storage(&self, body: &[Stmt]) -> bool {
        body.iter()
            .any(|statement| self.native_foreach_stmt_may_mutate_storage(statement))
    }

    fn native_by_reference_foreach_body_supported(&self, value: &str, body: &[Stmt]) -> bool {
        body.iter().all(|statement| match statement {
            Stmt::Echo { exprs, .. } => exprs
                .iter()
                .all(|expr| !native_foreach_expr_may_mutate_storage(expr)),
            Stmt::Print { expr, .. } | Stmt::Expr { expr, .. } => {
                !native_foreach_expr_may_mutate_storage(expr)
            }
            Stmt::Assign { target, expr, .. } => {
                (matches!(target, AssignTarget::Variable { name, .. } if name == value)
                    || native_by_reference_foreach_value_array_lvalue_target_supported(
                        value, target,
                    ))
                    && !native_foreach_expr_may_mutate_storage(expr)
            }
            _ => false,
        })
    }

    fn native_foreach_stmt_may_mutate_storage(&self, stmt: &Stmt) -> bool {
        match stmt {
            Stmt::Echo { exprs, .. } => exprs.iter().any(native_foreach_expr_may_mutate_storage),
            Stmt::Print { expr, .. } | Stmt::Expr { expr, .. } => {
                native_foreach_expr_may_mutate_storage(expr)
            }
            Stmt::UnsetArrayIndex { name, index, .. } => {
                !self.native_foreach_array_unset_root_has_prior_storage(name)
                    || native_foreach_expr_may_mutate_storage(index)
            }
            Stmt::UnsetNestedArrayIndex { name, indices, .. } => {
                !self.native_foreach_array_unset_root_has_prior_storage(name)
                    || indices.iter().any(native_foreach_expr_may_mutate_storage)
            }
            Stmt::UnsetMany { targets, .. } => targets
                .iter()
                .any(|target| self.native_foreach_unset_target_may_mutate_storage(target)),
            _ => true,
        }
    }

    fn native_foreach_unset_target_may_mutate_storage(&self, target: &UnsetTarget) -> bool {
        match target {
            UnsetTarget::ArrayIndex { name, index, .. } => {
                !self.native_foreach_array_unset_root_has_prior_storage(name)
                    || native_foreach_expr_may_mutate_storage(index)
            }
            UnsetTarget::NestedArrayIndex { name, indices, .. } => {
                !self.native_foreach_array_unset_root_has_prior_storage(name)
                    || indices.iter().any(native_foreach_expr_may_mutate_storage)
            }
            _ => true,
        }
    }

    fn native_foreach_array_unset_root_has_prior_storage(&self, name: &str) -> bool {
        match self.variables.get(name) {
            Some(CValue::String(_) | CValue::StringExpr(_)) | None => false,
            Some(_) => true,
        }
    }

    fn emit_array_lvalue_write_materialized_for_reference(
        &mut self,
        reference: &str,
        path: CNativeArrayLvaluePath,
        replacement: CNativeValueMaterialization,
        result_prefix: &str,
    ) -> CompileResult<()> {
        self.uses_native_string_helpers = true;
        self.uses_native_array_helpers = true;
        self.uses_native_array_lvalue_helpers = true;

        let owner = self.next_native_name("array_lvalue_owner");
        let result = self.next_native_name(result_prefix);
        self.body.push(format!(
            "phpc_NativeArrayLvalueOwner {owner} = phpc_native_array_lvalue_owner_reference_slot({reference});"
        ));
        self.body.push(format!(
            "phpc_NativeArrayLvalueResult {result} = phpc_native_array_lvalue_owner_value_operation_result({owner}, {}, {}, PHPC_NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE, 0, 0, 0, {});",
            path.path, path.len, replacement.handle
        ));
        let path_cleanup = c_cleanup_sequence(&path.cleanup_after_use);
        let cleanup = format!(
            "{}phpc_native_reference_free({reference}); {path_cleanup}",
            c_cleanup_sequence(&replacement.cleanup_after_use)
        );
        self.emit_native_array_lvalue_result_check(&result, &cleanup);
        self.body
            .push(format!("phpc_native_array_lvalue_result_free({result});"));
        self.body
            .push(format!("phpc_native_reference_free({reference});"));
        self.body.extend(replacement.cleanup_after_use);
        self.body.extend(path.cleanup_after_use);
        Ok(())
    }

    fn emit_array_lvalue_write_materialized_for_owner(
        &mut self,
        target: CNativeArrayLvalueTargetMaterialization,
        replacement: CNativeValueMaterialization,
        result_prefix: &str,
        failure_cleanup: &str,
    ) -> CompileResult<()> {
        self.uses_native_string_helpers = true;
        self.uses_native_array_helpers = true;
        self.uses_native_array_lvalue_helpers = true;

        let CNativeArrayLvalueTargetMaterialization { owner, path } = target;
        let owner_cleanup = c_cleanup_sequence(&owner.cleanup_after_use);
        let path_cleanup = c_cleanup_sequence(&path.cleanup_after_use);
        let target_cleanup = format!("{owner_cleanup}{path_cleanup}");
        let result = self.next_native_name(result_prefix);
        self.body.push(format!(
            "phpc_NativeArrayLvalueResult {result} = phpc_native_array_lvalue_owner_value_operation_result({}, {}, {}, PHPC_NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE, 0, 0, 0, {});",
            owner.owner, path.path, path.len, replacement.handle
        ));
        self.emit_native_array_lvalue_result_check(
            &result,
            &format!(
                "{}{target_cleanup}{failure_cleanup}",
                c_cleanup_sequence(&replacement.cleanup_after_use)
            ),
        );
        self.body
            .push(format!("phpc_native_array_lvalue_result_free({result});"));
        self.invalidate_native_array_lvalue_owner_write_facts(&owner);
        self.body.extend(replacement.cleanup_after_use);
        self.body.extend(owner.cleanup_after_use);
        self.body.extend(path.cleanup_after_use);
        Ok(())
    }

    fn emit_array_lvalue_assignment_for_target(
        &mut self,
        target: &AssignTarget,
        replacement_expr: &Expr,
        failure_cleanup: &str,
    ) -> CompileResult<bool> {
        let Some(target) =
            self.materialize_native_array_lvalue_assignment_target(target, failure_cleanup)?
        else {
            return Ok(false);
        };
        let target_cleanup = target.cleanup_sequence();
        let replacement = self.materialize_native_value_result_operand(
            replacement_expr,
            &format!("{target_cleanup}{failure_cleanup}"),
        )?;
        self.emit_array_lvalue_write_materialized_for_owner(
            target,
            replacement,
            "array_lvalue_assign_result",
            failure_cleanup,
        )?;
        Ok(true)
    }

    fn materialize_native_array_lvalue_assignment_target(
        &mut self,
        target: &AssignTarget,
        failure_cleanup: &str,
    ) -> CompileResult<Option<CNativeArrayLvalueTargetMaterialization>> {
        let (source, path, span) = match target {
            AssignTarget::ArrayIndex { name, index, span } => {
                let Some(source) = self.native_array_lvalue_owner_source_for_name(name) else {
                    return Ok(None);
                };
                if matches!(&source, CNativeArrayLvalueOwnerSource::ArrayHandle { .. }) {
                    return Ok(None);
                }
                let path = if let Some(index) = index.as_ref() {
                    self.materialize_native_array_lvalue_key_path(&[index], *span, failure_cleanup)?
                } else {
                    self.materialize_native_array_lvalue_append_path(
                        &[],
                        &[],
                        *span,
                        failure_cleanup,
                    )?
                };
                (source, path, *span)
            }
            AssignTarget::NestedArrayIndex {
                name,
                indices,
                span,
            } => {
                let Some(source) = self.native_array_lvalue_owner_source_for_name(name) else {
                    return Ok(None);
                };
                if matches!(&source, CNativeArrayLvalueOwnerSource::ArrayHandle { .. }) {
                    return Ok(None);
                }
                let indices = indices.iter().collect::<Vec<_>>();
                let path = self.materialize_native_array_lvalue_key_path(
                    &indices,
                    *span,
                    failure_cleanup,
                )?;
                (source, path, *span)
            }
            AssignTarget::NestedArrayAppend {
                name,
                indices,
                suffix_indices,
                span,
            } => {
                let Some(source) = self.native_array_lvalue_owner_source_for_name(name) else {
                    return Ok(None);
                };
                if matches!(&source, CNativeArrayLvalueOwnerSource::ArrayHandle { .. }) {
                    return Ok(None);
                }
                let prefix_indices = indices.iter().collect::<Vec<_>>();
                let suffix_indices = suffix_indices.iter().collect::<Vec<_>>();
                let path = self.materialize_native_array_lvalue_append_path(
                    &prefix_indices,
                    &suffix_indices,
                    *span,
                    failure_cleanup,
                )?;
                (source, path, *span)
            }
            _ => return Ok(None),
        };

        let path_cleanup = c_cleanup_sequence(&path.cleanup_after_use);
        let owner = self.materialize_native_array_lvalue_owner(
            source,
            span,
            "array_lvalue_owner",
            &format!("{path_cleanup}{failure_cleanup}"),
        )?;
        Ok(Some(CNativeArrayLvalueTargetMaterialization {
            owner,
            path,
        }))
    }

    fn emit_symbol_table_array_lvalue_write_with_path(
        &mut self,
        name: &str,
        path: CNativeArrayLvaluePath,
        replacement_expr: &Expr,
        span: Span,
        result_prefix: &str,
    ) -> CompileResult<()> {
        let path_cleanup = c_cleanup_sequence(&path.cleanup_after_use);
        let reference =
            self.emit_symbol_table_root_reference_for_array_lvalue(name, span, &path_cleanup)?;
        let reference_cleanup = format!("phpc_native_reference_free({reference}); ");
        let replacement = self.materialize_native_value_result_operand(
            replacement_expr,
            &format!("{reference_cleanup}{path_cleanup}"),
        )?;
        self.emit_array_lvalue_write_materialized_for_reference(
            &reference,
            path,
            replacement,
            result_prefix,
        )
    }

