fn native_class_metadata_value_operation_tag(
    kind: NativeObjectMetadataCallKind,
) -> Option<&'static str> {
    match kind {
        NativeObjectMetadataCallKind::ParentClassValue => Some("0"),
        NativeObjectMetadataCallKind::ClassParentsValue => Some("1"),
        NativeObjectMetadataCallKind::DeclaredClassesValue => Some("2"),
        NativeObjectMetadataCallKind::ClassMethodsValue => Some("3"),
        NativeObjectMetadataCallKind::ClassVarsValue => Some("4"),
        NativeObjectMetadataCallKind::DeclaredInterfacesValue => Some("5"),
        NativeObjectMetadataCallKind::ClassImplementsValue => Some("6"),
        NativeObjectMetadataCallKind::DeclaredTraitsValue => Some("7"),
        NativeObjectMetadataCallKind::ClassUsesValue => Some("8"),
        _ => None,
    }
}

fn is_native_relationship_metadata_builtin(name: &str) -> bool {
    matches!(
        php_unqualified_name(name).to_ascii_lowercase().as_str(),
        "is_a" | "is_subclass_of"
    )
}

fn php_unqualified_name(name: &str) -> &str {
    name.rsplit('\\').next().unwrap_or(name)
}

fn exact_function_call_lookup_name(name: &str) -> &str {
    name.strip_prefix('\\').unwrap_or(name)
}

fn global_function_fallback_name(name: &str) -> Option<&str> {
    if name.starts_with('\\') {
        return None;
    }

    name.rsplit_once('\\').map(|(_, suffix)| suffix)
}

fn exact_imported_global_function_call_name(name: &str) -> Option<&str> {
    let lookup_name = name.strip_prefix('\\')?;
    (!lookup_name.contains('\\')).then_some(lookup_name)
}

fn runtime_callable_builtin_signature_for_name(name: &str) -> Option<CNativeBuiltinSignature> {
    let signature = native_builtin_signature_for_name(name)?;
    match signature.source_call_support {
        CNativeBuiltinSignatureSourceCallSupport::RuntimeCallableValue => Some(signature),
        CNativeBuiltinSignatureSourceCallSupport::Blocked(
            CNativeBuiltinSignatureBlocker::MissingRuntimeCallableFamily,
        ) if signature.canonical_name == "count" => Some(signature),
        CNativeBuiltinSignatureSourceCallSupport::Blocked(_) => None,
    }
}

fn exact_imported_runtime_builtin_signature(name: &str) -> Option<CNativeBuiltinSignature> {
    runtime_callable_builtin_signature_for_name(exact_imported_global_function_call_name(name)?)
}

fn is_exact_qualified_function_call_name(name: &str) -> bool {
    exact_function_call_lookup_name(name).contains('\\') && name.starts_with('\\')
}

fn is_builtin_class_name(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "exception"
            | "datemalformedintervalstringexception"
            | "dateinterval"
            | "pdo"
            | "pdostatement"
            | "directory"
            | "datetimezone"
            | "datetime"
            | "datetimeimmutable"
            | "reflectionclass"
            | "reflectionmethod"
    )
}

fn known_strings_have_uniform_function_exists_result(values: &KnownString) -> Option<bool> {
    let mut result = None;
    for value in values.values() {
        let current = is_native_known_function_name(exact_function_call_lookup_name(value));
        if let Some(previous) = result {
            if previous != current {
                return None;
            }
        } else {
            result = Some(current);
        }
    }
    result
}

fn literal_include_path_setting_for_codegen(expr: &Expr, source_dir: &Path) -> Option<String> {
    match expr {
        Expr::String(value, _) => Some(value.clone()),
        Expr::MagicDir { .. } => Some(source_dir.to_string_lossy().into_owned()),
        Expr::GlobalConstant { name, .. } if name.eq_ignore_ascii_case("PATH_SEPARATOR") => {
            let separator = if cfg!(windows) { ';' } else { ':' };
            Some(separator.to_string())
        }
        Expr::Binary {
            left,
            op: BinaryOp::Concat,
            right,
            ..
        } => {
            let mut value = literal_include_path_setting_for_codegen(left, source_dir)?;
            value.push_str(&literal_include_path_setting_for_codegen(
                right, source_dir,
            )?);
            Some(value)
        }
        _ => None,
    }
}

