    #[test]
    fn native_callable_return_summary_resolves_generated_functions_and_methods() {
        let program = crate::parse(concat!(
            "<?php\n",
            "class CallableSummaryProduct {}\n",
            "function make_summary_product() { return new CallableSummaryProduct(); }\n",
            "class CallableSummaryFactory {\n",
            "    public function make() { return new CallableSummaryProduct(); }\n",
            "    public static function stat() { return new CallableSummaryProduct(); }\n",
            "}\n",
        ))
        .unwrap();
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            uses_native_value_clone: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .unwrap();
        generator
            .register_top_level_user_functions(&program.statements)
            .unwrap();
        generator.emit_declared_class_method_definitions().unwrap();
        generator
            .emit_registered_user_function_definitions()
            .unwrap();

        let function_identity = CNativeCallableIdentity::GeneratedFunction {
            function_key: CGenerator::user_function_key("make_summary_product"),
        };
        let function_summary = generator
            .native_callable_return_summary_for_identity(&function_identity, 0)
            .expect("generated function should resolve to a return summary");
        assert_eq!(
            function_summary.result_kind,
            CNativeCallableResultKind::NativeValue
        );
        assert_native_object_fact_contains_class(
            function_summary.facts.clone(),
            "CallableSummaryProduct",
        );

        let instance_identities = generator
            .native_callable_identities_for_declared_method_candidates(
                generator.declared_class_method_candidates("make"),
                CNativeCallableDeclaredMethodStaticness::Instance,
            )
            .expect("instance method identities should resolve");
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_callable_identities(instance_identities, 0),
            "CallableSummaryProduct",
        );

        let static_identities = generator
            .native_callable_identities_for_declared_method_candidates(
                generator.declared_class_static_method_candidates("stat"),
                CNativeCallableDeclaredMethodStaticness::Static,
            )
            .expect("static method identities should resolve");
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_callable_identities(static_identities, 0),
            "CallableSummaryProduct",
        );

        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&Expr::Call {
                name: "make_summary_product".to_string(),
                args: vec![],
                span: span(1),
            }),
            "CallableSummaryProduct",
        );
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&Expr::MethodCall {
                target: Box::new(Expr::Variable("factory".to_string(), span(1))),
                method: "make".to_string(),
                args: vec![],
                span: span(1),
            }),
            "CallableSummaryProduct",
        );
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&Expr::StaticMethodCall {
                class_name: "CallableSummaryFactory".to_string(),
                method: "stat".to_string(),
                args: vec![],
                span: span(1),
            }),
            "CallableSummaryProduct",
        );
        assert!(
            generator
                .native_callable_return_summary_for_identity(&function_identity, 1)
                .is_none(),
            "arity-incompatible generated callables should not publish return facts"
        );
    }

    #[test]
    fn external_declared_method_callable_identities_follow_visibility_staticness_and_invoke_policy()
    {
        fn set_method_visibility(
            generator: &mut CGenerator,
            class_name: &str,
            method_name: &str,
            visibility: ClassVisibility,
        ) {
            let method_key = CGenerator::declared_method_key(method_name);
            let method = generator
                .declared_classes
                .get_mut(&CGenerator::declared_class_key(class_name))
                .expect("test class metadata")
                .methods
                .iter_mut()
                .find(|method| CGenerator::declared_method_key(&method.decl.name) == method_key)
                .expect("test method metadata");
            method.visibility = visibility;
        }

        fn set_method_staticness(
            generator: &mut CGenerator,
            class_name: &str,
            method_name: &str,
            is_static: bool,
        ) {
            let method_key = CGenerator::declared_method_key(method_name);
            let method = generator
                .declared_classes
                .get_mut(&CGenerator::declared_class_key(class_name))
                .expect("test class metadata")
                .methods
                .iter_mut()
                .find(|method| CGenerator::declared_method_key(&method.decl.name) == method_key)
                .expect("test method metadata");
            method.is_static = is_static;
        }

        fn bind_object_fact(generator: &mut CGenerator, variable: &str, class_name: &str) {
            let class_key = CGenerator::declared_class_key(class_name);
            let class = generator
                .declared_classes
                .get(&class_key)
                .expect("test class metadata");
            generator.native_value_variable_facts.insert(
                variable.to_string(),
                CNativeValueFacts::object(CNativeObjectFacts::for_declared_class(class_key, class))
                    .expect("object facts"),
            );
            generator.variables.insert(
                variable.to_string(),
                CValue::NativeValueHandle(format!("{variable}_handle")),
            );
        }

        let program = crate::parse(concat!(
            "<?php\n",
            "class ExternalCallableProduct {}\n",
            "class PublicExternalCallableFactory {\n",
            "    public function make() { return new ExternalCallableProduct(); }\n",
            "    public static function stat() { return new ExternalCallableProduct(); }\n",
            "}\n",
            "class HiddenExternalCallableFactory {\n",
            "    public function make() { return new ExternalCallableProduct(); }\n",
            "    public static function stat() { return new ExternalCallableProduct(); }\n",
            "}\n",
            "class PublicInvokeExternalCallableFactory {\n",
            "    public function __invoke() { return new ExternalCallableProduct(); }\n",
            "}\n",
            "class HiddenInvokeExternalCallableFactory {\n",
            "    public function __invoke() { return new ExternalCallableProduct(); }\n",
            "}\n",
            "class StaticInvokeExternalCallableFactory {\n",
            "    public function __invoke() { return new ExternalCallableProduct(); }\n",
            "}\n",
        ))
        .unwrap();
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            uses_native_value_clone: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .unwrap();
        generator.emit_declared_class_method_definitions().unwrap();

        let span = test_span();
        let public_static_string_call = Expr::DynamicCall {
            callee: Box::new(Expr::String(
                "PublicExternalCallableFactory::stat".to_string(),
                span,
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&public_static_string_call),
            "ExternalCallableProduct",
        );

        let public_static_array_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::String("PublicExternalCallableFactory".to_string(), span),
                Expr::String("stat".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&public_static_array_call),
            "ExternalCallableProduct",
        );

        let class_string_to_instance_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::String("PublicExternalCallableFactory".to_string(), span),
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&class_string_to_instance_call)
                .is_none(),
            "class-string callable arrays must not publish facts for instance methods"
        );
        let method_string_to_instance_call = Expr::DynamicCall {
            callee: Box::new(Expr::String(
                "PublicExternalCallableFactory::make".to_string(),
                span,
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&method_string_to_instance_call)
                .is_none(),
            "class-method strings must not publish facts for instance methods"
        );

        let public_object_instance_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::New {
                    class_name: NewClassName::Named("PublicExternalCallableFactory".to_string()),
                    args: Vec::new(),
                    span,
                },
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&public_object_instance_call),
            "ExternalCallableProduct",
        );

        let public_object_static_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::New {
                    class_name: NewClassName::Named("PublicExternalCallableFactory".to_string()),
                    args: Vec::new(),
                    span,
                },
                Expr::String("stat".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&public_object_static_call),
            "ExternalCallableProduct",
        );

        set_method_visibility(
            &mut generator,
            "HiddenExternalCallableFactory",
            "make",
            ClassVisibility::Protected,
        );
        set_method_visibility(
            &mut generator,
            "HiddenExternalCallableFactory",
            "stat",
            ClassVisibility::Private,
        );

        let hidden_class_string_static_call = Expr::DynamicCall {
            callee: Box::new(Expr::String(
                "HiddenExternalCallableFactory::stat".to_string(),
                span,
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&hidden_class_string_static_call)
                .is_none(),
            "class-method strings must not publish facts for non-public static methods"
        );

        let hidden_object_instance_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::New {
                    class_name: NewClassName::Named("HiddenExternalCallableFactory".to_string()),
                    args: Vec::new(),
                    span,
                },
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&hidden_object_instance_call)
                .is_none(),
            "object receiver callable arrays must not publish facts for non-public instance methods"
        );

        let hidden_object_static_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::New {
                    class_name: NewClassName::Named("HiddenExternalCallableFactory".to_string()),
                    args: Vec::new(),
                    span,
                },
                Expr::String("stat".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&hidden_object_static_call)
                .is_none(),
            "object receiver callable arrays must not publish facts for non-public static methods"
        );

        bind_object_fact(
            &mut generator,
            "public_invokable",
            "PublicInvokeExternalCallableFactory",
        );
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&Expr::DynamicCall {
                callee: Box::new(test_variable_expr("public_invokable")),
                args: Vec::new(),
                span,
            }),
            "ExternalCallableProduct",
        );
        let public_invoke_contract = generator
            .callable_object_source_call_signature_contract(
                &test_variable_expr("public_invokable"),
                0,
            )
            .expect("public __invoke should expose the callable-object source-call boundary");
        assert_eq!(
            public_invoke_contract.availability,
            NativeMethodStaticSignatureAvailability::Known(CScopedCallableStringSignature {
                fixed_param_by_reference: Vec::new(),
                returns_by_reference: false,
            })
        );

        set_method_visibility(
            &mut generator,
            "HiddenInvokeExternalCallableFactory",
            "__invoke",
            ClassVisibility::Private,
        );
        bind_object_fact(
            &mut generator,
            "hidden_invokable",
            "HiddenInvokeExternalCallableFactory",
        );
        assert!(
            generator
                .native_value_facts_for_expr(&Expr::DynamicCall {
                    callee: Box::new(test_variable_expr("hidden_invokable")),
                    args: Vec::new(),
                    span,
                })
                .is_none(),
            "object callable identities must not publish facts for private __invoke metadata"
        );
        let hidden_invoke_contract = generator
            .callable_object_source_call_signature_contract(
                &test_variable_expr("hidden_invokable"),
                0,
            )
            .expect("private __invoke should still route to runtime rejection");
        assert!(matches!(
            hidden_invoke_contract.availability,
            NativeMethodStaticSignatureAvailability::RuntimeFallback(_)
        ));

        set_method_staticness(
            &mut generator,
            "StaticInvokeExternalCallableFactory",
            "__invoke",
            true,
        );
        bind_object_fact(
            &mut generator,
            "static_invokable",
            "StaticInvokeExternalCallableFactory",
        );
        assert!(
            generator
                .native_value_facts_for_expr(&Expr::DynamicCall {
                    callee: Box::new(test_variable_expr("static_invokable")),
                    args: Vec::new(),
                    span,
                })
                .is_none(),
            "object callable identities must not publish facts for static __invoke metadata"
        );
        let static_invoke_contract = generator
            .callable_object_source_call_signature_contract(
                &test_variable_expr("static_invokable"),
                0,
            )
            .expect("static __invoke should still route to runtime rejection");
        assert!(matches!(
            static_invoke_contract.availability,
            NativeMethodStaticSignatureAvailability::RuntimeFallback(_)
        ));
    }

    #[test]
    fn descriptor_closure_summaries_resolve_through_callable_identities_by_arity_and_result_kind() {
        let mut generator = CGenerator::default();
        let variadic_identity = CNativeCallableIdentity::DescriptorClosure {
            closure_key: "phpc_closure_frame_variadic".to_string(),
        };
        let exactly_two_identity = CNativeCallableIdentity::DescriptorClosure {
            closure_key: "phpc_closure_frame_two".to_string(),
        };
        let reference_identity = CNativeCallableIdentity::DescriptorClosure {
            closure_key: "phpc_closure_frame_reference".to_string(),
        };

        generator.native_descriptor_closure_return_summaries.insert(
            "phpc_closure_frame_variadic".to_string(),
            test_descriptor_closure_summary(
                vec![test_param(false, true)],
                CNativeCallableResultKind::NativeValue,
                Some(test_native_object_facts("box_one", "arrayaccess")),
            ),
        );
        generator.native_descriptor_closure_return_summaries.insert(
            "phpc_closure_frame_two".to_string(),
            test_descriptor_closure_summary(
                vec![test_param(false, false), test_param(false, false)],
                CNativeCallableResultKind::NativeValue,
                Some(test_native_object_facts("box_two", "arrayaccess")),
            ),
        );
        generator.native_descriptor_closure_return_summaries.insert(
            "phpc_closure_frame_reference".to_string(),
            test_descriptor_closure_summary(
                Vec::new(),
                CNativeCallableResultKind::Reference,
                Some(test_native_object_facts("box_reference", "arrayaccess")),
            ),
        );

        let one_arg_facts = generator
            .native_value_facts_for_callable_identities(vec![variadic_identity.clone()], 1)
            .expect("variadic descriptor closure accepts one argument");
        assert!(one_arg_facts
            .object
            .as_ref()
            .expect("object facts")
            .declared_class_keys
            .contains("box_one"));

        assert!(
            generator
                .native_value_facts_for_callable_identities(
                    HashSet::from([variadic_identity.clone(), exactly_two_identity.clone()]),
                    1,
                )
                .is_none(),
            "mixed callable identity sets with an arity-incompatible target should not publish facts"
        );

        let two_arg_facts = generator
            .native_value_facts_for_callable_identities(
                HashSet::from([variadic_identity, exactly_two_identity]),
                2,
            )
            .expect("both descriptor closures accept two arguments");
        let object = two_arg_facts.object.as_ref().expect("object facts");
        assert!(object.declared_class_keys.is_empty());
        assert!(object.implemented_interface_keys.contains("arrayaccess"));

        assert!(
            generator
                .native_value_facts_for_callable_identities(vec![reference_identity], 0)
                .is_none(),
            "by-reference descriptor closures should not publish value-return facts"
        );
    }

    #[test]
    fn descriptor_closure_callable_identities_drive_dynamic_call_facts_across_variable_surfaces() {
        let mut generator = CGenerator::default();
        let identity = CNativeCallableIdentity::DescriptorClosure {
            closure_key: "phpc_closure_frame_return_box".to_string(),
        };
        generator.native_descriptor_closure_return_summaries.insert(
            "phpc_closure_frame_return_box".to_string(),
            test_descriptor_closure_summary(
                Vec::new(),
                CNativeCallableResultKind::NativeValue,
                Some(test_native_object_facts("box", "arrayaccess")),
            ),
        );
        generator
            .native_callable_value_identities
            .insert("closure_handle".to_string(), HashSet::from([identity]));

        generator.store_native_value_result_variable_with_native_value_facts(
            "callback",
            CNativeValueMaterialization {
                handle: "closure_handle".to_string(),
                cleanup_after_use: Vec::new(),
            },
            None,
        );

        let span = test_span();
        let variable_call = Expr::DynamicCall {
            callee: Box::new(test_variable_expr("callback")),
            args: Vec::new(),
            span,
        };
        assert!(generator
            .native_value_facts_for_expr(&variable_call)
            .expect("descriptor closure dynamic call facts")
            .has_definite_native_object_interface("arrayaccess"));

        let copied = generator
            .variables
            .get("callback")
            .expect("callback variable was stored")
            .clone();
        generator.store_variable_value("copied_callback", copied);
        let copied_call = Expr::DynamicCall {
            callee: Box::new(test_variable_expr("copied_callback")),
            args: Vec::new(),
            span,
        };
        assert!(generator
            .native_value_facts_for_expr(&copied_call)
            .expect("copied descriptor closure dynamic call facts")
            .has_definite_native_object_interface("arrayaccess"));
    }

    #[test]
    fn descriptor_closure_reference_return_identities_select_reference_source_carriers() {
        let mut generator = CGenerator::default();
        let identity = CNativeCallableIdentity::DescriptorClosure {
            closure_key: "phpc_closure_frame_reference".to_string(),
        };
        generator.native_descriptor_closure_return_summaries.insert(
            "phpc_closure_frame_reference".to_string(),
            test_descriptor_closure_summary(
                vec![test_param(true, false)],
                CNativeCallableResultKind::Reference,
                None,
            ),
        );
        generator
            .native_callable_value_identities
            .insert("closure_handle".to_string(), HashSet::from([identity]));
        generator.store_native_value_result_variable(
            "callback",
            CNativeValueMaterialization {
                handle: "closure_handle".to_string(),
                cleanup_after_use: Vec::new(),
            },
        );

        let span = test_span();
        let callee = test_variable_expr("callback");
        let args = vec![test_variable_expr("slot")];
        assert!(
            generator
                .source_call_reference_signature_for_dynamic_call(&callee, &args)
                .is_some(),
            "descriptor closure reference-return identities should publish reference-call eligibility"
        );
        assert!(
            generator.dynamic_call_has_only_reference_returning_descriptor_closure_identities(
                &callee, &args,
            ),
            "descriptor closure reference-return identities should select the closure carrier path"
        );

        let carrier = generator
            .native_source_call_carrier(
                NativeInvokeResultTarget::ClosureArgumentHandle,
                NativeSourceCallResultConsumer::Reference,
                span,
            )
            .expect("descriptor closure reference carrier should select");
        assert_eq!(
            carrier.result,
            NativeSourceCallResultReturn::ReferenceHandle
        );
        assert_eq!(
            carrier.invoke_helper.name,
            "phpc_native_closure_invoke_reference_with_diagnostic_and_free_arguments"
        );
        assert_eq!(carrier.diagnostic_result_converter, None);
    }

    #[test]
    fn dynamic_callable_identities_drive_return_facts_for_strings_and_invokable_objects() {
        let program = crate::parse(concat!(
            "<?php\n",
            "class StringFactBag implements ArrayAccess {\n",
            "    public function offsetGet($offset) { return \"S\"; }\n",
            "    public function offsetExists($offset) { return true; }\n",
            "    public function offsetSet($offset, $value) { return null; }\n",
            "    public function offsetUnset($offset) { return null; }\n",
            "}\n",
            "class AltStringFactBag implements ArrayAccess {\n",
            "    public function offsetGet($offset) { return \"A\"; }\n",
            "    public function offsetExists($offset) { return true; }\n",
            "    public function offsetSet($offset, $value) { return null; }\n",
            "    public function offsetUnset($offset) { return null; }\n",
            "}\n",
            "function make_string_fact_bag() { return new StringFactBag(); }\n",
            "function make_alt_string_fact_bag() { return new AltStringFactBag(); }\n",
            "class StaticStringFactFactory {\n",
            "    public static function make() { return new StringFactBag(); }\n",
            "}\n",
            "class InvokeStringFactFactory {\n",
            "    public function __invoke() { return new StringFactBag(); }\n",
            "}\n",
            "class ChildInvokeStringFactFactory extends InvokeStringFactFactory {}\n",
        ))
        .unwrap();
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            uses_native_value_clone: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .unwrap();
        generator
            .register_top_level_user_functions(&program.statements)
            .unwrap();
        generator.emit_declared_class_method_definitions().unwrap();
        generator
            .emit_registered_user_function_definitions()
            .unwrap();

        let span = test_span();
        generator.variables.insert(
            "function_callback".to_string(),
            CValue::String("make_string_fact_bag".to_string()),
        );
        assert!(generator
            .native_value_facts_for_expr(&Expr::DynamicCall {
                callee: Box::new(test_variable_expr("function_callback")),
                args: Vec::new(),
                span,
            })
            .expect("generated-function string callable facts")
            .has_definite_native_object_interface("arrayaccess"));

        generator.known_strings.insert(
            "string_callable_selector".to_string(),
            KnownString::from_values([
                "make_string_fact_bag".to_string(),
                "make_alt_string_fact_bag".to_string(),
            ])
            .expect("known string callable set"),
        );
        generator.variables.insert(
            "branched_function_callback".to_string(),
            CValue::StringExpr("string_callable_selector".to_string()),
        );
        let branched_facts = generator
            .native_value_facts_for_expr(&Expr::DynamicCall {
                callee: Box::new(test_variable_expr("branched_function_callback")),
                args: Vec::new(),
                span,
            })
            .expect("branched generated-function string callable facts");
        assert!(branched_facts.has_definite_native_object_interface("arrayaccess"));
        assert!(
            branched_facts
                .object
                .as_ref()
                .expect("object facts")
                .declared_class_keys
                .is_empty(),
            "branched string callables should intersect facts across possible identities"
        );

        generator.variables.insert(
            "static_method_callback".to_string(),
            CValue::String("StaticStringFactFactory::make".to_string()),
        );
        assert!(generator
            .native_value_facts_for_expr(&Expr::DynamicCall {
                callee: Box::new(test_variable_expr("static_method_callback")),
                args: Vec::new(),
                span,
            })
            .expect("declared static-method string callable facts")
            .has_definite_native_object_interface("arrayaccess"));

        let child_class = generator
            .declared_classes
            .get(&CGenerator::declared_class_key(
                "ChildInvokeStringFactFactory",
            ))
            .expect("child invokable class metadata");
        generator.native_value_variable_facts.insert(
            "invokable".to_string(),
            CNativeValueFacts::object(CNativeObjectFacts::for_declared_class(
                CGenerator::declared_class_key("ChildInvokeStringFactFactory"),
                child_class,
            ))
            .expect("invokable object facts"),
        );
        generator.variables.insert(
            "invokable".to_string(),
            CValue::NativeValueHandle("invokable_handle".to_string()),
        );
        assert!(generator
            .native_value_facts_for_expr(&Expr::DynamicCall {
                callee: Box::new(test_variable_expr("invokable")),
                args: Vec::new(),
                span,
            })
            .expect("inherited __invoke callable facts")
            .has_definite_native_object_interface("arrayaccess"));
    }

    #[test]
    fn callable_object_source_call_contract_uses_invoke_metadata_for_argument_binding() {
        let program = crate::parse(concat!(
            "<?php\n",
            "class CallableObjectContractBase {\n",
            "    public function __invoke($first, &$slot, $tail = \"D\", ...$rest) { return $first; }\n",
            "}\n",
            "class CallableObjectContractChild extends CallableObjectContractBase {}\n",
        ))
        .unwrap();
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            uses_native_value_clone: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .unwrap();
        generator.emit_declared_class_method_definitions().unwrap();

        let base_class = generator
            .declared_classes
            .get(&CGenerator::declared_class_key(
                "CallableObjectContractBase",
            ))
            .expect("base test class metadata")
            .clone();
        let mut static_class = base_class.clone();
        static_class.name = "CallableObjectContractStatic".to_string();
        static_class.parent_key = None;
        static_class.methods[0].is_static = true;
        let static_key = CGenerator::declared_class_key(&static_class.name);
        generator
            .declared_classes
            .insert(static_key.clone(), static_class);
        generator.declared_class_order.push(static_key);

        let mut missing_class = base_class;
        missing_class.name = "CallableObjectContractMissing".to_string();
        missing_class.parent_key = None;
        missing_class.methods.clear();
        let missing_key = CGenerator::declared_class_key(&missing_class.name);
        generator
            .declared_classes
            .insert(missing_key.clone(), missing_class);
        generator.declared_class_order.push(missing_key);

        for (variable, class_name) in [
            ("callable", "CallableObjectContractChild"),
            ("static_invoke", "CallableObjectContractStatic"),
            ("missing", "CallableObjectContractMissing"),
        ] {
            let class_key = CGenerator::declared_class_key(class_name);
            let class = generator
                .declared_classes
                .get(&class_key)
                .expect("test class metadata");
            generator.native_value_variable_facts.insert(
                variable.to_string(),
                CNativeValueFacts::object(CNativeObjectFacts::for_declared_class(class_key, class))
                    .expect("object facts"),
            );
            generator.variables.insert(
                variable.to_string(),
                CValue::NativeValueHandle(format!("{variable}_handle")),
            );
        }

        let contract = generator
            .callable_object_source_call_signature_contract(&test_variable_expr("callable"), 3)
            .expect("known inherited __invoke should expose a source-call contract");
        assert_eq!(
            contract.availability,
            NativeMethodStaticSignatureAvailability::Known(CScopedCallableStringSignature {
                fixed_param_by_reference: vec![false, true, false],
                returns_by_reference: false,
            })
        );
        match contract.argument_strategy {
            NativeMethodStaticSourceCallArgumentStrategy::Frame(plan) => {
                assert_eq!(plan.params[0].name, "first");
                assert_eq!(plan.params[1].name, "slot");
                assert!(plan.params[1].by_reference);
                assert_eq!(plan.params[2].name, "tail");
                assert!(plan.params[3].is_variadic);
            }
            other => panic!("expected frame argument binding plan, got {other:?}"),
        }

        let static_contract = generator
            .callable_object_source_call_signature_contract(&test_variable_expr("static_invoke"), 1)
            .expect("malformed __invoke metadata should still route to runtime rejection");
        assert!(matches!(
            static_contract.availability,
            NativeMethodStaticSignatureAvailability::RuntimeFallback(_)
        ));
        assert!(generator
            .callable_object_source_call_signature_contract(&test_variable_expr("missing"), 0)
            .is_none());
    }

    #[test]
    fn callable_array_identities_drive_dynamic_call_facts_for_static_and_object_methods() {
        let program = crate::parse(concat!(
            "<?php\n",
            "class CallableArrayProduct {}\n",
            "class CallableArrayStaticFactory {\n",
            "    public static function make() { return new CallableArrayProduct(); }\n",
            "    public static function needs($value) { return new CallableArrayProduct(); }\n",
            "}\n",
            "class CallableArrayBaseFactory {\n",
            "    public function make() { return new CallableArrayProduct(); }\n",
            "}\n",
            "class CallableArrayChildFactory extends CallableArrayBaseFactory {}\n",
            "class CallableArrayMissingFactory {}\n",
        ))
        .unwrap();
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            uses_native_value_clone: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .unwrap();
        generator.emit_declared_class_method_definitions().unwrap();

        let span = test_span();
        let static_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::String("CallableArrayStaticFactory".to_string(), span),
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&static_call),
            "CallableArrayProduct",
        );

        let inherited_object_call = Expr::DynamicCall {
            callee: Box::new(keyed_callable_array_expr(
                Expr::New {
                    class_name: NewClassName::Named("CallableArrayChildFactory".to_string()),
                    args: Vec::new(),
                    span,
                },
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert_native_object_fact_contains_class(
            generator.native_value_facts_for_expr(&inherited_object_call),
            "CallableArrayProduct",
        );

        let arity_mismatch = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                Expr::String("CallableArrayStaticFactory".to_string(), span),
                Expr::String("needs".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&arity_mismatch)
                .is_none(),
            "callable-array identities should still respect frame arity"
        );

        let mut mixed_object_facts = CNativeObjectFacts::for_declared_class(
            CGenerator::declared_class_key("CallableArrayChildFactory"),
            generator
                .declared_classes
                .get(&CGenerator::declared_class_key("CallableArrayChildFactory"))
                .expect("child class"),
        );
        mixed_object_facts
            .declared_class_keys
            .insert(CGenerator::declared_class_key(
                "CallableArrayMissingFactory",
            ));
        generator.native_value_variable_facts.insert(
            "maybe_factory".to_string(),
            CNativeValueFacts::object(mixed_object_facts).expect("mixed object facts"),
        );
        generator.variables.insert(
            "maybe_factory".to_string(),
            CValue::NativeValueHandle("maybe_factory_handle".to_string()),
        );
        let mixed_receiver_call = Expr::DynamicCall {
            callee: Box::new(callable_array_expr(
                test_variable_expr("maybe_factory"),
                Expr::String("make".to_string(), span),
            )),
            args: Vec::new(),
            span,
        };
        assert!(
            generator
                .native_value_facts_for_expr(&mixed_receiver_call)
                .is_none(),
            "callable-array object receiver facts should be withheld if any possible receiver lacks the method"
        );
    }

    #[test]
    fn callable_array_source_call_contracts_drive_named_binding_and_magic_keys() {
        let program = crate::parse(concat!(
            "<?php\n",
            "class CallableArrayArgumentContract {\n",
            "    public static function stat($first, &$slot, $third = \"D\") { return $third; }\n",
            "    public function inst($first, &$slot, $third = \"D\") { return $third; }\n",
            "}\n",
            "class CallableArrayArgumentMagic {\n",
            "    public function __call($name, $args) { return $args; }\n",
            "    public static function __callStatic($name, $args) { return $args; }\n",
            "}\n",
        ))
        .expect("callable-array argument contract fixture parses");
        let mut generator = CGenerator {
            uses_native_string_helpers: true,
            ..CGenerator::default()
        };
        generator
            .register_top_level_declared_classes(&program.statements)
            .expect("callable-array classes register");
        generator
            .emit_declared_class_method_definitions()
            .expect("callable-array method frames emit");

        let span = test_span();
        let args = vec![
            Expr::NamedArgument {
                name: "third".to_string(),
                expr: Box::new(Expr::String("T".to_string(), span)),
                span,
            },
            Expr::NamedArgument {
                name: "first".to_string(),
                expr: Box::new(Expr::String("F".to_string(), span)),
                span,
            },
            Expr::NamedArgument {
                name: "slot".to_string(),
                expr: Box::new(test_variable_expr("slot")),
                span,
            },
        ];

        let static_contract = generator
            .callable_value_source_call_signature_contract(
                &callable_array_expr(
                    Expr::ClassNameConstant {
                        class_name: "CallableArrayArgumentContract".to_string(),
                        span,
                    },
                    Expr::String("stat".to_string(), span),
                ),
                args.len(),
            )
            .expect("class-string callable array should produce a static source-call contract");
        assert_eq!(
            static_contract.availability,
            NativeMethodStaticSignatureAvailability::Known(CScopedCallableStringSignature {
                fixed_param_by_reference: vec![false, true, false],
                returns_by_reference: false,
            })
        );
        assert!(matches!(
            static_contract.argument_strategy,
            NativeMethodStaticSourceCallArgumentStrategy::Frame(_)
        ));

        let object_contract = generator
            .callable_value_source_call_signature_contract(
                &callable_array_expr(
                    Expr::New {
                        class_name: NewClassName::Named(
                            "CallableArrayArgumentContract".to_string(),
                        ),
                        args: Vec::new(),
                        span,
                    },
                    Expr::String("inst".to_string(), span),
                ),
                args.len(),
            )
            .expect("object callable array should produce a receiver source-call contract");
        assert_eq!(
            object_contract.availability,
            NativeMethodStaticSignatureAvailability::Known(CScopedCallableStringSignature {
                fixed_param_by_reference: vec![false, true, false],
                returns_by_reference: false,
            })
        );

        let class_key = CGenerator::declared_class_key("CallableArrayArgumentContract");
        let class = generator
            .declared_classes
            .get(&class_key)
            .expect("contract class is registered");
        generator.native_value_variable_facts.insert(
            "object".to_string(),
            CNativeValueFacts::object(CNativeObjectFacts::for_declared_class(class_key, class))
                .expect("declared class object facts"),
        );
        let variable_object_contract = generator
            .callable_value_source_call_signature_contract(
                &callable_array_expr(
                    test_variable_expr("object"),
                    Expr::String("inst".to_string(), span),
                ),
                args.len(),
            )
            .expect(
                "variable object callable array should produce a receiver source-call contract",
            );
        assert_eq!(
            variable_object_contract.availability,
            NativeMethodStaticSignatureAvailability::Known(CScopedCallableStringSignature {
                fixed_param_by_reference: vec![false, true, false],
                returns_by_reference: false,
            })
        );

        let receiver_magic = generator
            .callable_value_source_call_signature_contract(
                &callable_array_expr(
                    Expr::New {
                        class_name: NewClassName::Named("CallableArrayArgumentMagic".to_string()),
                        args: Vec::new(),
                        span,
                    },
                    Expr::String("missing".to_string(), span),
                ),
                args.len(),
            )
            .expect("missing object callable array should preserve magic fallback contract");
        assert!(receiver_magic.preserves_named_source_keys_for_magic_args());

        let static_magic = generator
            .callable_value_source_call_signature_contract(
                &callable_array_expr(
                    Expr::ClassNameConstant {
                        class_name: "CallableArrayArgumentMagic".to_string(),
                        span,
                    },
                    Expr::String("missingStatic".to_string(), span),
                ),
                args.len(),
            )
            .expect("missing static callable array should preserve __callStatic contract");
        assert!(static_magic.preserves_named_source_keys_for_magic_args());

        assert!(
            generator
                .callable_value_source_call_signature_contract(
                    &callable_array_expr(
                        Expr::String("CallableArrayArgumentContract".to_string(), span),
                        Expr::String("missing".to_string(), span),
                    ),
                    args.len(),
                )
                .is_none(),
            "unknown callable-array methods without magic must stay at the runtime diagnostic boundary"
        );
    }

