    #[test]
    fn callable_array_identities_clear_across_array_owner_mutations() {
        fn prepared_generator() -> (CGenerator, Span, Expr, Expr) {
            let program = crate::parse(concat!(
                "<?php\n",
                "class CallableArrayMutationProduct {}\n",
                "class CallableArrayMutationFactory {\n",
                "    public static function make() { return new CallableArrayMutationProduct(); }\n",
                "}\n",
            ))
            .unwrap();
            let mut generator = CGenerator {
                uses_native_string_helpers: true,
                uses_native_value_clone: true,
                ..CGenerator::default()
            };
            generator
                .register_top_level_declared_classes(&program.statements)
                .unwrap();
            generator.emit_declared_class_method_definitions().unwrap();

            let span = test_span();
            let callable = callable_array_expr(
                Expr::String("CallableArrayMutationFactory".to_string(), span),
                Expr::String("make".to_string(), span),
            );
            generator
                .emit_assignment(
                    &AssignTarget::Variable {
                        name: "callback".to_string(),
                        span,
                    },
                    &callable,
                )
                .unwrap();
            let dynamic_call = Expr::DynamicCall {
                callee: Box::new(test_variable_expr("callback")),
                args: Vec::new(),
                span,
            };
            assert_native_object_fact_contains_class(
                generator.native_value_facts_for_expr(&dynamic_call),
                "CallableArrayMutationProduct",
            );
            (generator, span, callable, dynamic_call)
        }

        let (mut generator, span, _callable, dynamic_call) = prepared_generator();
        generator
            .emit_assignment(
                &AssignTarget::ArrayIndex {
                    name: "callback".to_string(),
                    index: Some(Expr::Int(1, span)),
                    span,
                },
                &Expr::String("other".to_string(), span),
            )
            .unwrap();
        assert!(
            generator
                .native_value_facts_for_expr(&dynamic_call)
                .is_none(),
            "direct array element writes should clear callable-array identities"
        );

        let (mut generator, span, _callable, dynamic_call) = prepared_generator();
        generator
            .emit_assignment(
                &AssignTarget::ArrayIndex {
                    name: "callback".to_string(),
                    index: None,
                    span,
                },
                &Expr::String("extra".to_string(), span),
            )
            .unwrap();
        assert!(
            generator
                .native_value_facts_for_expr(&dynamic_call)
                .is_none(),
            "array appends should clear callable-array identities"
        );

        let (mut generator, span, _callable, dynamic_call) = prepared_generator();
        generator
            .emit_unset_array_index("callback", &Expr::Int(0, span), span)
            .unwrap();
        assert!(
            generator
                .native_value_facts_for_expr(&dynamic_call)
                .is_none(),
            "array offset unsets should clear callable-array identities"
        );
    }

    fn property_offset_with_error_control_receiver() -> Expr {
        Expr::Index {
            target: Box::new(Expr::ErrorControl {
                expr: Box::new(Expr::Property {
                    target: Box::new(variable("box", 6)),
                    property: "items".to_string(),
                    span: span(10),
                }),
                span: span(5),
            }),
            index: Box::new(Expr::Int(0, span(18))),
            span: span(17),
        }
    }

    fn property_offset_with_error_control_expression() -> Expr {
        Expr::ErrorControl {
            expr: Box::new(Expr::Index {
                target: Box::new(Expr::Property {
                    target: Box::new(variable("box", 7)),
                    property: "items".to_string(),
                    span: span(11),
                }),
                index: Box::new(Expr::Int(0, span(19))),
                span: span(18),
            }),
            span: span(5),
        }
    }

    #[test]
    fn native_object_arrayaccess_error_control_receiver_classification_is_shared() {
        let receiver_error_control = property_offset_with_error_control_receiver();
        let expression_error_control = property_offset_with_error_control_expression();

        for (expr, operation, expected_result) in [
            (
                &receiver_error_control,
                NativeObjectArrayAccessOperation::Read,
                NativeObjectPropertyOperationResultKind::Value,
            ),
            (
                &receiver_error_control,
                NativeObjectArrayAccessOperation::NullCoalesceRead,
                NativeObjectPropertyOperationResultKind::Value,
            ),
            (
                &receiver_error_control,
                NativeObjectArrayAccessOperation::Isset,
                NativeObjectPropertyOperationResultKind::Bool,
            ),
            (
                &receiver_error_control,
                NativeObjectArrayAccessOperation::Empty,
                NativeObjectPropertyOperationResultKind::Bool,
            ),
            (
                &expression_error_control,
                NativeObjectArrayAccessOperation::Read,
                NativeObjectPropertyOperationResultKind::Value,
            ),
            (
                &expression_error_control,
                NativeObjectArrayAccessOperation::Empty,
                NativeObjectPropertyOperationResultKind::Bool,
            ),
        ] {
            let result = native_object_array_access_operation_result_from_expr(expr, operation)
                .expect("object-offset ArrayAccess expression should classify");

            assert_eq!(result.operation, operation);
            assert_eq!(
                result.receiver_kind,
                NativeObjectArrayAccessReceiverKind::ErrorControlReceiver
            );
            assert_eq!(result.span, span(5));
            assert_eq!(result.result_kind(), expected_result);
            assert_eq!(result.llvm_rejection(), LLVM_ERROR_CONTROL_REJECTION);
            assert_eq!(
                result.assembly_rejection(),
                ASSEMBLY_ERROR_CONTROL_REJECTION
            );
        }

        let non_error_control = Expr::Index {
            target: Box::new(Expr::DynamicProperty {
                target: Box::new(variable("box", 6)),
                property: Box::new(Expr::String("items".to_string(), span(11))),
                span: span(10),
            }),
            index: Box::new(Expr::String("key".to_string(), span(20))),
            span: span(19),
        };
        let result = native_object_array_access_operation_result_from_expr(
            &non_error_control,
            NativeObjectArrayAccessOperation::Isset,
        )
        .expect("dynamic property object-offset ArrayAccess expression should classify");
        assert_eq!(
            result.receiver_kind,
            NativeObjectArrayAccessReceiverKind::PropertyValue
        );
        assert_eq!(
            result.result_kind(),
            NativeObjectPropertyOperationResultKind::Bool
        );
        assert_eq!(result.llvm_rejection(), LLVM_ARRAY_ACCESS_REJECTION);
        assert_eq!(result.assembly_rejection(), ASSEMBLY_ARRAY_ACCESS_REJECTION);
    }

    #[test]
    fn native_object_arrayaccess_write_operation_classification_covers_write_families() {
        let direct_property_write = AssignTarget::ObjectPropertyArrayIndex {
            object: "box".to_string(),
            property: "items".to_string(),
            indices: vec![Expr::Int(0, span(18))],
            span: span(10),
        };
        let direct_property_append = AssignTarget::ObjectPropertyArrayAppend {
            object: "box".to_string(),
            property: "items".to_string(),
            indices: vec![],
            suffix_indices: vec![],
            span: span(11),
        };
        let dynamic_property_write = AssignTarget::DynamicObjectPropertyArrayIndex {
            object: "box".to_string(),
            property: variable("slot", 12),
            indices: vec![Expr::String("key".to_string(), span(20))],
            span: span(13),
        };
        let non_direct_property_write = AssignTarget::NonDirectObjectPropertyArrayIndex {
            holder: Expr::Property {
                target: Box::new(variable("box", 6)),
                property: "child".to_string(),
                span: span(10),
            },
            property: "items".to_string(),
            indices: vec![Expr::Int(1, span(24))],
            span: span(17),
        };
        let call_result_property_write = AssignTarget::NonDirectObjectPropertyArrayIndex {
            holder: Expr::Call {
                name: "make_box".to_string(),
                args: vec![],
                span: span(4),
            },
            property: "items".to_string(),
            indices: vec![Expr::Int(2, span(24))],
            span: span(17),
        };
        let new_result_property_append = AssignTarget::NonDirectObjectPropertyArrayAppend {
            holder: Expr::New {
                class_name: crate::ast::NewClassName::Named("Box".to_string()),
                args: vec![],
                span: span(4),
            },
            property: "items".to_string(),
            indices: vec![],
            suffix_indices: vec![],
            span: span(18),
        };

        for (target, operation, receiver_kind, expected_span) in [
            (
                &direct_property_write,
                NativeObjectArrayAccessOperation::Write,
                NativeObjectArrayAccessReceiverKind::PropertyValue,
                span(10),
            ),
            (
                &direct_property_append,
                NativeObjectArrayAccessOperation::AppendWrite,
                NativeObjectArrayAccessReceiverKind::PropertyValue,
                span(11),
            ),
            (
                &dynamic_property_write,
                NativeObjectArrayAccessOperation::Write,
                NativeObjectArrayAccessReceiverKind::PropertyValue,
                span(13),
            ),
            (
                &non_direct_property_write,
                NativeObjectArrayAccessOperation::Write,
                NativeObjectArrayAccessReceiverKind::PropertyValue,
                span(10),
            ),
            (
                &call_result_property_write,
                NativeObjectArrayAccessOperation::Write,
                NativeObjectArrayAccessReceiverKind::CallResult,
                span(4),
            ),
            (
                &new_result_property_append,
                NativeObjectArrayAccessOperation::AppendWrite,
                NativeObjectArrayAccessReceiverKind::NewObjectResult,
                span(4),
            ),
        ] {
            let result = if operation == NativeObjectArrayAccessOperation::AppendWrite {
                native_object_array_access_assignment_operation_result(target)
            } else {
                native_object_array_access_operation_result_from_assign_target(target, operation)
            }
            .expect("object/property ArrayAccess write target should classify");

            assert_eq!(result.operation, operation);
            assert_eq!(result.receiver_kind, receiver_kind);
            assert_eq!(result.span, expected_span);
        }

        let compound = native_object_array_access_compound_operation_result(&direct_property_write)
            .expect("compound object/property ArrayAccess write should classify");
        assert_eq!(
            compound.operation,
            NativeObjectArrayAccessOperation::CompoundUpdate
        );
        assert_eq!(compound.llvm_rejection(), LLVM_ARRAY_ACCESS_REJECTION);

        let null_coalesce =
            native_object_array_access_null_coalesce_write_operation_result(&direct_property_write)
                .expect("null-coalesce object/property ArrayAccess write should classify");
        assert_eq!(
            null_coalesce.operation,
            NativeObjectArrayAccessOperation::NullCoalesceWrite
        );
        assert_eq!(
            null_coalesce.result_kind(),
            NativeObjectPropertyOperationResultKind::Value
        );

        let direct_unset = UnsetTarget::ObjectPropertyArrayIndex {
            object: "box".to_string(),
            property: "items".to_string(),
            indices: vec![Expr::Int(0, span(18))],
            span: span(10),
        };
        let static_receiver_unset = UnsetTarget::NonDirectDynamicObjectPropertyArrayIndex {
            holder: Expr::StaticProperty {
                class_name: "Registry".to_string(),
                property: "box".to_string(),
                span: span(5),
            },
            property: variable("slot", 16),
            indices: vec![Expr::String("key".to_string(), span(24))],
            span: span(18),
        };

        for (target, receiver_kind, expected_span) in [
            (
                &direct_unset,
                NativeObjectArrayAccessReceiverKind::PropertyValue,
                span(10),
            ),
            (
                &static_receiver_unset,
                NativeObjectArrayAccessReceiverKind::StaticPropertyValue,
                span(5),
            ),
        ] {
            let result = native_object_array_access_unset_operation_result_from_target(target)
                .expect("object/property ArrayAccess unset target should classify");

            assert_eq!(result.operation, NativeObjectArrayAccessOperation::Unset);
            assert_eq!(result.receiver_kind, receiver_kind);
            assert_eq!(result.span, expected_span);
            assert_eq!(
                result.result_kind(),
                NativeObjectPropertyOperationResultKind::Bool
            );
        }
    }

    #[test]
    fn native_object_arrayaccess_error_control_receiver_diagnostics_share_operation_result() {
        let read = property_offset_with_error_control_receiver();
        let null_coalesce = Expr::Binary {
            left: Box::new(read.clone()),
            op: BinaryOp::NullCoalesce,
            right: Box::new(Expr::String("fallback".to_string(), span(26))),
            span: span(24),
        };
        let isset = Expr::Call {
            name: "isset".to_string(),
            args: vec![read.clone()],
            span: span(1),
        };
        let empty = Expr::Call {
            name: "empty".to_string(),
            args: vec![read.clone()],
            span: span(1),
        };

        for expr in [read, null_coalesce, isset, empty] {
            let llvm_error = LlvmGenerator::default()
                .emit_expr(&expr)
                .expect_err("LLVM object-offset ArrayAccess error-control receiver should reject");
            assert_eq!(llvm_error.phase, Phase::Codegen);
            assert_eq!(llvm_error.line, 1);
            assert_eq!(llvm_error.column, 5);
            assert_eq!(llvm_error.message, LLVM_ERROR_CONTROL_REJECTION);

            let assembly_error = CGenerator::default().emit_expr(&expr).expect_err(
                "assembly object-offset ArrayAccess error-control receiver should reject",
            );
            assert_eq!(assembly_error.phase, Phase::Codegen);
            assert_eq!(assembly_error.line, 1);
            assert_eq!(assembly_error.column, 5);
            assert_eq!(assembly_error.message, ASSEMBLY_ERROR_CONTROL_REJECTION);
        }
    }

    #[test]
    fn known_string_truthiness_reuses_runtime_semantics_across_value_families() {
        for value in ["", "0", "00", "0.0", " ", "false"] {
            let known = KnownString::one(value.to_string());
            assert_eq!(
                known_string_truthiness(&known),
                Some(is_php_truthy_string(value)),
                "single known string truthiness for {value:?}",
            );
        }

        let falsey_values =
            KnownString::from_values(["".to_string(), "0".to_string()]).expect("known strings");
        assert_eq!(known_string_truthiness(&falsey_values), Some(false));

        let truthy_values = KnownString::from_values([
            "00".to_string(),
            "0.0".to_string(),
            " ".to_string(),
            "false".to_string(),
        ])
        .expect("known strings");
        assert_eq!(known_string_truthiness(&truthy_values), Some(true));

        let mixed_values =
            KnownString::from_values(["0".to_string(), "00".to_string()]).expect("known strings");
        assert_eq!(known_string_truthiness(&mixed_values), None);
    }

    #[test]
    fn generated_c_string_comparison_safety_uses_shared_pair_classifier() {
        let binary_program = crate::parse(
            r#"<?php
$sum = 1 + 2;
$flag = $sum === 3;
$left = $flag ? "10" : "8foo";
$right = $flag ? "zeta" : "+foo";

echo $left < $right, "\n";
echo ".name" != "-word", "\n";
echo " 10" < "zeta";
"#,
        )
        .expect("parse binary string comparison source");
        let c_source = emit_c_source_for_assembly(&binary_program)
            .expect("known binary string comparison pairs should lower through C fallback");

        assert_known_string_comparison_runtime_boundary(&c_source);

        for source in [
            "<?php\necho \"10\" < \"2\";\n",
            "<?php\necho \" 10\" < \"2\";\n",
            "<?php\necho \"-2\" < \".5\";\n",
            "<?php\necho \".5\" < \"5.\";\n",
        ] {
            let program = crate::parse(source).expect("parse numeric string comparison source");
            let c_source = emit_c_source_for_assembly(&program)
                .expect("known string comparison source should lower through runtime boundary");
            assert_known_string_comparison_runtime_boundary(&c_source);
        }
    }

    fn assert_known_string_comparison_runtime_boundary(c_source: &str) {
        assert!(
            c_source.contains("phpc_native_value_from_string_bytes_with_diagnostic"),
            "known string pairs should materialize through the binary string value boundary:\n{c_source}"
        );
        assert!(
            c_source.contains("phpc_native_value_compare_result"),
            "known string pairs should compare through the shared runtime comparison boundary:\n{c_source}"
        );
    }

    #[test]
    fn c_assembly_fallback_routes_string_results_through_runtime_contract() {
        let program = crate::parse(
            "<?php\n$payload = \"A\\0B\";\necho strrev($payload), \"|\";\necho strtoupper(strtolower(\"MiXeD\")), \"|\";\nprint bin2hex($payload);\n",
        )
        .expect("parse string-result fallback source");
        let c_source = emit_c_source_for_assembly(&program)
            .expect("C assembly fallback should lower string-result operations");

        assert!(
            c_source.contains("phpc_native_value_string_result_operation_with_diagnostic"),
            "C fallback should consume the shared native string-result ABI:\n{c_source}"
        );
        assert!(
            c_source
                .matches(" = phpc_native_value_string_result_operation_with_diagnostic(")
                .count()
                >= 4,
            "direct and nested string-result operations should share the runtime contract:\n{c_source}"
        );
        for tag in [
            NativeStringResultOperation::Reverse as u8,
            NativeStringResultOperation::AsciiLower as u8,
            NativeStringResultOperation::AsciiUpper as u8,
            NativeStringResultOperation::BinToHex as u8,
        ] {
            assert!(
                c_source.contains(&format!(", {tag}, &string_result_diagnostic_")),
                "missing string-result operation tag {tag} in C fallback:\n{c_source}"
            );
        }
        assert!(
            c_source.matches("phpc_native_value_free(").count() >= 4,
            "C fallback should retain cleanup for produced string-result handles:\n{c_source}"
        );
        assert!(
            !c_source.contains(ASSEMBLY_STRING_RESULT_OPERATION_REJECTION),
            "lowerable string-result family should no longer hit the assembly fallback blocker:\n{c_source}"
        );

        if command_available("cc") {
            let asm = cc_assembly_from_c(&c_source)
                .expect("C assembly fallback string-result source should compile to assembly");
            assert!(asm.contains("main"), "{asm}");
        }
    }

    #[test]
    fn c_assembly_fallback_keeps_string_result_arity_boundary() {
        let program = crate::parse("<?php\necho strrev(\"abc\", \"extra\");\n")
            .expect("parse unsupported string-result arity");
        let error = emit_c_source_for_assembly(&program).unwrap_err();

        assert_eq!(error.phase, Phase::Codegen);
        assert_eq!(error.message, ASSEMBLY_STRING_RESULT_OPERATION_REJECTION);
    }

    #[test]
    fn c_assembly_fallback_routes_string_predicates_through_runtime_contract() {
        let program = crate::parse(
            "<?php\n$payload = \"A\\0B\";\necho str_starts_with($payload, \"A\\0\"), \"|\";\necho str_contains(strrev(\"abc\"), \"b\"), \"|\";\necho str_ends_with(42042, 42);\n",
        )
        .expect("parse string-predicate fallback source");
        let c_source = emit_c_source_for_assembly(&program)
            .expect("C assembly fallback should lower string-predicate operations");

        assert!(
            c_source.contains("phpc_native_value_string_predicate_with_diagnostic"),
            "C fallback should consume the shared native string-predicate ABI:\n{c_source}"
        );
        assert_eq!(
            c_source
                .matches(" = phpc_native_value_string_predicate_with_diagnostic(")
                .count(),
            3,
            "predicate family should share one runtime contract across direct and nested operands:\n{c_source}"
        );
        for tag in [
            NativeStringPredicate::StartsWith as u8,
            NativeStringPredicate::Contains as u8,
            NativeStringPredicate::EndsWith as u8,
        ] {
            assert!(
                c_source.contains(&format!(", {tag}, &string_predicate_diagnostic_")),
                "missing string-predicate operation tag {tag} in C fallback:\n{c_source}"
            );
        }
        assert!(
            c_source.contains("phpc_native_value_string_result_operation_with_diagnostic"),
            "nested string-result operands should materialize before predicate dispatch:\n{c_source}"
        );
        assert!(
            !c_source.contains(ASSEMBLY_STRING_PREDICATE_REJECTION),
            "lowerable string-predicate family should no longer hit the assembly fallback blocker:\n{c_source}"
        );

        if command_available("cc") {
            let asm = cc_assembly_from_c(&c_source)
                .expect("C assembly fallback string-predicate source should compile to assembly");
            assert!(asm.contains("main"), "{asm}");
        }
    }

    #[test]
    fn c_assembly_fallback_keeps_string_predicate_arity_boundary() {
        let program = crate::parse("<?php\necho str_contains(\"abc\");\n")
            .expect("parse unsupported string-predicate arity");
        let error = emit_c_source_for_assembly(&program).unwrap_err();

        assert_eq!(error.phase, Phase::Codegen);
        assert_eq!(error.message, ASSEMBLY_STRING_PREDICATE_REJECTION);
    }

